// Must-eat dishes per region, built by tools/build_dishes.py from content/dishes/. Do not edit by hand.
window.DISHES = {
  aachen: [{"id": "aachen-printen", "name": "Aachener Printen", "local": "", "icon": "🍪", "desc": "Spiced, dense gingerbread bars baked in Aachen since the Middle Ages, plain or coated in chocolate. The city's best-known bakery product.", "kw": ["printen"]}, {"id": "aachen-reisfladen", "name": "Öcher Reisfladen", "local": "Aachener Reisfladen", "icon": "🥧", "desc": "Small shortcrust tart filled with sweet rice pudding and often cinnamon. A traditional Aachen bakery treat.", "kw": ["reisfladen"]}, {"id": "aachen-puttes", "name": "Puttes", "local": "Aachener Puttes", "icon": "🌭", "desc": "Aachen's own black pudding, fried and served with onions and potatoes. A hearty old-town staple.", "kw": ["puttes", "blood sausage"]}, {"id": "aachen-doeppekooche", "name": "Döppekooche", "local": "Döppekooche", "icon": "🥔", "desc": "Baked grated-potato casserole with bacon and onion, a rustic dish of the Eifel and Rhineland, eaten with apple sauce.", "kw": ["döppekooche", "dibbekuchen"]}, {"id": "aachen-rubenkraut", "name": "Rübenkraut", "local": "Rübenkraut", "icon": "🍯", "desc": "Thick sugar-beet syrup spread on dark bread, from the sugar-beet fields around Düren and Aachen. The region's answer to honey.", "kw": ["rübenkraut", "beet syrup"]}],
  aalborg: [{"id": "aalborg-skagenrora", "name": "Skagenssalat", "local": "", "icon": "🦐", "desc": "Prawns in a mayonnaise and dill dressing, piled on rye bread or toast. Named after Skagen at the northern tip of Jutland.", "kw": ["skagen", "skagenssalat"]}, {"id": "aalborg-rodspaette", "name": "Stegt rødspætte", "local": "", "icon": "🐟", "desc": "Breaded plaice fried in butter and served with remoulade and lemon. A standard fish lunch on the North Jutland coast.", "kw": ["rødspætte", "plaice"]}, {"id": "aalborg-sild", "name": "Marinated herring", "local": "Marineret sild", "icon": "🐟", "desc": "Herring pickled in vinegar or curry sauce and eaten on rye bread. A fixture of the Danish lunch table and the North Jutland harbours.", "kw": ["sild", "herring"]}, {"id": "aalborg-frikadeller", "name": "Frikadeller", "local": "", "icon": "🍖", "desc": "Pan-fried pork meatballs served with potatoes and red cabbage. The everyday Danish home dish, found in traditional lunch restaurants.", "kw": ["frikadeller"]}, {"id": "aalborg-aalborgakvavit", "name": "Skagen fish plate", "local": "Skagens fiskeret", "icon": "🍽", "desc": "A plate of fried and smoked fish from the Skagen fleet, served with rye bread and remoulade in harbour restaurants.", "kw": ["skagen", "fiskefrikadelle", "fiskeret"]}],
  aarhus: [{"id": "aarhus-brunsviger", "name": "Brunsviger", "local": "", "icon": "🍰", "desc": "Sticky yeast cake with a brown-sugar and butter topping, baked in Aarhus and Funen bakeries and eaten with coffee.", "kw": ["brunsviger"]}, {"id": "aarhus-aeblekage", "name": "Æblekage", "local": "", "icon": "🍎", "desc": "Layers of stewed apple, buttered crumbs and whipped cream. A traditional Danish dessert still served in Jutland cafes.", "kw": ["æblekage"]}, {"id": "aarhus-flaesk", "name": "Stegt flæsk med persillesovs", "local": "", "icon": "🥓", "desc": "Fried pork belly with potatoes and parsley sauce. Voted Denmark's national dish and common on traditional Jutland menus.", "kw": ["stegt flæsk", "persillesovs"]}, {"id": "aarhus-rugbrod", "name": "Rugbrød", "local": "", "icon": "🍞", "desc": "Dense, sour dark rye bread that is the base of Danish lunch, baked in local bakeries and sold by the loaf.", "kw": ["rugbrød"]}, {"id": "aarhus-kanelsnegl", "name": "Kanelsnegl", "local": "", "icon": "🥐", "desc": "Cinnamon swirl pastry baked fresh each morning in Aarhus bakeries, a regular companion to coffee.", "kw": ["kanelsnegl", "cinnamon"]}],
  adana: [{"id": "adana-kebap", "name": "Adana kebabı", "local": "", "icon": "🍢", "desc": "Hand-minced lamb with tail fat and red pepper pressed on wide skewers and grilled over charcoal. The city's famous dish, often eaten with şalgam and onion salad.", "kw": ["adana kebap", "adana kebab"]}, {"id": "adana-sirdan", "name": "Şırdan dolması", "local": "", "icon": "🍖", "desc": "Lamb stomach stuffed with rice and spices, boiled and fried. A classic of old Adana tradition.", "kw": ["şırdan", "sirdan"]}, {"id": "adana-fellah-koftesi", "name": "Fellah köftesi", "local": "", "icon": "🧆", "desc": "A Çukurova dish of bulgur and meat dumplings in a rich tomato and pepper sauce. Served in local lokantas.", "kw": ["fellah köftesi", "fellah"]}, {"id": "adana-bici-bici", "name": "Bici bici", "local": "", "icon": "🍧", "desc": "A cold street dessert of starch jelly in rosewater syrup with crushed ice. A cooling summer speciality of Adana.", "kw": ["bici bici"]}],
  afyon: [{"id": "afyon-ekmek-kadayifi", "name": "Afyon ekmek kadayıfı", "local": "Kaymaklı ekmek kadayıfı", "icon": "🍮", "desc": "Soft bread dessert soaked in syrup and served under a thick spoon of Afyon kaymak. It is geographically registered and counted among the city's best-known sweets.", "kw": ["ekmek kadayıfı", "kaymak"]}, {"id": "afyon-sucuk", "name": "Afyon sucuk", "local": "Afyon sucuğu", "icon": "🌭", "desc": "Spiced beef sausage with a geographical indication, eaten at breakfast, with eggs or in pide. Afyon is one of Türkiye's best-known sucuk towns.", "kw": ["sucuk"]}, {"id": "afyon-hashasli-bukme", "name": "Poppy seed bükme", "local": "Haşhaşlı bükme", "icon": "🥧", "desc": "Layered pastry rolled with poppy seeds, traditionally with a lentil filling, crisp outside and filling inside. Poppy seeds are what set it apart from ordinary börek in Afyon.", "kw": ["bükme", "haşhaş"]}, {"id": "afyon-ilibada", "name": "İlibada dolması", "local": "", "icon": "🥬", "desc": "Leaves of the local ilibada herb wrapped around a filling and cooked slowly in a pot. A regional herb dish found on Afyon family tables.", "kw": ["ilibada"]}, {"id": "afyon-suhut-keskegi", "name": "Şuhut keşkek", "local": "Şuhut keşkeği", "icon": "🍲", "desc": "Göce wheat, chickpeas and meat cooked for hours in an earthen pot, sometimes served with kaymak and a sauce. Named after Şuhut, a district of Afyon.", "kw": ["keşkek", "şuhut"]}],
  amasya: [{"id": "amasya-corek", "name": "Amasya corek", "local": "Amasya çöreği", "icon": "🥐", "desc": "A yeast pastry rolled around a ground poppy-seed paste, with walnut kneaded into the dough and an egg-yolk glaze. Made at home for guests across Amasya.", "kw": ["amasya çöreği", "çörek"]}, {"id": "amasya-topuz-kebabi", "name": "Topuz kebab", "local": "Topuz kebabı", "icon": "🍖", "desc": "Grilled meat served on a mace-shaped iron holder, usually with several kinds of meat, peppers and rice. A celebration dish of Amasya, widely served in Merzifon.", "kw": ["topuz kebabı", "topuz"]}, {"id": "amasya-singir-kebabi", "name": "Singir kebab", "local": "Şıngır kebabı", "icon": "🍆", "desc": "Lamb and salted eggplant rings alternated on skewers and turned by hand over charcoal on a special frame. An Amasya kebab you rarely find elsewhere.", "kw": ["şıngır kebabı", "şıngır"]}, {"id": "amasya-tokat-kebabi", "name": "Tokat kebab", "local": "Tokat kebabı", "icon": "🍢", "desc": "Bone-in lamb with eggplant in a tomato sauce, cooked in the Tokat style. The best-known dish of Tokat, the neighbouring city in this region.", "kw": ["tokat kebabı", "tokat kebab"]}, {"id": "amasya-corum-leblebisi", "name": "Corum leblebi", "local": "Çorum leblebisi", "icon": "🥜", "desc": "Roasted chickpeas cooked over wood fire, sold plain, peppered or sugared. Çorum is Turkey's leblebi town and the snack is sold across its markets.", "kw": ["leblebi", "çorum leblebisi"]}],
  amiens: [{"id": "amiens-macaron", "name": "Amiens macaron", "local": "Macaron d'Amiens", "icon": "🍪", "desc": "A soft, chewy almond and honey cake, nothing like the Parisian meringue sandwich. Baked in Amiens since the Renaissance and sold in local patisseries.", "kw": ["macaron d'amiens", "amiens macaron"]}, {"id": "amiens-ficelle", "name": "Ficelle picarde", "local": "", "icon": "🥞", "desc": "A savoury crêpe rolled around ham and mushrooms, topped with cream and cheese and baked golden. A Picardy classic created in Amiens in the 1950s.", "kw": ["ficelle picarde", "ficelle"]}, {"id": "amiens-pate-canard", "name": "Amiens duck pâté", "local": "Pâté de canard d'Amiens", "icon": "🥧", "desc": "Duck and pork baked in a pastry crust, served cold in slices. Made in Amiens since the 19th century.", "kw": ["pâté de canard", "duck pâté"]}, {"id": "amiens-flamiche", "name": "Flamiche", "local": "Flamiche aux poireaux", "icon": "🥧", "desc": "A leek and cream tart, the Picardy answer to quiche. A staple starter in Amiens and across the Somme.", "kw": ["flamiche", "leek tart"]}, {"id": "amiens-gateau-battu", "name": "Gâteau battu", "local": "", "icon": "🍞", "desc": "A tall, airy egg brioche from Picardy, baked in a tin and eaten for breakfast or with coffee in Amiens bakeries.", "kw": ["gâteau battu", "gateau battu"]}],
  amsterdam: [{"id": "amsterdam-bitterballen", "name": "Bitterballen", "local": "", "icon": "🍢", "desc": "Crisp, deep-fried balls with a molten beef ragout inside, eaten with mustard. The standard bar snack in Amsterdam's brown cafes at borrel hour.", "kw": ["bitterbal"]}, {"id": "amsterdam-poffertjes", "name": "Poffertjes", "local": "", "icon": "🥞", "desc": "Small puffy buckwheat pancakes served hot with butter and icing sugar. A fixture of Amsterdam's street stalls and pancake houses.", "kw": ["poffertjes"]}, {"id": "amsterdam-oliebollen", "name": "Oliebollen", "local": "", "icon": "🍩", "desc": "Deep-fried dough balls with raisins, dusted with sugar. Sold from winter stalls around New Year, and in bakeries much of the year.", "kw": ["oliebol"]}, {"id": "amsterdam-appeltaart", "name": "Dutch apple pie", "local": "Appeltaart", "icon": "🥧", "desc": "Deep, spiced apple pie with a lattice or crumble top, served with whipped cream. The cafes of the Jordaan made it a signature of the city.", "kw": ["appeltaart", "apple pie"]}, {"id": "amsterdam-rijsttafel", "name": "Rijsttafel", "local": "", "icon": "🍛", "desc": "A spread of small Indonesian dishes served around rice, a legacy of colonial ties. Amsterdam has the country's deepest tradition of Indonesian restaurants.", "kw": ["rijsttafel", "indonesian"]}],
  angers: [{"id": "angers-fouee", "name": "Fouée", "local": "", "icon": "🥖", "desc": "Hollow flatbread baked in a wood oven and filled with rillettes, white beans and butter. Saumur's cave restaurants serve them hot by the basket.", "kw": ["fouée", "fouees"]}, {"id": "angers-rillauds", "name": "Rillauds d'Anjou", "local": "", "icon": "🥓", "desc": "Chunks of pork belly slowly cooked and caramelised in lard, eaten warm with mustard. A staple of Anjou butchers and market days.", "kw": ["rillauds", "rillaud"]}, {"id": "angers-cremet-anjou", "name": "Crémet d'Anjou", "local": "", "icon": "🍮", "desc": "Light dessert of whipped cream, whipped egg white and fromage frais, served cold with cream or red fruit. A speciality of Angers and the Maine-et-Loire.", "kw": ["crémet", "cremet"]}, {"id": "angers-quernons-ardoise", "name": "Quernons d'ardoise", "local": "", "icon": "🍫", "desc": "Almond-and-hazelnut nougatine coated in blue-grey chocolate to look like Angers' roof slate. A sweet from Angers confectioners.", "kw": ["quernon", "quernons"]}, {"id": "angers-galipettes", "name": "Galipettes", "local": "", "icon": "🍄", "desc": "Large button mushrooms grown in the tuffeau caves around Saumur, stuffed with rillettes or garlic and herbs, and baked. Eaten in cave restaurants.", "kw": ["galipette", "galipettes"]}],
  ankara: [{"id": "ankara-tava", "name": "Ankara tava", "local": "Ankara tavası", "icon": "🍖", "desc": "Lamb and rice baked slowly in a shallow dish until the top crisps. The city's own celebration dish, found in old lokantas around Ulus.", "kw": ["ankara tava", "tava"]}, {"id": "ankara-kurusu", "name": "Beypazarı kurusu", "local": "", "icon": "🍪", "desc": "Thin, hard twice-baked biscuits from the town of Beypazarı, eaten with tea or crumbled into soup. The best-known local product of the area.", "kw": ["beypazarı", "kurusu"]}, {"id": "ankara-simit", "name": "Ankara simit", "local": "Ankara simidi", "icon": "🥯", "desc": "Sesame-crusted bread ring sold from carts and bakeries across the city. The Ankara version is thinner and crunchier than the Istanbul one.", "kw": ["simit"]}, {"id": "ankara-beypazari-guvec", "name": "Beypazarı güveç", "local": "Beypazarı güveci", "icon": "🍲", "desc": "Meat and vegetables stewed for hours in a sealed clay pot in a wood oven. Beypazarı's old bakeries still cook it the slow way.", "kw": ["güveç", "guvec"]}, {"id": "ankara-keskin-tava", "name": "Keskin tava", "local": "Keskin tavası", "icon": "🍖", "desc": "Lamb slow-roasted on a tray until it falls apart, from the town of Keskin near Kırıkkale, served with bread to mop up the juices.", "kw": ["keskin tava", "keskin"]}],
  annecy: [{"id": "annecy-tartiflette", "name": "Tartiflette", "local": "", "icon": "🥔", "desc": "Baked potatoes with bacon, onions and a generous layer of Reblochon. The best-known Savoyard dish, built on a cheese from the Thônes valley.", "kw": ["tartiflette"]}, {"id": "annecy-reblochon", "name": "Reblochon", "local": "", "icon": "🧀", "desc": "Soft washed-rind cheese from the Thônes valley near Annecy, eaten on its own and used in many local recipes.", "kw": ["reblochon"]}, {"id": "annecy-fondue-savoyarde", "name": "Fondue savoyarde", "local": "", "icon": "🫕", "desc": "A blend of melted Savoie cheeses eaten with bread, often alongside potatoes and charcuterie. Served in every Annecy restaurant.", "kw": ["fondue savoyarde", "fondue"]}, {"id": "annecy-lake-fish", "name": "Lake Annecy fish", "local": "Féra et omble chevalier", "icon": "🐟", "desc": "Féra and Arctic char from the lake, usually grilled or smoked. Lakeside restaurants in Annecy serve them as a signature plate.", "kw": ["féra", "omble chevalier", "lake fish"]}, {"id": "annecy-rissoles", "name": "Savoyard rissoles", "local": "Rissoles savoyardes", "icon": "🥟", "desc": "Fried pastry parcels filled with apple or pear, flavoured with cinnamon and dusted with icing sugar. A traditional Savoie sweet.", "kw": ["rissoles"]}],
  antalya: [{"id": "antalya-piyaz", "name": "Antalya piyazı", "local": "", "icon": "🫘", "desc": "White beans in a thick tahini, garlic and lemon dressing with egg and onion. It is a main dish here, not a side salad, and carries a geographical indication.", "kw": ["piyaz", "antalya piyazı"]}, {"id": "antalya-sis-kofte", "name": "Antalya şiş köfte", "local": "Şiş köfte", "icon": "🍢", "desc": "Lamb-heavy minced meat pressed onto skewers and grilled. In Antalya it is the standard partner of tahini piyaz, eaten with flatbread.", "kw": ["şiş köfte", "sis kofte"]}, {"id": "antalya-hibes", "name": "Hibeş", "local": "", "icon": "🥣", "desc": "A thick tahini, garlic and lemon spread served as a meze or dip, closely tied to Antalya's tahini cooking. Scoop it up with bread alongside piyaz.", "kw": ["hibeş", "hibes"]}, {"id": "antalya-alanya-tava", "name": "Alanya tava", "local": "", "icon": "🍲", "desc": "Lamb cooked with tomatoes, peppers and garlic in a pan or clay dish until thick and savoury. A home-style dish of the Alanya coast.", "kw": ["alanya tava", "tava"]}],
  antwerpen: [{"id": "antwerpen-handjes", "name": "Antwerpse handjes", "local": "", "icon": "🍪", "desc": "Small butter biscuits shaped like a hand, named after the legend of Brabo throwing a giant's hand into the Scheldt. Sold in bakeries and chocolate shops, also as chocolates.", "kw": ["handjes", "handje"]}, {"id": "antwerpen-worstenbroodje", "name": "Worstenbroodje", "local": "", "icon": "🥐", "desc": "Spiced minced pork baked in a flaky puff-pastry roll. A bakery staple in Antwerp, eaten warm at any hour.", "kw": ["worstenbroodje", "sausage roll"]}, {"id": "antwerpen-americain", "name": "Filet américain", "local": "Préparé / filet américain", "icon": "🥩", "desc": "Seasoned raw minced beef spread on a baguette or pistolet, a lunch of the Antwerp sandwich bars. It is a Belgian staple with a strong local following.", "kw": ["américain", "americain", "filet"]}, {"id": "antwerpen-mechelse-koekoek", "name": "Mechelse koekoek", "local": "", "icon": "🍗", "desc": "Slow-cooked chicken from Mechelen in the Antwerp province, served in a creamy sauce with mushrooms or in classic Flemish stews. A prized local poultry breed.", "kw": ["koekoek", "mechelse"]}, {"id": "antwerpen-frietjes", "name": "Frietjes with stoofvlees", "local": "", "icon": "🍟", "desc": "Thick-cut twice-fried chips from a frietkot, here eaten with sweet-sour beef stew or sauce. Antwerp is known for its old fry shops.", "kw": ["frietjes", "frituur", "fries", "stoofvlees"]}],
  arnhem: [{"id": "arnhem-arnhemse-meisjes", "name": "Arnhemse meisjes", "local": "", "icon": "🥐", "desc": "Crisp, buttery puff-pastry cookies shaped like a bow, named after the traditional girls' costume. The city's own biscuit, sold in Arnhem's bakeries.", "kw": ["arnhemse meisjes", "meisjes"]}, {"id": "arnhem-gelderse-rookworst", "name": "Gelderse rookworst", "local": "", "icon": "🌭", "desc": "Lightly smoked, coarse-ground pork sausage typical of Gelderland. Eaten on its own, in a roll or with stamppot.", "kw": ["rookworst"]}, {"id": "arnhem-veluwse-boekweitpannenkoek", "name": "Buckwheat pancake", "local": "Boekweitpannenkoek", "icon": "🥞", "desc": "Thick pancake made with buckwheat flour, often with bacon and syrup. A classic of the Veluwe's forest pancake houses.", "kw": ["boekweit", "pannenkoek", "pancake"]}, {"id": "arnhem-gelderse-appelstroop", "name": "Gelderse appelstroop", "local": "", "icon": "🍎", "desc": "Thick, dark apple syrup spread on bread or pancakes, made from fruit of the Betuwe orchards. A staple of the Gelderland breakfast table.", "kw": ["appelstroop", "stroop"]}],
  augsburg: [{"id": "augsburg-datschi", "name": "Augsburger Zwetschgendatschi", "local": "", "icon": "🥧", "desc": "Flat plum cake on a thin dough base, baked on a tray in September and October. The signature cake of Augsburg and Bavarian Swabia.", "kw": ["zwetschgendatschi", "datschi", "plum cake"]}, {"id": "augsburg-bubespitzle", "name": "Bubenspitzle", "local": "Schupfnudeln mit Sauerkraut", "icon": "🥔", "desc": "Finger-shaped potato noodles fried in butter, served with sauerkraut and bacon. A homely staple of Swabian kitchens around Augsburg.", "kw": ["bubenspitzle", "schupfnudeln", "bubespitzle"]}, {"id": "augsburg-krautkrapfen", "name": "Krautkrapfen", "local": "", "icon": "🥟", "desc": "Dough pockets filled with seasoned cabbage and bacon, baked or fried. A rustic Bavarian Swabian dish of the Lech and Danube villages.", "kw": ["krautkrapfen"]}, {"id": "augsburg-zwiebelrostbraten", "name": "Zwiebelrostbraten", "local": "", "icon": "🥩", "desc": "Pan-fried beef roast topped with fried onions in gravy, served with Spätzle. A standard of Swabian inns in the Augsburg area.", "kw": ["zwiebelrostbraten", "spätzle"]}],
  avignon: [{"id": "avignon-papaline", "name": "Papalines d'Avignon", "local": "", "icon": "🍬", "desc": "Emblematic Avignon confection created in 1960 by the Vaucluse pastry masters' guild. Around sixty confectioners in the département still make it by hand.", "kw": ["papaline"]}, {"id": "avignon-daube", "name": "Daube avignonnaise", "local": "", "icon": "🍲", "desc": "Beef stew slowly simmered in wine, better the day after it is made, and in the Avignon version cooked gently with anchovies. A staple of Provençal home cooking.", "kw": ["daube"]}, {"id": "avignon-crespeou", "name": "Crespeou", "local": "", "icon": "🍳", "desc": "A terrine of layered coloured omelettes, from the Comtat Venaissin. Farmers once carried it to the fields, and it is eaten cold.", "kw": ["crespeou"]}, {"id": "avignon-berlingot", "name": "Berlingots de Carpentras", "local": "", "icon": "🍭", "desc": "Berlingots de Carpentras are boiled sweets from Carpentras in the Vaucluse, a town better known for its truffle market and other Ventoux produce.", "kw": ["berlingot"]}, {"id": "avignon-fruits-confits", "name": "Fruits confits d'Apt", "local": "", "icon": "🍒", "desc": "Candied fruit, the specialty of Apt in the Luberon. Especially common at Christmas and over the winter festive season.", "kw": ["fruits confits", "candied fruit"]}],
  aydin: [{"id": "aydin-cine-koftesi", "name": "Çine köftesi", "local": "Çine köftesi", "icon": "🍖", "desc": "A meatball dish from the Çine district, traditionally eaten with yayık ayranı, churned buttermilk. A specialty of the Büyük Menderes valley.", "kw": ["çine köftesi", "çine"]}, {"id": "aydin-cingene-pilavi", "name": "Çingene pilavı", "local": "Çingene pilavı", "icon": "🥗", "desc": "Despite the name, a rice-free dish of çökelek curd cheese, tomato, pepper, cucumber, parsley, onion and thyme dressed with olive oil. Eaten at any meal in Aydın.", "kw": ["çingene pilavı", "çökelek"]}, {"id": "aydin-yuvarlama", "name": "Yuvarlama", "local": "Aydın yuvarlaması", "icon": "🍲", "desc": "Fried balls of minced meat, onion, egg and spices, simmered in butter and water, served with strained yogurt and red pepper butter. An Aydın home dish.", "kw": ["yuvarlama"]}, {"id": "aydin-soke-cop-sis", "name": "Söke çöp şiş", "local": "Söke çöp şişi", "icon": "🍢", "desc": "Small skewers of meat from the town of Söke, named in food guides as the town's signature dish alongside its tahinli pide.", "kw": ["çöp şiş", "söke"]}, {"id": "aydin-keskek", "name": "Aydın keşkek", "local": "Keşkek", "icon": "🍚", "desc": "Wheat and chicken or lamb cooked with butter and topped with butter and red pepper sauce. Served at weddings and circumcision celebrations.", "kw": ["keşkek"]}],
  ayvalik: [{"id": "ayvalik-tostu", "name": "Ayvalık tostu", "local": "Ayvalık tostu", "icon": "🥪", "desc": "A large toasted sandwich of sucuk, salami, sausage, kaşar, tomato and pickles on crisp bread, pressed hard. Registered as a traditional product in 2023.", "kw": ["ayvalık tostu", "tost"]}, {"id": "ayvalik-ada-koftesi", "name": "Ada köftesi", "local": "Ada köftesi", "icon": "🍖", "desc": "Thyme-scented veal meatballs that came with the Cretan exchange. Cunda and Ayvalık kitchens still serve them.", "kw": ["ada köftesi", "girit köfte"]}, {"id": "ayvalik-gardumi", "name": "Gardumi", "local": "Gardumi", "icon": "🥘", "desc": "Milk-fed lamb intestine stuffed and cooked, counted among Ayvalık's oldest dishes.", "kw": ["gardumi"]}, {"id": "ayvalik-lor-tatlisi", "name": "Ayvalık lor tatlısı", "local": "Lor tatlısı", "icon": "🍮", "desc": "A curd-cheese dessert specific to Ayvalık. On Cunda it is served with sour cherry jam.", "kw": ["lor tatlısı"]}, {"id": "ayvalik-kalburabasti", "name": "Kalburabastı", "local": "Kül şerbetli kalburabastı", "icon": "🍪", "desc": "A syrup-soaked sweet pastry that Ayvalık is known for, served with an ash-scented syrup.", "kw": ["kalburabastı"]}],
  bamberg: [{"id": "bamberg-schaeufele", "name": "Schäufele", "local": "Schäuferla", "icon": "🍖", "desc": "Roast pork shoulder with a crackling crust, served with potato dumplings and cabbage or salad. The classic Sunday roast of Franconian inns around Bamberg.", "kw": ["schäufele", "schäuferla"]}, {"id": "bamberg-hoernla", "name": "Bamberger Hörnla", "local": "", "icon": "🥐", "desc": "Crescent-shaped butter yeast pastry, folded like a croissant and made in Bamberg for centuries. Found in the town's old bakeries.", "kw": ["hörnla", "hörnchen"]}, {"id": "bamberg-zwiebel", "name": "Stuffed Bamberg onion", "local": "Gefüllte Bamberger Zwiebel", "icon": "🧅", "desc": "Local onion hollowed out and filled with minced meat, baked in smoked-beer sauce. It pairs Bamberg's onion growing with its smoked beer tradition.", "kw": ["bamberger zwiebel", "stuffed onion"]}, {"id": "bamberg-coburger-bratwurst", "name": "Coburger Bratwurst", "local": "", "icon": "🌭", "desc": "Coarse beef-and-pork sausage grilled over pine cones and eaten in a long roll. Coburg's own bratwurst, sold at stands on the market square.", "kw": ["coburger bratwurst", "bratwurst"]}, {"id": "bamberg-schmaetzchen", "name": "Coburger Schmätzchen", "local": "", "icon": "🍬", "desc": "Small meringue-and-hazelnut sweets in the shape of a kiss, a Coburg confectionery specialty from the old ducal town.", "kw": ["schmätzchen"]}],
  basel: [{"id": "basel-laeckerli", "name": "Basler Läckerli", "local": "", "icon": "🍪", "desc": "Chewy spiced honey biscuit with candied peel, almonds and hazelnuts, glazed white on top. Basel's signature sweet, sold in tins at the city's old confectioners.", "kw": ["läckerli", "laeckerli"]}, {"id": "basel-mehlsuppe", "name": "Basler Mehlsuppe", "local": "", "icon": "🍲", "desc": "Soup of deeply browned flour and onions in beef stock, finished with grated cheese. Tied to Fasnacht, but served in traditional Basel restaurants through the colder months.", "kw": ["mehlsuppe", "flour soup"]}, {"id": "basel-zwiebelwaehe", "name": "Basler Zwiebelwähe", "local": "", "icon": "🥧", "desc": "Savoury onion tart with egg and cream on a thin pastry base. Eaten in Basel at Fasnacht and in bakeries and cafés through the year.", "kw": ["zwiebelwähe", "onion tart"]}, {"id": "basel-brunsli", "name": "Basler Brunsli", "local": "", "icon": "🍫", "desc": "Small chocolate and almond biscuits with cinnamon, baked at Christmas time in Basel bakeries and confectioners. They are soft inside and slightly crisp outside.", "kw": ["brunsli"]}, {"id": "basel-suure-mocke", "name": "Suure Mocke", "local": "", "icon": "🥩", "desc": "Beef marinated in vinegar and spices, then braised into a rich sour stew. A traditional Basel-area Sunday dish, found in old-style restaurants.", "kw": ["suure mocke", "sauer mocke"]}],
  berlin: [{"id": "berlin-currywurst", "name": "Currywurst", "local": "", "icon": "🌭", "desc": "Sliced pork sausage under ketchup-curry sauce and curry powder, eaten with fries or a roll. Invented in Berlin in 1949 and sold at stands across the city.", "kw": ["currywurst"]}, {"id": "berlin-pfannkuchen", "name": "Berliner Pfannkuchen", "local": "Berliner", "icon": "🍩", "desc": "Jam-filled fried doughnut dusted with sugar. Berliners call it Pfannkuchen, while the rest of Germany says Berliner.", "kw": ["pfannkuchen", "berliner doughnut"]}, {"id": "berlin-buletten", "name": "Buletten", "local": "", "icon": "🍔", "desc": "Pan-fried minced-meat patties with bread roll, onion and marjoram, eaten warm with mustard or cold as a snack. The classic Berlin home-style meat dish.", "kw": ["bulette", "buletten"]}, {"id": "berlin-klopse", "name": "Königsberger Klopse", "local": "", "icon": "🍲", "desc": "Veal meatballs poached in a creamy caper sauce with boiled potatoes and beetroot. Brought by East Prussian refugees and now firmly a Berlin tavern staple.", "kw": ["klopse", "königsberger"]}, {"id": "berlin-eisbein", "name": "Eisbein with sauerkraut", "local": "Eisbein", "icon": "🍖", "desc": "Boiled, cured pork knuckle served with sauerkraut and pea puree. The traditional heavy plate of Berlin taverns.", "kw": ["eisbein"]}, {"id": "berlin-doner", "name": "Döner kebab", "local": "", "icon": "🥙", "desc": "Spit-roasted meat in flatbread with salad and sauces. The Berlin-style döner, developed by Turkish immigrants here in the 1970s, is the city's everyday street meal.", "kw": ["döner", "doner"]}],
  bern: [{"id": "bern-berner-platte", "name": "Berner Platte", "local": "", "icon": "🍖", "desc": "Platter of smoked pork, bacon, tongue and sausages on sauerkraut or beans, with boiled potatoes. The classic dish of the canton, served in traditional Bernese restaurants.", "kw": ["berner platte"]}, {"id": "bern-zibelechueche", "name": "Zibelechueche", "local": "Zwiebelkuchen", "icon": "🥧", "desc": "Onion tart with cream, egg and nutmeg. Bern marks the autumn onion harvest with it, and bakeries and restaurants serve it around the Zibelemärit.", "kw": ["zibelechueche", "zwiebelkuchen", "onion tart"]}, {"id": "bern-mandelbaerli", "name": "Mandelbärli", "local": "", "icon": "🐻", "desc": "Small bear-shaped almond sweets, a Bernese confectionery speciality. The bear is the city's emblem, so they are the typical local souvenir.", "kw": ["mandelbärli", "mandelbaerli"]}, {"id": "bern-roesti", "name": "Rösti", "local": "", "icon": "🥔", "desc": "Grated potato fried into a golden cake, the traditional farmhouse side of the Bernese Mittelland. It goes with sausage, fried egg or a Berner Platte.", "kw": ["rösti", "roesti"]}, {"id": "bern-meringues-gruyere", "name": "Meringues with double cream", "local": "", "icon": "🍦", "desc": "Crisp meringue shells with thick Gruyère double cream, a dessert of the Bernese Oberland and Emmental. Bern cafés and restaurants serve it as a regional treat.", "kw": ["meringue", "double cream"]}],
  besancon: [{"id": "besancon-saucisse-de-morteau", "name": "Morteau sausage", "local": "Saucisse de Morteau", "icon": "🌭", "desc": "Smoked pork sausage from the Haut-Doubs, simmered and served with potatoes or in a potée. A staple in Besançon's restaurants and charcuteries.", "kw": ["morteau", "saucisse de morteau"]}, {"id": "besancon-cancoillotte", "name": "Cancoillotte", "local": "", "icon": "🧀", "desc": "Soft, runny cheese spread made from cow's milk, butter and water, eaten warm on potatoes, ham or bread. Besançon and Franche-Comté's own cheese.", "kw": ["cancoillotte"]}, {"id": "besancon-comte", "name": "Comté", "local": "Comté", "icon": "🧀", "desc": "Pressed cooked cheese from raw cow's milk, creamy, aromatic and a little spicy. Made across the Jura and Doubs and sold everywhere in Besançon.", "kw": ["comté", "comte"]}, {"id": "besancon-griotte-bisontine", "name": "Griotte bisontine", "local": "", "icon": "🍒", "desc": "Small cherries coated in dark chocolate, a sweet long tied to Besançon. Sold in the town's chocolate shops.", "kw": ["griotte", "griottes"]}, {"id": "besancon-poulet-vin-jaune", "name": "Chicken, vin jaune, morels", "local": "Poulet au vin jaune et aux morilles", "icon": "🍗", "desc": "Free-range chicken cooked with vin jaune, cream, shallots and morel mushrooms. A traditional recipe of the Jura mountains and Franche-Comté.", "kw": ["vin jaune", "morilles"]}],
  biarritz: [{"id": "biarritz-gateau-basque", "name": "Gâteau basque", "local": "", "icon": "🥧", "desc": "Shortcrust pastry filled with pastry cream or black cherry jam. The signature Basque Country dessert, sold in every bakery in Biarritz and Bayonne.", "kw": ["gâteau basque", "gateau basque"]}, {"id": "biarritz-piperade", "name": "Piperade", "local": "", "icon": "🍳", "desc": "Stew of tomatoes, green peppers and onion with Espelette chilli, often topped with scrambled egg or ham. A staple of Basque home cooking.", "kw": ["piperade"]}, {"id": "biarritz-axoa", "name": "Axoa", "local": "", "icon": "🥘", "desc": "Minced veal simmered with onion, peppers and Espelette chilli, served with potatoes. A Basque lunch dish found in local restaurants.", "kw": ["axoa"]}, {"id": "biarritz-jambon-bayonne", "name": "Bayonne ham", "local": "Jambon de Bayonne", "icon": "🥓", "desc": "Salt-cured ham aged at least seven months, from the Adour basin around Bayonne. Eaten thinly sliced, with piperade or in sandwiches.", "kw": ["jambon de bayonne", "bayonne ham"]}, {"id": "biarritz-chocolat", "name": "Basque chocolate", "local": "Chocolat de Bayonne", "icon": "🍫", "desc": "Bayonne has made chocolate since the 17th century. Dark bars, hot chocolate and chocolate-covered sweets from local chocolatiers are a regional tradition.", "kw": ["chocolat", "chocolate"]}, {"id": "biarritz-ttoro", "name": "Ttoro", "local": "", "icon": "🍲", "desc": "Basque fish stew of hake, conger and shellfish with peppers and tomato. The traditional fishermen's dish of the coast around Saint-Jean-de-Luz and Biarritz.", "kw": ["ttoro", "fish stew"]}],
  bielefeld: [{"id": "bielefeld-wurstebrei", "name": "Wurstebrei", "local": "", "icon": "🌭", "desc": "Soft, spiced pork and groats sausage, fried and eaten with bread or boiled with sauerkraut. A winter staple of East Westphalian kitchens.", "kw": ["wurstebrei"]}, {"id": "bielefeld-stuten", "name": "Westphalian Stuten", "local": "Westfälischer Stuten", "icon": "🍞", "desc": "Sweet, soft raisin bread, sliced and eaten with butter or the local cured ham. A traditional East Westphalian bakery loaf.", "kw": ["stuten"]}, {"id": "bielefeld-dicke-bohnen", "name": "Broad beans with bacon", "local": "Dicke Bohnen mit Speck", "icon": "🫘", "desc": "Broad beans stewed with smoked bacon and savory herbs, served with boiled potatoes. A summer farmhouse dish across Westphalia and Lippe.", "kw": ["dicke bohnen", "broad beans"]}, {"id": "bielefeld-schmoeraeppelkes", "name": "Schmoräppelkes", "local": "", "icon": "🍎", "desc": "Apples stewed in a pan with sugar, butter and cinnamon, sometimes with pumpernickel crumbs. A traditional Westphalian dessert.", "kw": ["schmoräppel", "schmoraeppel"]}],
  bolu: [{"id": "bolu-mengen-pilavi", "name": "Mengen pilavı", "local": "", "icon": "🍚", "desc": "Pilaf with lamb, mushrooms, walnuts, tomatoes and dill, served with ayran. It takes its name from the Mengen district, home of Türkiye's famous cooks.", "kw": ["mengen pilavı", "mengen"]}, {"id": "bolu-ovmac", "name": "Ovmaç soup", "local": "Ovmaç (oğmaç) çorbası", "icon": "🥣", "desc": "Winter soup with onion, mince and tomato paste, thickened with hand-rubbed pieces of flour-and-egg dough. One of Bolu's best-known soups.", "kw": ["ovmaç", "oğmaç"]}, {"id": "bolu-saray-helvasi", "name": "Saray helvası", "local": "", "icon": "🍬", "desc": "Dry, layered halva topped with pistachios, a classic Bolu gift sweet. Sources tie it to Mudurnu in Bolu province.", "kw": ["saray helvası"]}, {"id": "bolu-abant-kebabi", "name": "Abant kebabı", "local": "", "icon": "🍆", "desc": "Whole smoked aubergine stuffed with lamb, mushrooms, onion, tomato and pepper, often topped with grated cheese. Named after the lake in Bolu's hills.", "kw": ["abant kebabı", "abant"]}, {"id": "bolu-kedi-batmaz", "name": "Kedi batmaz", "local": "", "icon": "🥄", "desc": "Cornmeal cooked in boiling water with molasses, spooned out and eaten with butter, walnuts and molasses. A Mengen dish whose odd name means that a cat would not sink in it.", "kw": ["kedi batmaz"]}],
  bonn: [{"id": "bonn-gummibaerchen", "name": "Gummy bears", "local": "Gummibärchen", "icon": "🐻", "desc": "Haribo Goldbears were invented in Bonn in 1922 and are still made here. Shops in the city sell fresh and fruit-gum varieties.", "kw": ["gummy bear", "haribo", "gummibär"]}, {"id": "bonn-goldsaft", "name": "Grafschafter Goldsaft", "local": "", "icon": "🍯", "desc": "Sweet, dark sugar-beet syrup made in the Grafschaft near Bonn. Spread on bread or stirred into baking.", "kw": ["goldsaft", "beet syrup"]}, {"id": "bonn-muscheln", "name": "Rhenish mussels", "local": "Muscheln Rheinischer Art", "icon": "🦪", "desc": "Mussels steamed with vegetables and white wine, served with rye bread. A Rhineland pub classic found around Bonn and the river.", "kw": ["muscheln", "mussels"]}, {"id": "bonn-sauerbraten", "name": "Rheinischer Sauerbraten", "local": "", "icon": "🍖", "desc": "Beef marinated for days in vinegar and spices, served with a sweet-sour gravy with raisins and dumplings. A Rhineland Sunday dish.", "kw": ["sauerbraten"]}],
  bordeaux: [{"id": "bordeaux-canele", "name": "Canelé", "local": "Canelé de Bordeaux", "icon": "🧁", "desc": "Small fluted cake with a dark caramelised crust and a soft custard centre scented with vanilla and rum. Born in Bordeaux and sold in bakeries across the city.", "kw": ["canelé", "canele"]}, {"id": "bordeaux-entrecote", "name": "Entrecôte bordelaise", "local": "Entrecôte à la bordelaise", "icon": "🥩", "desc": "Rib steak grilled over vine cuttings and served with a red wine and shallot sauce, sometimes with bone marrow. The classic Bordeaux brasserie plate.", "kw": ["entrecôte", "entrecote"]}, {"id": "bordeaux-lamproie", "name": "Lamproie à la bordelaise", "local": "", "icon": "🐟", "desc": "Lamprey from the Gironde estuary stewed in red wine with leeks. An old, strong-flavoured dish, found in season in traditional Bordeaux restaurants.", "kw": ["lamproie", "lamprey"]}, {"id": "bordeaux-huitres", "name": "Arcachon oysters", "local": "Huîtres du bassin d'Arcachon", "icon": "🦪", "desc": "Oysters from the Arcachon basin, often eaten with grilled crépinettes sausages and a glass of white wine. The Gironde's best-known seafood.", "kw": ["huîtres", "oysters", "arcachon"]}, {"id": "bordeaux-agneau-pauillac", "name": "Pauillac lamb", "local": "Agneau de Pauillac", "icon": "🍖", "desc": "Milk-fed lamb raised in the Médoc around Pauillac, roasted pink with herbs. A regional meat with its own label, served in Bordeaux restaurants.", "kw": ["agneau de pauillac", "pauillac lamb"]}],
  bornholm: [{"id": "bornholm-sol-over-gudhjem", "name": "Sol over Gudhjem", "local": "", "icon": "🍳", "desc": "Rye bread topped with smoked herring, radishes and chives, crowned with a raw egg yolk as the sun. Named after the harbour town of Gudhjem and eaten at the island's smokehouses.", "kw": ["sol over gudhjem"]}, {"id": "bornholm-roget-sild", "name": "Smoked herring", "local": "Røget sild", "icon": "🐟", "desc": "Herring smoked over alder wood in the island's smokehouses, with the tall brick chimneys still dotting the harbours. Eaten warm, straight from the smoker, with rye bread.", "kw": ["smoked herring", "røget sild"]}, {"id": "bornholm-salt-sild", "name": "Herring on rye", "local": "Salt sild på rugbrød", "icon": "🍞", "desc": "Salt herring on dark rye bread with caramelised onions, beetroot and Bornholm mustard. The everyday island lunch, found at harbour restaurants.", "kw": ["salt herring"]}, {"id": "bornholm-bolcher", "name": "Bornholm boiled sweets", "local": "Bornholmske bolcher", "icon": "🍬", "desc": "Hard sweets made by hand in small batches in Svaneke and other towns, often shaped in front of visitors. A sweet souvenir that is also a local craft.", "kw": ["bolcher", "boiled sweets"]}],
  boulogne: [{"id": "boulogne-hareng", "name": "Smoked herring", "local": "Hareng saur", "icon": "🐟", "desc": "Herring salted and smoked in the port's old smokehouses. Boulogne is France's biggest fishing port and the herring is celebrated each November.", "kw": ["herring", "hareng"]}, {"id": "boulogne-gainee", "name": "Gainée boulonnaise", "local": "Gainée", "icon": "🍲", "desc": "A fish stew with vegetables, onions and fresh cream, often called Boulogne's bouillabaisse. Made with the day's catch from the harbour.", "kw": ["gainée", "gainee"]}, {"id": "boulogne-moules", "name": "Moules marinières", "local": "", "icon": "🦪", "desc": "Mussels steamed in white wine, shallots and cream. The quayside restaurants serve them with chips.", "kw": ["moules", "mussels"]}, {"id": "boulogne-vieux-boulogne", "name": "Vieux Boulogne", "local": "", "icon": "🧀", "desc": "Cow's-milk cheese with an orange washed rind and a famously strong smell but a mild, creamy inside. Made in the Boulonnais behind the Côte d'Opale.", "kw": ["vieux boulogne", "vieux-boulogne"]}],
  bourges: [{"id": "bourges-pate-berrichon", "name": "Pâté berrichon", "local": "Pâté de Pâques", "icon": "🥧", "desc": "A pie of seasoned pork and veal in golden pastry, with whole hard-boiled eggs inside. Originally an Easter dish, now eaten year-round across the Berry.", "kw": ["pâté berrichon", "pâté de pâques"]}, {"id": "bourges-coq-en-barbouille", "name": "Coq en barbouille", "local": "Poulet en barbouille", "icon": "🍗", "desc": "Chicken braised with red wine, brandy and onions, then finished with a sauce thickened with the bird's blood and cream. A classic Berry dish.", "kw": ["barbouille"]}, {"id": "bourges-crottin-de-chavignol", "name": "Crottin de Chavignol", "local": "", "icon": "🧀", "desc": "A small goat cheese from the Sancerre hills in the Cher, creamy and mild when young, hard and sharp when aged. Often baked on salad.", "kw": ["crottin", "chavignol"]}, {"id": "bourges-lentilles-du-berry", "name": "Berry green lentils", "local": "Lentilles vertes du Berry", "icon": "🫘", "desc": "Small dark green lentils with protected geographical status, nutty and firm. Grown in the Berry and served with salt pork or in soups.", "kw": ["lentilles", "lentil"]}, {"id": "bourges-forestines", "name": "Forestines", "local": "Forestines de Bourges", "icon": "🍬", "desc": "Hazelnut praline sweets in a crisp sugar shell, created in Bourges in 1879 by confectioner Georges Forest. Still made in the town.", "kw": ["forestine"]}],
  braunschweig: [{"id": "braunschweig-mettwurst", "name": "Braunschweiger Mettwurst", "local": "", "icon": "🌭", "desc": "Smoked, spreadable pork sausage that Braunschweig butchers have made for centuries. Eaten sliced on bread, it is the city's best-known food.", "kw": ["braunschweiger", "mettwurst"]}, {"id": "braunschweig-prilleken", "name": "Prilleken", "local": "", "icon": "🍩", "desc": "Small fried yeast-dough balls dusted with sugar, a long-standing Braunschweig treat sold at fairs and bakeries.", "kw": ["prilleken"]}, {"id": "braunschweig-harzer-kaese", "name": "Harzer cheese", "local": "Harzer Käse", "icon": "🧀", "desc": "Strong-smelling, fat-free sour-milk cheese from the Harz foothills, usually eaten with onions and vinegar on dark bread.", "kw": ["harzer käse", "harzer cheese", "harzer"]}, {"id": "braunschweig-hochzeitssuppe", "name": "Braunschweig wedding soup", "local": "Braunschweiger Hochzeitssuppe", "icon": "🍲", "desc": "Clear chicken broth with asparagus, small meatballs and egg custard. A festive soup of Braunschweig and the Altmark.", "kw": ["hochzeitssuppe", "wedding soup"]}],
  breda: [{"id": "breda-bergse-ansjovis", "name": "Bergen op Zoom anchovies", "local": "Bergse ansjovis", "icon": "🐟", "desc": "The only Dutch anchovies, caught by one family in fyke nets off Bergen op Zoom from May to early June and sold fresh or salted.", "kw": ["ansjovis", "anchovy", "anchovies"]}, {"id": "breda-groffenkoek", "name": "Bergse puddingkoek", "local": "Groffenkoek", "icon": "🍮", "desc": "Large round pudding tart from Bergen op Zoom, also called koeienvlaai. A bakery speciality of West Brabant.", "kw": ["groffenkoek", "puddingkoek", "koeienvlaai"]}, {"id": "breda-bergse-asperges", "name": "West Brabant white asparagus", "local": "Bergse asperges", "icon": "🌿", "desc": "White asparagus grown around Bergen op Zoom, served in spring with ham, egg and butter. Many restaurants run a dedicated asparagus menu.", "kw": ["asperges", "asparagus"]}, {"id": "breda-chaams-hoen", "name": "Chaams hoen", "local": "Kaamsekiep", "icon": "🍗", "desc": "Free-range chicken from the farms south of Breda, roasted or stewed. A traditional product of the Chaam area.", "kw": ["chaams hoen", "kaamsekiep"]}],
  bremen: [{"id": "bremen-kuekenragout", "name": "Bremer Kükenragout", "local": "", "icon": "🍲", "desc": "Creamy ragout of chicken, mushrooms, asparagus and meatballs in a light sauce, served in a puff pastry shell. Bremen's festive dish.", "kw": ["kükenragout", "ragout"]}, {"id": "bremen-klaben", "name": "Bremer Klaben", "local": "", "icon": "🍞", "desc": "Dense fruit bread with raisins and candied peel, baked around Christmas and found in Bremen bakeries from autumn.", "kw": ["klaben"]}, {"id": "bremen-kluten", "name": "Bremer Kluten", "local": "", "icon": "🍬", "desc": "Chocolate-coated peppermint sweets, a traditional Bremen confection hardened into a ball shape.", "kw": ["kluten"]}, {"id": "bremen-knipp", "name": "Knipp", "local": "", "icon": "🥓", "desc": "Fried sausage of oats, groats and pork, served with fried potatoes and pickles. A north German speciality typical of Bremen.", "kw": ["knipp"]}, {"id": "bremen-matjes", "name": "Vegesacker Matjes", "local": "", "icon": "🐟", "desc": "Young salted herring tied to the port of Bremen-Vegesack, where the herring fleet sailed. Eaten with onions and bread.", "kw": ["matjes", "herring"]}],
  brest: [{"id": "brest-kig-ha-farz", "name": "Kig ha farz", "local": "", "icon": "🍲", "desc": "Breton pot-au-feu from the Léon in northern Finistère: pork and beef simmered with vegetables and a buckwheat farz cooked in a cloth bag, served with a shallot-and-butter sauce.", "kw": ["kig ha farz"]}, {"id": "brest-kouign-amann", "name": "Kouign-amann", "local": "", "icon": "🥐", "desc": "A caramelised cake of laminated dough, butter and sugar, born in Douarnenez in Finistère. Dark and crisp outside, soft and very buttery inside.", "kw": ["kouign-amann", "kouign amann"]}, {"id": "brest-cotriade", "name": "Cotriade", "local": "", "icon": "🐟", "desc": "Finistère's fisherman's stew of mixed fish, potatoes and onions in a butter-enriched broth, eaten over bread. A staple of the ports around Douarnenez and Concarneau.", "kw": ["cotriade"]}, {"id": "brest-pate-henaff", "name": "Pâté Hénaff", "local": "", "icon": "🥫", "desc": "Pork pâté from Pouldreuzic in the Bigouden country, created in 1915 and now a Finistère emblem in its blue tin. Sold in every local shop and eaten on bread.", "kw": ["hénaff", "henaff"]}, {"id": "brest-palets-bretons", "name": "Palets bretons", "local": "", "icon": "🍪", "desc": "Thick, crumbly butter biscuits with salted butter, a speciality of Pont-Aven in southern Finistère. Sold in tins by local bakeries and biscuit makers.", "kw": ["palets bretons", "palet breton"]}],
  brugge: [{"id": "brugge-garnaalkroket", "name": "Shrimp croquette", "local": "Garnaalkroket", "icon": "🍤", "desc": "Crisp-fried croquette filled with creamy grey North Sea shrimp. A fixture of Flemish coast and Bruges restaurant menus.", "kw": ["garnaalkroket", "shrimp croquette", "croquette"]}, {"id": "brugge-paling", "name": "Eel in green sauce", "local": "Paling in 't groen", "icon": "🐟", "desc": "Eel stewed in a sauce of fresh green herbs, a Flemish dish from the coast and rivers of West Flanders. Served with fries or bread.", "kw": ["paling", "eel"]}, {"id": "brugge-mosselen", "name": "Mussels with fries", "local": "Mosselen met friet", "icon": "🦪", "desc": "Steamed mussels in celery and onion broth served with a bowl of fries. Belgium's best-known meal, eaten along the coast and in Bruges from late summer.", "kw": ["mosselen", "mussels", "moules"]}, {"id": "brugge-oostendse-tong", "name": "Ostend sole", "local": "Oostendse tong", "icon": "🐟", "desc": "Dover sole from the Ostend fleet, pan-fried in butter and served whole with potatoes. The classic dish of the Flemish coast.", "kw": ["tong", "sole"]}, {"id": "brugge-chocolates", "name": "Bruges chocolates", "local": "", "icon": "🍫", "desc": "Hand-made chocolates and pralines, many shaped as swans or lace patterns, sold in the centre's small chocolate workshops.", "kw": ["praline", "chocolate", "chocolaterie"]}],
  brussel: [{"id": "brussel-brusselse-wafel", "name": "Brussels waffle", "local": "Brusselse wafel / gaufre de Bruxelles", "icon": "🧇", "desc": "Light rectangular waffle with a crisp shell and airy batter, dusted with sugar. Sold from stalls and cafes across the centre.", "kw": ["brussels waffle", "waffle", "gaufre", "wafel"]}, {"id": "brussel-mitraillette", "name": "Mitraillette", "local": "", "icon": "🥖", "desc": "Baguette filled with fried meat, chips and sauce. A Brussels student favourite from the city's friteries.", "kw": ["mitraillette"]}, {"id": "brussel-stoemp", "name": "Stoemp", "local": "", "icon": "🥔", "desc": "Mashed potato mixed with carrots, leek or other vegetables, served with sausage. Home cooking that appears on old Brussels brasserie menus.", "kw": ["stoemp"]}, {"id": "brussel-praline", "name": "Belgian praline", "local": "Praline", "icon": "🍫", "desc": "Filled chocolate shell, a Brussels invention of the early 1900s. Dozens of chocolatiers in the centre and Sablon still make them by hand.", "kw": ["praline", "chocolatier", "chocolate"]}, {"id": "brussel-pain-grecque", "name": "Pain à la grecque", "local": "", "icon": "🥨", "desc": "Flat sugared pastry roll with cinnamon, sold in Brussels bakeries. The name is a corruption of the old Rue des Grecs, not a Greek origin.", "kw": ["pain à la grecque", "pain a la grecque"]}, {"id": "brussel-plattekaas", "name": "Plattekaas with radish", "local": "Brusselse plattekaas", "icon": "🧀", "desc": "Fresh white cheese mixed with radishes and spring onion, eaten on dark bread. A traditional cafe snack of Brussels and the Pajottenland.", "kw": ["plattekaas", "fromage blanc", "radish"]}, {"id": "brussel-speculoos", "name": "Speculoos", "local": "Speculoos", "icon": "🍪", "desc": "Spiced caramel-brown biscuit eaten with coffee in Belgium and used in spreads and cakes. Brussels bakeries still sell traditional versions.", "kw": ["speculoos", "spéculoos"]}],
  bursa: [{"id": "bursa-iskender", "name": "İskender kebap", "local": "İskender kebap", "icon": "🥙", "desc": "Sliced doner on pieces of pide with tomato sauce, yogurt and sizzling butter. Said to have been first served by İskender Efendi in Bursa in 1867.", "kw": ["iskender"]}, {"id": "bursa-inegol-kofte", "name": "İnegöl köfte", "local": "İnegöl köftesi", "icon": "🍖", "desc": "Grilled meatballs of lamb and beef mixed without added spices, tied to the town of İnegöl in the province. Reportedly brought by Balkan migrants in the late 19th century.", "kw": ["inegöl köfte", "köfte"]}, {"id": "bursa-pideli-kofte", "name": "Pideli köfte", "local": "Pideli köfte", "icon": "🥙", "desc": "Like İskender but with grilled meatballs laid over pide instead of doner. A Bursa dish served at kebab houses.", "kw": ["pideli köfte"]}, {"id": "bursa-kemalpasa", "name": "Kemalpaşa dessert", "local": "Kemalpaşa tatlısı", "icon": "🍮", "desc": "A semolina-based syrup dessert from Mustafakemalpaşa, first known as cheese dessert because of the local cheese made for it. It is soaked in sweet syrup.", "kw": ["kemalpaşa tatlısı", "kemalpaşa"]}, {"id": "bursa-kestane-sekeri", "name": "Kestane şekeri", "local": "Kestane şekeri", "icon": "🌰", "desc": "Candied chestnuts made from Uludağ chestnuts, a symbol of the city. The Şekerciler Çarşısı has sold them since the early 1900s.", "kw": ["kestane şekeri", "candied chestnut"]}],
  caen: [{"id": "caen-tripes", "name": "Tripes à la mode de Caen", "local": "", "icon": "🍲", "desc": "Beef tripe and ox foot simmered for hours with onions, carrots, leeks, cider and calvados. Caen's best-known dish, defended by a local brotherhood that holds a yearly tripe contest.", "kw": ["tripes à la mode de caen", "tripes"]}, {"id": "caen-pre-sale", "name": "Salt-marsh lamb", "local": "Agneau de pré-salé", "icon": "🐑", "desc": "Lamb raised on meadows in Mont-Saint-Michel bay that the tides flood with seawater, which gives the meat a distinctive flavour. Eaten around the bay in Manche; the lamb holds AOC status.", "kw": ["pré-salé", "salt-marsh lamb"]}, {"id": "caen-omelette", "name": "Mont-Saint-Michel omelette", "local": "Omelette du Mont-Saint-Michel", "icon": "🍳", "desc": "A soufflé-style omelette of fresh eggs and salted Normandy butter, beaten and cooked in a long-handled pan over a wood fire. A fast pilgrim meal from the Mont-Saint-Michel inns since 1888.", "kw": ["omelette", "mont-saint-michel omelette"]}, {"id": "caen-pont-eveque", "name": "Pont-l'Évêque", "local": "", "icon": "🧀", "desc": "Soft washed-rind cow's-milk cheese with a square shape and orange rind, from the Calvados department. One of Normandy's four AOP cheeses.", "kw": ["pont-l'évêque", "pont-l'eveque"]}, {"id": "caen-teurgoule", "name": "Teurgoule", "local": "", "icon": "🍚", "desc": "Rice pudding baked slowly for about five hours with milk, sugar and cinnamon until a dark crust forms. A traditional Lower Normandy dessert linked to the Granville area.", "kw": ["teurgoule"]}],
  canakkale: [{"id": "canakkale-peynir-helvasi", "name": "Gelibolu cheese halva", "local": "Gelibolu peynir helvası", "icon": "🍯", "desc": "A sweet-salty halva made from fresh unsalted white cheese, a little flour and beet sugar, with a geographical indication. Gelibolu makers trace it back some 700 years.", "kw": ["peynir helvası", "cheese halva"]}, {"id": "canakkale-ezine-peyniri", "name": "Ezine cheese", "local": "Ezine peyniri", "icon": "🧀", "desc": "A white brine cheese named for the Ezine district, a fixture of Turkish breakfast and an ingredient in many local dishes. Easy to buy across the province.", "kw": ["ezine", "ezine peyniri"]}, {"id": "canakkale-sardalya", "name": "Gelibolu sardines", "local": "Gelibolu sardalyası", "icon": "🐟", "desc": "Sardines from the Gelibolu coast, salted and cured or cooked as buğulama and stuffed dolma. Salted fish canning is part of the town's food identity.", "kw": ["sardalya", "sardine"]}, {"id": "canakkale-tavuklu-manti", "name": "Gelibolu chicken mantı", "local": "Gelibolu tavuklu mantısı", "icon": "🥟", "desc": "A chicken-topped mantı dish listed among Gelibolu's signature foods in local culinary research. It sits beside the cheese halva and sardines as the town's own table.", "kw": ["tavuklu mantı", "gelibolu mantı"]}],
  carcassonne: [{"id": "carcassonne-escargots", "name": "Languedoc-style snails", "local": "Escargots à la languedocienne", "icon": "🐌", "desc": "Small petit-gris snails cooked slowly in a sauce of ham, walnuts, chard, garlic and parsley. A staple starter on Carcassonne menus, less known than the parsley-butter version.", "kw": ["escargots", "snails"]}, {"id": "carcassonne-gesiers", "name": "Duck gizzard salad", "local": "Salade de gésiers de canard", "icon": "🥗", "desc": "Duck gizzards, confit or pan-seared, served on a salad with crusty bread. Duck is everywhere in Cathar country, and this is the usual way to start a meal in the old town.", "kw": ["gésiers", "gizzard"]}, {"id": "carcassonne-carcassonnais", "name": "Le Carcassonnais", "local": "Le Carcassonnais", "icon": "🥐", "desc": "A puff-pastry brioche filled with vanilla cream and candied fruit, a Sunday treat from the city's bakeries.", "kw": ["carcassonnais", "brioche"]}, {"id": "carcassonne-cassoulet-glace", "name": "Iced cassoulet", "local": "Cassoulet glacé", "icon": "🍨", "desc": "A Carcassonne dessert shaped like a small cassoulet or burger, layering nougatine, vanilla, chestnut and morello cherry. Sold at several pastry shops in the city.", "kw": ["cassoulet glacé", "iced cassoulet"]}, {"id": "carcassonne-ecus", "name": "Écus de la Cité", "local": "Écus de la Cité", "icon": "🍫", "desc": "Small round chocolate coins stamped with the emblem of the fortified city, in dark or milk chocolate. A local sweet sold in confectioners and pastry shops.", "kw": ["écus", "chocolate"]}],
  chambery: [{"id": "chambery-matouille", "name": "Matouille", "local": "La Matouille", "icon": "🧀", "desc": "Tome des Bauges baked with white wine, garlic and nutmeg until it melts into a creamy spread, served with potatoes, salad or bread. A mountain-farm dish of the Bauges.", "kw": ["matouille", "tome des bauges"]}, {"id": "chambery-chambery-truffle", "name": "Chambéry chocolate truffle", "local": "Truffe au chocolat", "icon": "🍫", "desc": "Hand-rolled ganache of cream, butter and chocolate coated in cocoa. Said to have been born in Chambéry in the late 19th century.", "kw": ["truffle", "truffe"]}, {"id": "chambery-gateau-de-savoie", "name": "Gâteau de Savoie", "local": "", "icon": "🍰", "desc": "Light sponge of eggs, sugar and flour, eaten plain, with icing sugar or jam. Tradition places its origin at the court of the Counts of Savoy in Chambéry.", "kw": ["gâteau de savoie", "savoy cake"]}, {"id": "chambery-diots-crozets", "name": "Diots and crozets", "local": "Diots et crozets", "icon": "🌭", "desc": "Pork sausages simmered in white wine and onions, served with crozets, tiny square Savoyard pasta. A winter staple across Savoie.", "kw": ["diots", "crozets"]}, {"id": "chambery-gateau-des-bauges", "name": "Bauges cake", "local": "Gâteau des Bauges", "icon": "🍰", "desc": "Cake of whey, butter, local honey and fruit, with blackcurrant jam and a groove of quince jelly. Made in the Bauges massif above Chambéry.", "kw": ["gâteau des bauges", "bauges"]}],
  chemnitz: [{"id": "chemnitz-getzen", "name": "Buttermilchgetzen", "local": "", "icon": "🥞", "desc": "Thin potato and buttermilk pancake baked or fried, eaten with sweet toppings or with sausage. Poor-household cooking from the Ore Mountains.", "kw": ["getzen", "buttermilchgetzen"]}, {"id": "chemnitz-falscher-hase", "name": "Falscher Hase", "local": "", "icon": "🍖", "desc": "Baked minced-meat loaf with a hard-boiled egg inside, served with gravy and potatoes. A Saxon and Ore Mountains Sunday dish.", "kw": ["falscher hase"]}, {"id": "chemnitz-ochsenfetzen", "name": "Ochsenfetzen", "local": "", "icon": "🥩", "desc": "Strips of beef in a thick onion gravy, a hearty dish from the Ore Mountains kitchen, served with dumplings or potatoes.", "kw": ["ochsenfetzen"]}, {"id": "chemnitz-hutzenbrot", "name": "Hutzenbrot", "local": "", "icon": "🍞", "desc": "Dense fruit bread of dried pears and nuts, baked in the Ore Mountains and Vogtland for winter.", "kw": ["hutzenbrot", "hutzenkuchen"]}],
  chur: [{"id": "chur-capuns", "name": "Capuns", "local": "", "icon": "🥬", "desc": "Swiss chard leaves wrapped around a spätzle-like dough with dried meat, baked in cream and milk. The best-known dish of Graubünden, found in Chur's traditional restaurants.", "kw": ["capuns"]}, {"id": "chur-pizokel", "name": "Pizokel", "local": "", "icon": "🍝", "desc": "Thick buckwheat or wheat dumplings, often cooked with cheese, cabbage or butter and sage. A Graubünden mountain staple that Chur restaurants put on the menu.", "kw": ["pizokel", "pizokels"]}, {"id": "chur-maluns", "name": "Maluns", "local": "", "icon": "🥔", "desc": "Grated potatoes roasted slowly in butter with flour until crumbly, usually served with apple sauce. A Graubünden peasant dish found in the Chur area.", "kw": ["maluns"]}, {"id": "chur-nusstorte", "name": "Bündner Nusstorte", "local": "", "icon": "🥧", "desc": "Shortcrust tart filled with walnuts in caramel. Graubünden's best-known sweet, sold in every Chur bakery.", "kw": ["nusstorte", "walnut tart"]}, {"id": "chur-buendnerfleisch", "name": "Bündnerfleisch", "local": "", "icon": "🥩", "desc": "Air-dried beef, pressed and cured in the dry mountain air, sliced very thin. Graubünden's best-known cured meat, served as a platter in Chur.", "kw": ["bündnerfleisch", "buendnerfleisch", "air-dried beef"]}],
  clermont: [{"id": "clermont-truffade", "name": "Truffade", "local": "", "icon": "🥔", "desc": "Sliced potatoes cooked with garlic and fresh tomme cheese until stringy, served with local ham and salad. The emblematic dish of Auvergne.", "kw": ["truffade"]}, {"id": "clermont-pounti", "name": "Pounti", "local": "", "icon": "🥧", "desc": "Savoury cake of eggs, flour, milk, bacon, chard and prunes, eaten hot or cold. A traditional peasant dish of Auvergne.", "kw": ["pounti"]}, {"id": "clermont-saint-nectaire", "name": "Saint-Nectaire", "local": "", "icon": "🧀", "desc": "Mild, fairly flavourful cow's milk cheese of the Auvergne volcanoes, served at home and in restaurants.", "kw": ["saint-nectaire"]}, {"id": "clermont-pate-de-fruits", "name": "Auvergne pâtes de fruits", "local": "Pâtes de fruits", "icon": "🍬", "desc": "Fruit jellies of apricot, apple, quince or plum, cooked, dried and rolled in sugar. An Auvergne tradition with a confectioner near Clermont-Ferrand.", "kw": ["pâtes de fruits", "pate de fruits", "fruit jellies"]}, {"id": "clermont-pompe-aux-pommes", "name": "Pompe aux pommes", "local": "", "icon": "🥧", "desc": "Rectangular apple tart with well-cooked pieces of apple, often served with vanilla ice cream. A regional bakery sweet of Auvergne.", "kw": ["pompe aux pommes", "pompe"]}],
  colmar: [{"id": "colmar-flammekueche", "name": "Tarte flambée", "local": "Flammekueche", "icon": "🍕", "desc": "A paper-thin dough topped with crème fraîche, onions and bacon, baked in a wood oven. Served in Colmar's winstubs, sometimes with Munster.", "kw": ["flammekueche", "tarte flambée"]}, {"id": "colmar-kougelhopf", "name": "Kougelhopf", "local": "Kugelhopf", "icon": "🍞", "desc": "A yeasted ring cake with raisins and almonds, baked in a fluted ceramic mould. Sold in Colmar bakeries all year.", "kw": ["kougelhopf", "kugelhopf"]}, {"id": "colmar-munster", "name": "Munster cheese", "local": "Munster", "icon": "🧀", "desc": "A strong, washed-rind cheese from the Vosges valleys near Colmar, eaten with cumin and boiled potatoes.", "kw": ["munster"]}, {"id": "colmar-quetsch", "name": "Tarte aux quetsches", "local": "", "icon": "🥧", "desc": "A tart of Alsatian damson plums that marks the start of autumn. A staple of Colmar's bakeries and winstubs.", "kw": ["quetsch", "tarte aux quetsches"]}, {"id": "colmar-bredele", "name": "Alsatian bredele", "local": "Bredele", "icon": "🍪", "desc": "Small spiced Christmas biscuits in many shapes. Colmar's Christmas market is among the best places to try them.", "kw": ["bredele", "bredala"]}],
  corsica: [{"id": "corsica-figatellu", "name": "Figatellu", "local": "", "icon": "🌭", "desc": "A Corsican pork-liver sausage, cured or grilled fresh over embers in winter. The centrepiece of the island's charcuterie, alongside lonzu and coppa.", "kw": ["figatellu", "figatelli"]}, {"id": "corsica-brocciu", "name": "Brocciu", "local": "", "icon": "🧀", "desc": "Corsica's whey cheese, protected by AOC since 1983 and AOP since 2003. Eaten fresh or aged, and used in cannelloni, fritters and desserts.", "kw": ["brocciu"]}, {"id": "corsica-fiadone", "name": "Fiadone", "local": "", "icon": "🍮", "desc": "The island's emblematic dessert, a baked brocciu, egg, sugar and lemon-zest cake. Found in restaurants and bakeries all over Corsica.", "kw": ["fiadone"]}, {"id": "corsica-canistrelli", "name": "Canistrelli", "local": "", "icon": "🍪", "desc": "Small dry Corsican biscuits made with flour, sugar and white wine. Flavours include lemon, aniseed and chestnut.", "kw": ["canistrelli", "canistrellu"]}, {"id": "corsica-civet-sanglier", "name": "Civet de sanglier", "local": "Cinghjale in civet", "icon": "🐗", "desc": "Wild boar stewed in a rich onion sauce, a staple of Corsican mountain cooking. Typically served with polenta or pasta.", "kw": ["sanglier", "wild boar"]}],
  cottbus: [{"id": "cottbus-gurken", "name": "Spreewald gherkins", "local": "Spreewälder Gurken", "icon": "🥒", "desc": "Pickled cucumbers with protected origin, grown and processed in the Spreewald. Eaten at stalls, from barrels and in salads.", "kw": ["spreewald gherkin", "spreewälder gurken", "gherkin"]}, {"id": "cottbus-meerrettich", "name": "Spreewald horseradish", "local": "Spreewälder Meerrettich", "icon": "🌿", "desc": "Sharp grated horseradish from the Spreewald, served with fish, sausage or meat. Part of the region's food tradition.", "kw": ["meerrettich", "horseradish"]}, {"id": "cottbus-plinse", "name": "Plinse", "local": "Lausitzer Plinse", "icon": "🥞", "desc": "Yeast pancake of Sorbian-Wendish origin, baked thick and served with sugar, cinnamon and apple sauce.", "kw": ["plinse"]}, {"id": "cottbus-pueckler-eis", "name": "Fürst-Pückler-Eis", "local": "", "icon": "🍨", "desc": "Layered ice cream of chocolate, strawberry and vanilla, named for the Cottbus park creator Prince Pückler. Sold in local cafés.", "kw": ["pückler", "fürst-pückler"]}, {"id": "cottbus-spreewald-aal", "name": "Spreewald eel", "local": "Spreewälder Aal", "icon": "🐟", "desc": "Smoked or fried eel from the Spreewald waterways, a traditional local fish dish.", "kw": ["aal", "eel"]}],
  cyprus: [{"id": "cyprus-halloumi", "name": "Halloumi", "local": "Χαλλούμι / Hellim", "icon": "🧀", "desc": "Brined sheep's and goat's milk cheese folded with mint that holds its shape on the grill. Cyprus's signature cheese, eaten grilled, fresh with watermelon or baked into pies on both sides of the island.", "kw": ["halloumi", "hellim"]}, {"id": "cyprus-sheftalia", "name": "Sheftalia", "local": "Σεφταλιά / Şeftali kebabı", "icon": "🌭", "desc": "Minced meat with onion and parsley wrapped in caul fat and grilled over charcoal. A purely Cypriot sausage, served in pitta at grill houses across the island.", "kw": ["sheftalia", "şeftali", "seftali"]}, {"id": "cyprus-souvla", "name": "Souvla", "local": "Σούβλα", "icon": "🍖", "desc": "Large chunks of lamb or pork turned for hours on long skewers over charcoal. The Sunday and holiday meal of Cyprus, cooked in backyard foukou grills and village tavernas.", "kw": ["souvla"]}, {"id": "cyprus-kleftiko", "name": "Kleftiko", "local": "Κλέφτικο", "icon": "🍲", "desc": "Lamb on the bone with potatoes, sealed and slow-baked in a wood-fired clay oven until it falls apart. A taverna staple across Cyprus, often ordered a day ahead in the villages.", "kw": ["kleftiko"]}, {"id": "cyprus-molohiya", "name": "Molohiya", "local": "Μολοχία / Molehiya", "icon": "🥬", "desc": "Dried jute leaves stewed with chicken or lamb in a tomato and lemon sauce. A Turkish Cypriot home-cooking classic, found in lokantas in Nicosia and Famagusta.", "kw": ["molohiya", "molehiya", "molokhia"]}, {"id": "cyprus-loukoumi", "name": "Cyprus delight", "local": "Λουκούμι", "icon": "🍬", "desc": "Soft rosewater or bergamot jelly cubes dusted with icing sugar. The village of Geroskipou near Paphos has made loukoumi for over a century and sells it in its own shops.", "kw": ["loukoumi", "lokum", "cyprus delight"]}],
  denbosch: [{"id": "denbosch-bossche-bol", "name": "Bossche bol", "local": "", "icon": "🍰", "desc": "Large choux ball filled with whipped cream and coated in dark chocolate. The pastry of 's-Hertogenbosch, eaten with a fork or a very wide mouth.", "kw": ["bossche bol", "bossche bollen"]}, {"id": "denbosch-duingoed-kaas", "name": "Duingoed cheese", "local": "Duingoed kaas", "icon": "🧀", "desc": "Prize-winning cheese made by farmers around the Loon and Drunen dunes, a short ride from Den Bosch. Found in local cheese shops and farm stalls.", "kw": ["duingoed"]}, {"id": "denbosch-brabantse-buffelmozzarella", "name": "Brabant buffalo mozzarella", "local": "Buffelmozzarella", "icon": "🧀", "desc": "Buffalo mozzarella from Brabant farms, one of the province's recognised local cheeses. Sold at farm shops and markets around the city.", "kw": ["buffalo mozzarella", "mozzarella"]}, {"id": "denbosch-moorkop", "name": "Moorkop", "local": "", "icon": "🍫", "desc": "Choux pastry with cream and a chocolate glaze, a sibling of the Bossche bol. Sold in the city's patisseries.", "kw": ["moorkop"]}],
  denhaag: [{"id": "denhaag-hollandse-nieuwe", "name": "Hollandse Nieuwe herring", "local": "Haring", "icon": "🐟", "desc": "Young herring eaten raw with chopped onions and pickles, caught in early summer. Scheveningen harbour is the classic place to taste it.", "kw": ["haring", "herring"]}, {"id": "denhaag-kibbeling", "name": "Kibbeling", "local": "", "icon": "🍤", "desc": "Chunks of battered, deep-fried white fish with garlic sauce. A Scheveningen harbour snack eaten from a paper tray.", "kw": ["kibbeling"]}, {"id": "denhaag-haagse-hopjes", "name": "Haagse hopjes", "local": "", "icon": "🍬", "desc": "Coffee-caramel hard sweets named after a count of the Hague. Created in the city in the 18th century.", "kw": ["hopjes", "hopje"]}, {"id": "denhaag-haagse-bluf", "name": "Haagse bluf", "local": "", "icon": "🍮", "desc": "Light dessert of whipped egg white, sugar and berry juice. A traditional Hague pudding.", "kw": ["haagse bluf", "bluf"]}, {"id": "denhaag-soto-ayam", "name": "Soto ayam", "local": "", "icon": "🍜", "desc": "Indonesian chicken soup with rice noodles and egg. Den Haag has a large Indo-Dutch community and many specialist eateries.", "kw": ["soto", "indonesian"]}],
  denizli: [{"id": "denizli-denizli-kebabi", "name": "Denizli kebabı", "local": "Denizli tandır kebabı", "icon": "🍖", "desc": "Lamb cooked in a tandır oven, eaten with onion, tomato and lavaş. It received a geographical indication in 2010.", "kw": ["denizli kebabı", "tandır"]}, {"id": "denizli-tavas-guveci", "name": "Tavas güveci", "local": "Tavas güveci", "icon": "🥘", "desc": "A güveç from the Tavas district cooked for hours without spices. A local favorite beyond the town.", "kw": ["tavas güveci", "güveç"]}, {"id": "denizli-yen-boregi", "name": "Yen böreği", "local": "Yen böreği", "icon": "🥧", "desc": "A main-course pastry with minced meat filling in a cornmeal dough, made in villages for special days and guests. Also written leyen böreği.", "kw": ["yen böreği", "leyen böreği"]}, {"id": "denizli-tavas-baklavasi", "name": "Tavas baklavası", "local": "Tavas baklavası", "icon": "🍯", "desc": "Baklava from the Tavas district, one of the local products Denizli promotes on its gastronomy routes.", "kw": ["tavas baklavası", "baklava"]}, {"id": "denizli-borulce-boregi", "name": "Börülce böreği", "local": "Börülce böreği", "icon": "🥧", "desc": "A pastry of crumbled dry yufka and boiled black-eyed peas, often served with pickles. A Denizli country dish.", "kw": ["börülce böreği", "börülce"]}],
  dijon: [{"id": "dijon-boeuf-bourguignon", "name": "Boeuf bourguignon", "local": "Bœuf bourguignon", "icon": "🍲", "desc": "Charolais beef stewed slowly in red Burgundy wine with onions, bacon and mushrooms. Burgundy's festive and Sunday dish, found on nearly every traditional menu.", "kw": ["bourguignon", "boeuf bourguignon"]}, {"id": "dijon-oeufs-meurette", "name": "Oeufs en meurette", "local": "Œufs en meurette", "icon": "🥚", "desc": "Eggs poached directly in a dark red-wine sauce with bacon and onions, served on toast. A Burgundy starter that Dijon kitchens treat as a classic.", "kw": ["meurette", "oeufs en meurette"]}, {"id": "dijon-jambon-persille", "name": "Jambon persillé", "local": "", "icon": "🍖", "desc": "Shoulder ham cooked for hours in a strong stock, then set in parsley aspic and sliced cold. A Burgundian dish traditionally linked to Easter.", "kw": ["jambon persillé", "persillé"]}, {"id": "dijon-escargots", "name": "Burgundy snails", "local": "Escargots de Bourgogne", "icon": "🐌", "desc": "Snails baked in their shells with garlic and parsley butter. Burgundy's most famous starter, served in Dijon's traditional restaurants.", "kw": ["escargot", "escargots"]}, {"id": "dijon-pain-epices", "name": "Pain d'épices de Dijon", "local": "", "icon": "🍞", "desc": "Dense honey-spice cake that has been part of Dijon since the French Revolution era. Traditionally eaten toasted and buttered at breakfast.", "kw": ["pain d'épices", "gingerbread"]}, {"id": "dijon-epoisses", "name": "Époisses", "local": "", "icon": "🧀", "desc": "Strong, soft cow's-milk cheese with an orange rind washed in the local spirit. A Burgundy classic eaten at the end of a meal.", "kw": ["époisses", "epoisses"]}, {"id": "dijon-gougeres", "name": "Gougères", "local": "", "icon": "🧀", "desc": "Small choux-pastry puffs baked with cheese, a Burgundian speciality. Served warm at the aperitif and sold in bakeries.", "kw": ["gougère", "gougères"]}],
  diyarbakir: [{"id": "diyarbakir-ciger", "name": "Diyarbakır liver kebab", "local": "Ciğer kebabı", "icon": "🍢", "desc": "Lamb liver cut into small pieces and grilled on skewers, often eaten at breakfast with bread, onion and sumac. It has protected geographical status here.", "kw": ["ciğer kebabı", "ciğer", "cartlak"]}, {"id": "diyarbakir-mumbar", "name": "Mumbar dolması", "local": "", "icon": "🥘", "desc": "Sheep intestine stuffed with rice, minced meat and spices, then boiled and fried. A famously Diyarbakır dish sold in many local restaurants.", "kw": ["mumbar"]}, {"id": "diyarbakir-meftune", "name": "Meftune", "local": "", "icon": "🍲", "desc": "Slow-cooked lamb with seasonal vegetables in a sweet-and-sour sauce, with a touch of dried fruit. A traditional Diyarbakır home dish.", "kw": ["meftune"]}, {"id": "diyarbakir-duvakli-pilav", "name": "Duvaklı pilav", "local": "", "icon": "🍚", "desc": "Spiced rice with meat, topped with a pastry lid that is lifted at the table like a veil. A festive dish served in Diyarbakır restaurants.", "kw": ["duvaklı pilav"]}, {"id": "diyarbakir-burma-kadayif", "name": "Burma kadayıf", "local": "", "icon": "🍯", "desc": "Rolled shredded pastry with pistachio or walnut in syrup, a staple of Diyarbakır sweet shops. The city also serves Nuriye, a similar pastry.", "kw": ["burma kadayıf", "kadayıf", "nuriye"]}],
  dortmund: [{"id": "dortmund-pfefferpotthast", "name": "Pfefferpotthast", "local": "", "icon": "🥘", "desc": "Westphalian beef stew with onions, bay leaf and plenty of pepper, long a Dortmund tavern dish served with potatoes or bread.", "kw": ["pfefferpotthast"]}, {"id": "dortmund-toettchen", "name": "Töttchen", "local": "", "icon": "🍲", "desc": "Veal ragout in a tangy gravy made with vinegar and capers, a dish of Westphalia and the Ruhr.", "kw": ["töttchen"]}, {"id": "dortmund-pumpernickel", "name": "Westphalian pumpernickel", "local": "Westfälischer Pumpernickel", "icon": "🍞", "desc": "Dark rye bread steamed for many hours until sweet and soft. Eaten with ham, cheese or butter across the region.", "kw": ["pumpernickel"]}, {"id": "dortmund-salzkuchen", "name": "Dortmunder Salzkuchen", "local": "", "icon": "🥐", "desc": "Yeast roll topped with salt, caraway and onion, a Dortmund bakery snack known as a beer-hall companion.", "kw": ["salzkuchen"]}, {"id": "dortmund-schinken", "name": "Westphalian ham", "local": "Westfälischer Schinken", "icon": "🥩", "desc": "Smoked and air-cured ham from Westphalian farms, sliced thin and served with pumpernickel.", "kw": ["westphalian ham", "schinken"]}],
  dresden: [{"id": "dresden-stollen", "name": "Dresden Stollen", "local": "Dresdner Christstollen", "icon": "🍞", "desc": "Heavy fruit loaf with candied peel, almonds and a coat of butter and sugar. Dresden has baked it since the 15th century and guards the name.", "kw": ["stollen"]}, {"id": "dresden-wuerzfleisch", "name": "Würzfleisch", "local": "", "icon": "🍲", "desc": "Ragout of diced meat in a sharp, creamy, cheese-topped sauce, served in small gratin dishes. A Saxon snack found in every Dresden pub.", "kw": ["würzfleisch", "wuerzfleisch"]}, {"id": "dresden-pfefferkuchen", "name": "Pulsnitz gingerbread", "local": "Pulsnitzer Pfefferkuchen", "icon": "🍪", "desc": "Spiced honey gingerbread from Pulsnitz in Upper Lusatia, baked since 1558 and sold plain or with glaze and filling.", "kw": ["pfefferkuchen", "pulsnitz", "gingerbread"]}, {"id": "dresden-leinoel-quark", "name": "Quark with linseed oil", "local": "Leinöl mit Quark", "icon": "🥔", "desc": "Boiled potatoes in their skins with fresh quark and cold-pressed linseed oil. The classic Upper Lusatian farmhouse meal.", "kw": ["leinöl", "linseed oil", "quark"]}, {"id": "dresden-forelle", "name": "Saxon Switzerland trout", "local": "Forelle", "icon": "🐟", "desc": "River trout from the Elbe Sandstone hills, served blue, fried or smoked. A favorite lunch at inns around Pirna and Bad Schandau.", "kw": ["forelle", "trout"]}],
  duesseldorf: [{"id": "duesseldorf-reibekuchen", "name": "Reibekuchen", "local": "Rievkooche", "icon": "🥔", "desc": "Crisp grated-potato pancakes, served hot with apple sauce or dark bread. A Rhineland street and brewery classic.", "kw": ["reibekuchen", "rievkooche"]}, {"id": "duesseldorf-senfrostbraten", "name": "Düsseldorfer Senfrostbraten", "local": "", "icon": "🥩", "desc": "Roast beef coated in the city's mustard and braised with onions. A traditional meal in the old-town breweries.", "kw": ["senfrostbraten", "rostbraten"]}, {"id": "duesseldorf-mostert", "name": "Düsseldorf mustard", "local": "Düsseldorfer Mostert", "icon": "🌭", "desc": "The medium-hot mustard made in the city since the 19th century, eaten with Mett and rolls or sausages.", "kw": ["mostert", "mustard"]}, {"id": "duesseldorf-bergische-waffeln", "name": "Bergische waffeln", "local": "Bergische Waffeln", "icon": "🧇", "desc": "Heart-shaped waffles served with hot cherries and cream, from the Bergisches Land around Düsseldorf.", "kw": ["bergische waffel", "waffel"]}, {"id": "duesseldorf-kaffeetafel", "name": "Bergische Kaffeetafel", "local": "", "icon": "🍰", "desc": "Afternoon spread of waffles, rice pudding, dark bread, cheese and jam, served in traditional Bergisches Land cafés.", "kw": ["kaffeetafel"]}],
  edirne: [{"id": "edirne-tava-ciger", "name": "Edirne tava ciğer", "local": "Edirne tava ciğeri", "icon": "🍖", "desc": "Thin slices of liver dusted with flour and fried crisp, served with fried dried chilies and raw onion. The city's best-known dish, with a push to list it with UNESCO.", "kw": ["tava ciğer", "ciğer"]}, {"id": "edirne-ciger-sarma", "name": "Ciğer sarma", "local": "Edirne ciğer sarması", "icon": "🥩", "desc": "Liver wrapped in lamb caul fat and baked with currants, pine nuts, onion and rice. It has a geographical indication as an Edirne dish.", "kw": ["ciğer sarma"]}, {"id": "edirne-badem-ezmesi", "name": "Edirne almond paste", "local": "Badem ezmesi", "icon": "🌰", "desc": "A dense sweet of almonds, sugar and water that goes back to the Ottoman palace. A shop here has been known for it since 1961.", "kw": ["badem ezmesi", "almond paste"]}, {"id": "edirne-deva-i-misk", "name": "Deva-i misk", "local": "Deva-ı misk", "icon": "🍯", "desc": "A helva-like sweet said to date from Mehmed II's time, made with 41 spices and egg white and named for its medicinal, musky character. Sold in Edirne's old sweet shops.", "kw": ["deva-i misk", "deva-ı misk"]}, {"id": "edirne-kandilli-manti", "name": "Kandilli mantı", "local": "Kandilli mantı", "icon": "🥟", "desc": "Layers of baked buttered dough squares soaked in onion broth and served over shredded poultry. Once made with goose or duck, now usually chicken.", "kw": ["kandilli mantı", "mantı"]}],
  eindhoven: [{"id": "eindhoven-brabants-worstenbroodje", "name": "Brabants worstenbroodje", "local": "", "icon": "🥖", "desc": "Seasoned minced pork wrapped in flaky pastry and baked. Eindhoven's bakeries take it seriously, with regional votes for the best one.", "kw": ["worstenbroodje"]}, {"id": "eindhoven-kempense-schapenkaas", "name": "Kempen sheep's cheese", "local": "Schapenkaas", "icon": "🧀", "desc": "Cheese from sheep grazing on the Kempen heathlands. Found at farm shops and markets around Eindhoven.", "kw": ["schapenkaas", "sheep cheese"]}, {"id": "eindhoven-brabantse-eierkoek", "name": "Brabant eierkoek", "local": "Brabantse eierkoek", "icon": "🧁", "desc": "Light, dry sponge cake that originates in Brabant, found in bakeries and supermarkets across the province.", "kw": ["eierkoek"]}, {"id": "eindhoven-gevulde-koek", "name": "Gevulde koek", "local": "", "icon": "🍪", "desc": "Round almond-paste filled butter cookie. A Brabant bakery favourite.", "kw": ["gevulde koek"]}],
  enschede: [{"id": "enschede-twentse-krentenwegge", "name": "Twentse krentenwegge", "local": "", "icon": "🍞", "desc": "Soft raisin bread baked in a long loaf and sliced thick with butter. A Twente tradition, found on breakfast tables and in bakeries.", "kw": ["krentenwegge"]}, {"id": "enschede-balkenbrij", "name": "Balkenbrij", "local": "", "icon": "🥓", "desc": "Pork and buckwheat loaf sliced and fried, eaten with syrup or mustard. A farmhouse dish of the eastern Netherlands.", "kw": ["balkenbrij"]}, {"id": "enschede-hete-bliksem", "name": "Hete bliksem", "local": "", "icon": "🍎", "desc": "Stamppot of potatoes, apples and bacon from the east. A winter dish of Twente and the Achterhoek.", "kw": ["hete bliksem"]}, {"id": "enschede-twents-pannenkoek", "name": "Dutch pancake", "local": "Pannenkoek", "icon": "🥞", "desc": "Large plate-sized pancake with savoury or sweet toppings. Sold at farm restaurants across Twente.", "kw": ["pannenkoek", "pancake"]}],
  erfurt: [{"id": "erfurt-rostbratwurst", "name": "Thüringer Rostbratwurst", "local": "", "icon": "🌭", "desc": "Grilled pork sausage with a protected origin in Thuringia, seasoned with marjoram and caraway. Served in a roll with mustard.", "kw": ["rostbratwurst", "bratwurst"]}, {"id": "erfurt-kloesse", "name": "Thüringer Klöße", "local": "", "icon": "🥔", "desc": "Large dumplings of raw and boiled potato, soft inside, eaten with roast or gravy. The signature Thuringian side dish.", "kw": ["klöße", "kloesse", "dumpling"]}, {"id": "erfurt-mutzbraten", "name": "Mutzbraten", "local": "", "icon": "🍖", "desc": "Pork neck marinated in onions and spices and roasted over a beechwood fire, served in a bun. A specialty of Altenburg and Thuringia.", "kw": ["mutzbraten"]}, {"id": "erfurt-rotwurst", "name": "Thüringer Rotwurst", "local": "", "icon": "🌭", "desc": "Coarse blood and liver sausage, traditional at Thuringian butchers and eaten on bread or with sauerkraut.", "kw": ["rotwurst", "blutwurst"]}, {"id": "erfurt-zwiebelkuchen", "name": "Weimar onion tart", "local": "Weimarer Zwiebelkuchen", "icon": "🥧", "desc": "Yeast dough topped with onions, bacon and caraway, baked in trays. Weimar's autumn onion market made it the town's signature bake.", "kw": ["zwiebelkuchen", "onion tart", "onion cake"]}],
  erzurum: [{"id": "erzurum-cag", "name": "Cağ kebab", "local": "Cağ kebabı", "icon": "🍢", "desc": "Goat or lamb marinated for about a day, then cooked on a horizontal spit and sliced onto skewers. It is Erzurum's signature dish, also called Oltu kebab after the nearby town.", "kw": ["cağ", "cag kebab"]}, {"id": "erzurum-kadayif", "name": "Stuffed kadayıf", "local": "Kadayıf dolması", "icon": "🍯", "desc": "Shredded kadayıf wrapped around walnuts or pistachios, fried and soaked in syrup. A favourite Erzurum dessert, said to go back to Seljuk times.", "kw": ["kadayıf dolması", "kadayif"]}, {"id": "erzurum-subo", "name": "Erzurum su böreği", "local": "Erzurum su böreği", "icon": "🥟", "desc": "Layered pastry baked with local string cheese, using one egg for each sheet of dough. A staple of Erzurum breakfast tables.", "kw": ["su böreği", "su boregi"]}, {"id": "erzurum-lor", "name": "Lor dolması", "local": "Lor dolması", "icon": "🥬", "desc": "Chard leaves wrapped around a bulgur filling, a home-style stuffed dish from the Erzurum kitchen.", "kw": ["lor dolması", "dolma"]}, {"id": "erzurum-lalanga", "name": "Lalanga", "local": "Lalanga", "icon": "🥞", "desc": "A fried batter treat served with sugar or syrup, described as an ancestor of pancakes and crêpes. Part of the traditional Erzurum table.", "kw": ["lalanga", "leylanga"]}],
  eskisehir: [{"id": "eskisehir-ciborek", "name": "Çibörek", "local": "", "icon": "🥟", "desc": "Half-moon pastry of thin dough filled with spiced minced meat and deep-fried, usually eaten with ayran. A Tatar dish that Eskişehir has made its own, served around Odunpazarı.", "kw": ["çibörek", "cibörek"]}, {"id": "eskisehir-balaban", "name": "Balaban", "local": "Balaban kebabı", "icon": "🍖", "desc": "Pide soaked in hot broth and topped with yogurt-tomato sauce, grilled meatballs, skewers, peppers and hot butter. A Tatar-rooted dish tied to Eskişehir's old kebab houses.", "kw": ["balaban"]}, {"id": "eskisehir-met-helva", "name": "Met helva", "local": "Met helvası", "icon": "🍯", "desc": "Crumbly flour, sugar and butter halva flavoured with cocoa and vanilla. Its name comes from a stick-and-knucklebone game, and Eskişehir treats it as its own sweet.", "kw": ["met helva", "met helvası"]}, {"id": "eskisehir-hosmerim", "name": "Höşmerim", "local": "", "icon": "🍮", "desc": "Halva-like dessert of fresh unsalted cheese cooked with flour, semolina and sugar, often topped with walnuts. A traditional Eskişehir sweet served in its pastry shops.", "kw": ["höşmerim"]}, {"id": "eskisehir-muska-baklava", "name": "Sivrihisar muska baklava", "local": "Sivrihisar muska baklavası", "icon": "🥐", "desc": "Triangular baklava shaped like an amulet (muska), with layered pastry and balanced syrup. A specialty of Sivrihisar, in the Eskişehir province.", "kw": ["muska baklava", "sivrihisar"]}],
  essen: [{"id": "essen-frikadelle", "name": "Ruhr Frikadelle", "local": "Kumpel-Frikadelle", "icon": "🍔", "desc": "Large fried minced-meat patty, eaten hot with potato salad or in a roll. A miners-era staple of Ruhr home cooking and snack bars.", "kw": ["frikadelle", "kumpel"]}, {"id": "essen-pommes-schranke", "name": "Pommes Schranke", "local": "", "icon": "🍟", "desc": "Chips with both ketchup and mayonnaise, the red-white Ruhr order named after the railway barrier.", "kw": ["pommes", "fries", "chips"]}, {"id": "essen-panhas", "name": "Panhas", "local": "", "icon": "🥓", "desc": "Fried slices of a buckwheat and pork-broth sausage, a Westphalian and Lower Rhine speciality of the Ruhr.", "kw": ["panhas"]}, {"id": "essen-mettbroetchen", "name": "Mettbrötchen", "local": "", "icon": "🥖", "desc": "Crusty roll with seasoned raw minced pork and onions, a classic Ruhr breakfast and bakery order.", "kw": ["mettbrötchen", "mett"]}],
  fontainebleau: [{"id": "fontainebleau-brie-melun", "name": "Brie de Melun", "local": "", "icon": "🧀", "desc": "A raw-milk Brie with a stronger, earthier flavour than most, protected since 1980 and made near Melun. Sold in Fontainebleau's cheese shops.", "kw": ["brie de melun", "melun"]}, {"id": "fontainebleau-brie-meaux", "name": "Brie de Meaux", "local": "", "icon": "🧀", "desc": "A soft, creamy raw-milk cheese from Seine-et-Marne, the department around Fontainebleau. Matured in local cheese shops.", "kw": ["brie de meaux", "brie"]}, {"id": "fontainebleau-fontainebleau", "name": "Fontainebleau", "local": "Le fontainebleau", "icon": "🍓", "desc": "A light, unsweetened dessert of fromage blanc folded with whipped cream, served with strawberries or red fruit coulis.", "kw": ["fontainebleau dessert", "fromage blanc"]}, {"id": "fontainebleau-chasselas", "name": "Chasselas de Thomery", "local": "", "icon": "🍇", "desc": "Table grapes grown on trained walls in Thomery near Fontainebleau since the 18th century. Sold in season in autumn.", "kw": ["chasselas", "thomery"]}],
  frankfurt: [{"id": "frankfurt-gruene-sosse", "name": "Frankfurt green sauce", "local": "Frankfurter Grüne Soße", "icon": "🌿", "desc": "Cold sauce of seven fresh herbs with sour cream and yoghurt, served with boiled eggs and potatoes. The city's signature dish, protected as a regional specialty.", "kw": ["grüne soße", "green sauce"]}, {"id": "frankfurt-handkaese", "name": "Handkäse mit Musik", "local": "", "icon": "🧀", "desc": "Sour-milk cheese marinated in vinegar, oil and onions. Eaten with bread in apple-wine taverns, where 'Musik' refers to the onion dressing.", "kw": ["handkäse", "handkase"]}, {"id": "frankfurt-wuerstchen", "name": "Frankfurter Würstchen", "local": "", "icon": "🌭", "desc": "Thin, smoked pork sausages heated in water and served with mustard and bread. The original Frankfurter, long made in the city.", "kw": ["frankfurter würstchen", "würstchen"]}, {"id": "frankfurt-rippchen", "name": "Frankfurter Rippchen", "local": "", "icon": "🍖", "desc": "Cured and boiled pork chop served with sauerkraut, mustard and bread. A staple of Sachsenhausen taverns.", "kw": ["rippchen"]}, {"id": "frankfurt-bethmaennchen", "name": "Bethmännchen", "local": "", "icon": "🍪", "desc": "Small marzipan balls with three almond halves on the side, baked until just golden. A Frankfurt Christmas sweet that is now sold in bakeries all year.", "kw": ["bethmännchen", "bethmann"]}],
  freiburg: [{"id": "freiburg-kirschtorte", "name": "Black Forest cake", "local": "Schwarzwälder Kirschtorte", "icon": "🍰", "desc": "Chocolate sponge, whipped cream and sour cherries soaked in kirsch. Born in the Black Forest, where it is still made with local cherries.", "kw": ["kirschtorte", "black forest cake"]}, {"id": "freiburg-schinken", "name": "Black Forest ham", "local": "Schwarzwälder Schinken", "icon": "🥓", "desc": "Dry-cured, smoked ham with a dark crust, made in the Black Forest with a protected origin. Eaten thinly sliced on bread or as Speck.", "kw": ["schwarzwälder schinken", "black forest ham"]}, {"id": "freiburg-lange-rote", "name": "Lange Rote", "local": "", "icon": "🌭", "desc": "Freiburg's long grilled sausage in a roll, sold from stalls on the Münsterplatz. A market-day lunch for locals.", "kw": ["lange rote"]}, {"id": "freiburg-bibbeleskaes", "name": "Bibbeleskäs", "local": "", "icon": "🧀", "desc": "Fresh quark with herbs, onions and cream, eaten with boiled potatoes or bread. A simple Baden dish from the Upper Rhine.", "kw": ["bibbeleskäs", "bibbeleskaes"]}, {"id": "freiburg-flammkuchen", "name": "Breisgau Flammkuchen", "local": "Breisgauer Flammkuchen", "icon": "🥧", "desc": "Thin crisp dough with crème fraîche, onions and bacon, baked in a hot oven. Imported from Alsace and a local favorite in Freiburg.", "kw": ["flammkuchen"]}],
  gaziantep: [{"id": "gaziantep-beyran", "name": "Beyran soup", "local": "Beyran çorbası", "icon": "🍲", "desc": "Spicy lamb and rice soup topped with pul biber and a slick of fat, eaten for breakfast in Antep. It is the city's signature morning dish and is served in dedicated beyran houses.", "kw": ["beyran"]}, {"id": "gaziantep-katmer", "name": "Katmer", "local": "Antep katmeri", "icon": "🥞", "desc": "Paper-thin dough folded around clotted cream, crushed pistachios and sugar, then baked on a hot plate. A traditional Antep breakfast pastry eaten with the local pistachios.", "kw": ["katmer"]}, {"id": "gaziantep-ali-nazik", "name": "Ali Nazik kebab", "local": "Ali Nazik kebabı", "icon": "🍆", "desc": "Spiced minced lamb or cubed meat on a bed of smoked aubergine blended with garlicky yoghurt. A classic Antep kebab house dish.", "kw": ["ali nazik"]}, {"id": "gaziantep-yuvalama", "name": "Yuvalama", "local": "", "icon": "🥣", "desc": "Small rice-and-mince meatballs simmered in a yoghurt and chickpea broth finished with mint butter. A long-standing Antep home-style dish found in local lokantas.", "kw": ["yuvalama"]}, {"id": "gaziantep-baklava", "name": "Antep pistachio baklava", "local": "Antep fıstıklı baklava", "icon": "🥮", "desc": "Thin layers of pastry with green Antep pistachio and syrup, lighter and greener than most baklava. The city holds protected status for it and bakeries here are everywhere.", "kw": ["antep baklava", "fıstıklı baklava", "baklava"]}],
  geneve: [{"id": "geneve-longeole", "name": "Longeole", "local": "", "icon": "🌭", "desc": "Fennel-scented pork sausage with a protected geographical status, cooked in the oven or simmered and served with potatoes or lentils. A Geneva countryside speciality.", "kw": ["longeole"]}, {"id": "geneve-gratin-cardons", "name": "Cardon gratin", "local": "Gratin de cardons", "icon": "🥬", "desc": "Cardoon baked with béchamel and cheese. The Geneva cardoon has a protected designation and the dish is a Geneva Christmas tradition, found in autumn and winter.", "kw": ["cardon", "cardons"]}, {"id": "geneve-fondue", "name": "Cheese fondue", "local": "Fondue au fromage", "icon": "🫕", "desc": "Melted Swiss cheeses with white wine, eaten with bread from a shared pot. Geneva serves the classic version in its old brasseries and cafés through the colder months.", "kw": ["fondue"]}, {"id": "geneve-pain-genevois", "name": "Pain de Genève", "local": "Pain genevois", "icon": "🍞", "desc": "Soft, lightly sweet bread from the Geneva region. Bakers in the city still bake it as a local alternative to the standard roll.", "kw": ["pain genevois", "pain de genève"]}],
  gent: [{"id": "gent-waterzooi", "name": "Gentse waterzooi", "local": "", "icon": "🍲", "desc": "Creamy stew of chicken or fish with leek, carrot and potato. Born in Ghent, where chicken has replaced the old river fish.", "kw": ["waterzooi"]}, {"id": "gent-neuzen", "name": "Gentse neuzen", "local": "", "icon": "🍬", "desc": "Raspberry-flavoured jelly sweets shaped like noses, made in Ghent since the 1800s and sold in the old centre.", "kw": ["neuzen", "neus"]}, {"id": "gent-cuberdon", "name": "Cuberdon", "local": "Gentse neus / cuberdon", "icon": "🍬", "desc": "Cone-shaped purple sweet with a hard shell and runny raspberry centre. Locals call them neuzen, and they are strongly linked to Ghent.", "kw": ["cuberdon"]}, {"id": "gent-hutsepot", "name": "Hutsepot", "local": "", "icon": "🍲", "desc": "Slow-cooked stew of pork and vegetables, a winter dish of Ghent with roots in the 1300s. Still on menus of old taverns.", "kw": ["hutsepot"]}, {"id": "gent-tierenteyn", "name": "Tierenteyn mustard", "local": "Tierenteyn-Verlent mosterd", "icon": "🌭", "desc": "Strong grainy mustard from a Ghent shop open since 1790, sold from the barrel. Eaten with cold cuts and stoverij.", "kw": ["mustard", "mosterd", "tierenteyn"]}],
  goettingen: [{"id": "goettingen-feldkieker", "name": "Göttinger Feldkieker", "local": "", "icon": "🌭", "desc": "Coarse air-dried mettwurst of pork, with protected origin. Göttingen's best-known sausage.", "kw": ["feldkieker", "feldgieker"]}, {"id": "goettingen-stracke", "name": "Eichsfelder Stracke", "local": "", "icon": "🥓", "desc": "Straight air-dried sausage of the Eichsfeld, slow-matured for months and sliced thin.", "kw": ["stracke"]}, {"id": "goettingen-kaelberblase", "name": "Eichsfelder Kälberblase", "local": "", "icon": "🌭", "desc": "Raw sausage stuffed into a calf bladder and matured for months. Eaten on bread with pickled cucumbers.", "kw": ["kälberblase"]}, {"id": "goettingen-schmandkuchen", "name": "Eichsfelder Schmandkuchen", "local": "", "icon": "🍰", "desc": "Flat cake with a sour cream and custard topping, baked in the Eichsfeld.", "kw": ["schmandkuchen"]}],
  grenoble: [{"id": "grenoble-gratin-dauphinois", "name": "Gratin dauphinois", "local": "", "icon": "🥔", "desc": "Thin potato slices baked slowly in cream and garlic, traditionally without cheese. The classic dish of the Dauphiné.", "kw": ["gratin dauphinois", "gratin"]}, {"id": "grenoble-tarte-aux-noix", "name": "Grenoble walnut tart", "local": "Tarte aux noix", "icon": "🥧", "desc": "Tart of Grenoble walnuts, brown sugar, butter and fresh cream. Grenoble walnuts hold an AOP, France's first for a dried fruit, and pâtisseries across Isère sell the tart.", "kw": ["tarte aux noix", "walnut tart", "noix de grenoble"]}, {"id": "grenoble-bleu-vercors-sassenage", "name": "Bleu du Vercors-Sassenage", "local": "", "icon": "🧀", "desc": "Mild protected blue cheese from the cows that graze in the Vercors Natural Park, just above Grenoble.", "kw": ["vercors-sassenage", "bleu du vercors"]}, {"id": "grenoble-saint-marcellin", "name": "Saint-Marcellin", "local": "", "icon": "🧀", "desc": "Small soft cow's milk cheese with a protected geographical indication, produced in Isère and neighbouring departments and a fixture of Grenoble markets.", "kw": ["saint-marcellin"]}, {"id": "grenoble-murcon", "name": "Murçon", "local": "", "icon": "🌭", "desc": "Cooked pork sausage seasoned with caraway, tied to the Matheysine area south of Grenoble around La Mure.", "kw": ["murçon", "murcon"]}],
  groningen: [{"id": "groningen-groninger-mosterdsoep", "name": "Groninger mosterdsoep", "local": "", "icon": "🍲", "desc": "Creamy soup flavoured with mustard from the province, usually with bacon. A traditional Groningen dish.", "kw": ["mosterdsoep", "mustard soup"]}, {"id": "groningen-groninger-koek", "name": "Groninger koek", "local": "", "icon": "🍞", "desc": "Dense spiced gingerbread cake sliced with butter. The province's breakfast staple.", "kw": ["groninger koek"]}, {"id": "groningen-groninger-metworst", "name": "Groninger metworst", "local": "", "icon": "🌭", "desc": "Coarse raw-cured sausage seasoned with clove and pepper. A regional speciality sold at the city's butchers.", "kw": ["metworst"]}, {"id": "groningen-eierbal", "name": "Groninger eierbal", "local": "Eierbal", "icon": "🥚", "desc": "Deep-fried breaded ball of ragout around a hard-boiled egg, sold in snack bars and mostly eaten in Groningen province.", "kw": ["eierbal"]}],
  halle: [{"id": "halle-hallorenkugel", "name": "Hallorenkugeln", "local": "", "icon": "🍫", "desc": "Chocolate balls with a filling, made in Halle since 1804 and named for the salt boilers. Found in local shops.", "kw": ["hallorenkugel", "halloren"]}, {"id": "halle-quarkkeulchen", "name": "Quarkkeulchen", "local": "", "icon": "🥞", "desc": "Fried patties of potato and quark with cinnamon sugar and apple sauce. A Saxon-Anhalt dessert found in Halle restaurants.", "kw": ["quarkkeulchen"]}, {"id": "halle-butterkuchen", "name": "Mansfelder Butterkuchen", "local": "", "icon": "🍰", "desc": "Yeast sheet cake topped with butter, sugar and almonds. A bakery staple of the Mansfeld region.", "kw": ["butterkuchen"]}, {"id": "halle-hausmacher", "name": "Hausmacher Leberwurst", "local": "", "icon": "🌭", "desc": "Home-style liver sausage of the Halle region, spread on bread at the butcher's counter.", "kw": ["leberwurst"]}],
  hamburg: [{"id": "hamburg-labskaus", "name": "Labskaus", "local": "", "icon": "🥘", "desc": "Sailor's mash of corned beef, potatoes and beetroot topped with fried egg and rollmops. Hamburg's best-known harbour dish.", "kw": ["labskaus"]}, {"id": "hamburg-franzbroetchen", "name": "Franzbrötchen", "local": "", "icon": "🥐", "desc": "Cinnamon-sugar pastry rolled and flattened like a croissant, found in every Hamburg bakery.", "kw": ["franzbrötchen"]}, {"id": "hamburg-rundstueck", "name": "Rundstück warm", "local": "", "icon": "🥪", "desc": "Warm roast pork in a crusty roll with gravy, a Hamburg lunchtime classic.", "kw": ["rundstück"]}, {"id": "hamburg-aalsuppe", "name": "Hamburger Aalsuppe", "local": "", "icon": "🍲", "desc": "Sweet-sour soup with eel, vegetables, dried fruit and dumplings, a signature harbour-city recipe.", "kw": ["aalsuppe"]}, {"id": "hamburg-pannfisch", "name": "Pannfisch", "local": "", "icon": "🐟", "desc": "Pan-fried fish with mustard sauce and fried potatoes, a north German tavern classic of the harbour.", "kw": ["pannfisch"]}],
  hannover: [{"id": "hannover-heidschnucke", "name": "Heidschnuckenbraten", "local": "", "icon": "🍖", "desc": "Roast of Heidschnucke, the grey heath sheep of the Lüneburg Heath, with a strong gamey flavor, served with beans and potatoes.", "kw": ["heidschnucke"]}, {"id": "hannover-heidespargel", "name": "Heath asparagus", "local": "Heidespargel", "icon": "🌱", "desc": "White asparagus grown in the sandy soils around Lüneburg and Celle, served with new potatoes, ham and butter in spring.", "kw": ["heidespargel", "asparagus"]}, {"id": "hannover-buchweizentorte", "name": "Buckwheat cake", "local": "Heidjer Buchweizentorte", "icon": "🍰", "desc": "Layered cream cake with buckwheat flour and cranberry jam, baked on the Lüneburg Heath where buckwheat was grown on poor soil.", "kw": ["buchweizentorte", "buckwheat"]}, {"id": "hannover-pfannenschlag", "name": "Calenberger Pfannenschlag", "local": "", "icon": "🥩", "desc": "Fried pork cuts with bacon, onions and herbs from the Calenberg farmland south of Hannover, eaten with kale or potatoes.", "kw": ["pfannenschlag", "calenberger"]}, {"id": "hannover-zuckerkuchen", "name": "Lüneburg sugar cake", "local": "Lüneburger Zuckerkuchen", "icon": "🍰", "desc": "Flat yeast cake with a crust of sugar, butter and cinnamon, a Lüneburg bakery staple.", "kw": ["zuckerkuchen"]}],
  hasselt: [{"id": "hasselt-limburgse-vlaai", "name": "Limburgse vlaai", "local": "", "icon": "🥧", "desc": "Round fruit tart on a yeast dough base, with rice or cherry filling. A tradition across Limburg on both sides of the Dutch border.", "kw": ["vlaai"]}, {"id": "hasselt-hasseltse-speculaas", "name": "Hasseltse speculaas", "local": "", "icon": "🍪", "desc": "Local spiced biscuit baked in Hasselt for centuries, strongly tied to the city's bakers.", "kw": ["speculaas", "speculoos"]}, {"id": "hasselt-stroop", "name": "Haspengouw fruit syrup", "local": "Appelstroop / perenstroop", "icon": "🍯", "desc": "Thick apple or pear syrup cooked in Haspengouw orchards, spread on bread. A farm product of the Limburg fruit belt.", "kw": ["stroop", "syrup"]}, {"id": "hasselt-fruittaart", "name": "Haspengouw fruit tart", "local": "Fruittaart", "icon": "🍒", "desc": "Tart with Haspengouw cherries, plums or apples, from the orchard region of Limburg and Sint-Truiden.", "kw": ["tart", "taart", "fruit"]}],
  hatay: [{"id": "hatay-tepsi-kebabi", "name": "Tepsi kebabı", "local": "", "icon": "🥘", "desc": "Minced lamb and beef baked in a tray in a wood-fired oven with tomatoes and peppers. A true Antakya dish, locally called lahm-ı sini.", "kw": ["tepsi kebabı", "lahm-ı sini"]}, {"id": "hatay-oruk", "name": "Oruk", "local": "", "icon": "🧆", "desc": "Hatay's version of içli köfte with a bulgur shell and a filling of minced and pounded meat. The tray-baked sini oruğu is especially popular.", "kw": ["oruk", "sini oruğu"]}, {"id": "hatay-kunefe", "name": "Künefe", "local": "", "icon": "🍮", "desc": "Warm shredded pastry with melted cheese under syrup. Antakya künefe shops are famous for their own recipes.", "kw": ["künefe", "kunefe"]}, {"id": "hatay-humus", "name": "Humus", "local": "", "icon": "🥣", "desc": "Chickpea paste with tahini and lemon, served warm and often for breakfast. Antakya's meze culture makes it a daily staple.", "kw": ["humus", "hummus"]}, {"id": "hatay-biberli-ekmek", "name": "Biberli ekmek", "local": "", "icon": "🫓", "desc": "Flatbread filled with red pepper paste, onion and walnuts or spices. A popular Antakya street bread.", "kw": ["biberli ekmek"]}],
  isparta: [{"id": "isparta-banak", "name": "Banak", "local": "Banak", "icon": "🍖", "desc": "Lamb, mutton or beef slow-cooked in a tray over pide bread and often served with pilaf. A traditional dish of the Isparta kitchen.", "kw": ["banak"]}, {"id": "isparta-gullokum", "name": "Rose Turkish delight", "local": "Gül lokumu", "icon": "🌹", "desc": "Turkish delight flavoured with real rose from the Isparta rose fields, which locals prefer to versions made with rose water.", "kw": ["gül lokumu", "rose lokum", "rose delight"]}, {"id": "isparta-gullac", "name": "Yalvaç güllacı", "local": "Yalvaç güllacı", "icon": "🥛", "desc": "A rose-shaped rolled güllaç dessert made with a milk-based, lor-like cheese, different from other güllaç varieties. Named for the Isparta town of Yalvaç.", "kw": ["güllaç", "gullac"]}, {"id": "isparta-sis", "name": "Burdur şiş", "local": "Burdur şiş", "icon": "🍢", "desc": "Lamb or goat minced with tail fat and seasoned with salt only, grilled on skewers and usually eaten with pide. A Burdur speciality.", "kw": ["burdur şiş", "burdur sis"]}, {"id": "isparta-kombe", "name": "Bucak kömbe", "local": "Bucak kömbesi", "icon": "🫓", "desc": "Round dough pastry filled with tahini, walnut, molasses or poppy seed and oil, common around Bucak in Burdur province.", "kw": ["kömbe", "kombe"]}],
  istanbul: [{"id": "istanbul-balikekmek", "name": "Balık ekmek", "local": "", "icon": "🐟", "desc": "Grilled mackerel in a bread roll with onion and salad, sold from boats and stalls at the Galata Bridge and along the Bosphorus.", "kw": ["balık ekmek", "mackerel"]}, {"id": "istanbul-borek", "name": "Börek", "local": "", "icon": "🥐", "desc": "Layered or rolled pastry filled with white cheese, spinach or mince, sold in bakeries and börekçis throughout the city.", "kw": ["börek", "borek"]}, {"id": "istanbul-kumpir", "name": "Kumpir", "local": "", "icon": "🥔", "desc": "Large baked potato mashed with butter and cheese, then loaded with toppings. A street food closely tied to Ortaköy on the Bosphorus.", "kw": ["kumpir"]}, {"id": "istanbul-midye", "name": "Midye dolma", "local": "", "icon": "🦪", "desc": "Mussels stuffed with spiced rice, served cold with lemon from street stalls, especially around Beyoğlu and Kadıköy.", "kw": ["midye"]}, {"id": "istanbul-kokorec", "name": "Kokoreç", "local": "", "icon": "🌭", "desc": "Seasoned lamb offal wrapped around a skewer, grilled and chopped into a bread roll. A late-night street food of Beyoğlu and Kadıköy.", "kw": ["kokoreç", "kokorec"]}, {"id": "istanbul-baklava", "name": "Baklava", "local": "", "icon": "🍯", "desc": "Layers of thin pastry with pistachio or walnut and syrup, sold in the historic sweet shops of the old city.", "kw": ["baklava"]}, {"id": "istanbul-lokum", "name": "Turkish delight", "local": "Lokum", "icon": "🍬", "desc": "Soft gel sweets of starch and sugar with rose, pistachio or hazelnut, sold by weight in the old shops around the Spice Bazaar.", "kw": ["lokum", "turkish delight"]}],
  izmir: [{"id": "izmir-boyoz", "name": "Boyoz", "local": "", "icon": "🥐", "desc": "Flaky, oily pastry brought by Sephardic Jews, eaten on weekend mornings with a boiled egg. Found almost only in İzmir.", "kw": ["boyoz"]}, {"id": "izmir-lokma", "name": "İzmir lokma", "local": "", "icon": "🍩", "desc": "Small fried dough balls soaked in syrup, sold warm from shops and carts. The İzmir version is crisp outside and syrupy inside.", "kw": ["lokma"]}, {"id": "izmir-sambali", "name": "Şambali", "local": "", "icon": "🍰", "desc": "Semolina cake soaked in syrup and topped with almond or cream, a dessert strongly linked to İzmir.", "kw": ["şambali", "sambali"]}, {"id": "izmir-kumru", "name": "Kumru", "local": "", "icon": "🥪", "desc": "Toasted roll filled with sucuk, tomato and cheese. Born in Çeşme on the Aegean coast and now eaten all over İzmir.", "kw": ["kumru"]}, {"id": "izmir-otlar", "name": "Aegean wild greens", "local": "Ege otları", "icon": "🥬", "desc": "Boiled wild herbs dressed with olive oil and lemon, a staple of Aegean meyhanes and the kitchens of Çeşme and Urla.", "kw": ["ege otları", "otlar", "radika"]}, {"id": "izmir-tulum", "name": "İzmir tulum cheese", "local": "İzmir tulum peyniri", "icon": "🧀", "desc": "Crumbly, salty goat's-milk cheese ripened in a skin, made in the İzmir hills and served at breakfast.", "kw": ["tulum"]}],
  kaiserslautern: [{"id": "kaiserslautern-fleischknepp", "name": "Fleischknepp", "local": "", "icon": "🥟", "desc": "Palatinate meat dumplings, served in broth or on sauerkraut. Palatinate home cooking.", "kw": ["fleischknepp"]}, {"id": "kaiserslautern-grumbeersupp", "name": "Grumbeersupp with plum cake", "local": "Grumbeersupp mit Quetschekuche", "icon": "🍲", "desc": "Potato soup served with plum cake. A traditional Palatinate Sunday meal.", "kw": ["grumbeersupp", "plum cake"]}, {"id": "kaiserslautern-gebreedelde", "name": "Gebreedelde", "local": "", "icon": "🥔", "desc": "Palatinate fried potatoes with bacon or liver sausage.", "kw": ["gebreedelde"]}, {"id": "kaiserslautern-keschde", "name": "Sweet chestnuts", "local": "Keschde", "icon": "🌰", "desc": "Chestnuts from the Palatinate Forest, roasted or cooked into soups and stuffings in autumn.", "kw": ["keschde", "chestnut"]}, {"id": "kaiserslautern-pfaelzer-bratwurst", "name": "Pfälzer Bratwurst", "local": "", "icon": "🌭", "desc": "Coarse pork bratwurst grilled and eaten with sauerkraut. Common at village festivals.", "kw": ["pfälzer bratwurst", "bratwurst"]}],
  kapadokya: [{"id": "kapadokya-testi-kebabi", "name": "Pottery kebab", "local": "Testi kebabı", "icon": "🏺", "desc": "Meat and vegetables slow-cooked in a sealed clay pot from Avanos, which is cracked open at the table. It has a geographical indication and is the dish of Cappadocia.", "kw": ["testi kebabı", "testi kebab", "pottery kebab"]}, {"id": "kapadokya-nevsehir-manti", "name": "Nevşehir mantı", "local": "Nevşehir mantısı", "icon": "🥟", "desc": "Baked rolls of bread dough with spiced mince and onion, sliced and served with garlic yogurt, spicy butter, sumac and mint. Quicker to make than Kayseri's mantı.", "kw": ["mantı", "nevşehir mantısı"]}, {"id": "kapadokya-kuru-kaymak", "name": "Dried kaymak", "local": "Kuru kaymak", "icon": "🧈", "desc": "Clotted cream made by simmering milk over wood for hours and drying the skin that forms. Eaten with honey or jam, and a specialty of Kaymaklı.", "kw": ["kuru kaymak", "kaymak"]}, {"id": "kapadokya-kayisi-yahnisi", "name": "Apricot stew", "local": "Kayısı yahnisi", "icon": "🍑", "desc": "Meat and sweet apricots stewed in an earthen pot over a wood fire, with grape molasses if the fruit is not sweet enough. A regional dish of the Cappadocian table.", "kw": ["kayısı yahnisi", "apricot"]}, {"id": "kapadokya-zerdeli-pilav", "name": "Zerdeli pilav", "local": "", "icon": "🍚", "desc": "Rice layered with grape molasses, chickpeas, peeled almonds and raisins. A sweet-savoury festive dish of Nevşehir kitchens.", "kw": ["zerdeli pilav"]}],
  karlsruhe: [{"id": "karlsruhe-rehruecken", "name": "Rehrücken Baden-Baden", "local": "", "icon": "🦌", "desc": "Saddle of venison roasted with a cranberry-filled pear, a game classic of Baden-Baden and the northern Black Forest.", "kw": ["rehrücken", "venison"]}, {"id": "karlsruhe-braegele", "name": "Brägele", "local": "", "icon": "🥔", "desc": "Sliced boiled potatoes fried in a pan with onions and bacon until golden. The usual Baden side dish.", "kw": ["brägele", "braegele"]}, {"id": "karlsruhe-kratzete", "name": "Kratzete", "local": "", "icon": "🥞", "desc": "Torn pancake fried until crisp, served with apple sauce or stewed fruit. A Black Forest and Ortenau country dish.", "kw": ["kratzete"]}, {"id": "karlsruhe-striebele", "name": "Striebele", "local": "", "icon": "🍩", "desc": "Fried lattice of yeast dough dusted with sugar. A fair and Fastnacht pastry of Baden and the Black Forest.", "kw": ["striebele", "striebli"]}],
  kars: [{"id": "kars-kaz", "name": "Kars goose", "local": "Kars kazı", "icon": "🦆", "desc": "Goose is the famous meat of Kars, often cooked in a tandır oven and eaten through the cold winter months, sometimes over pilaf.", "kw": ["kaz", "goose"]}, {"id": "kars-kasar", "name": "Kars kaşarı", "local": "Kars kaşarı", "icon": "🧀", "desc": "A large wheel cheese cut into wedges like a cake, eaten at breakfast and through the day. One of the region's best-known products alongside its honey.", "kw": ["kaşar", "kasar", "cheese"]}, {"id": "kars-hangel", "name": "Hangel", "local": "Hangel", "icon": "🍝", "desc": "Thin pieces of dough boiled in water and served with yogurt and a fried onion topping. A traditional Kars home dish.", "kw": ["hangel", "hengel"]}, {"id": "kars-kete", "name": "Kars kete", "local": "Kars ketesi", "icon": "🥐", "desc": "A flatbread-style pastry made with butter, eaten morning and evening and especially good with tea.", "kw": ["kete"]}, {"id": "kars-hasil", "name": "Haşıl", "local": "Haşıl", "icon": "🍲", "desc": "A winter dish of specially prepared wheat cooked in water and served with butter and garlic yogurt.", "kw": ["haşıl", "hasil"]}],
  kassel: [{"id": "kassel-ahle-wurst", "name": "Ahle Wurst", "local": "Ahle Wurscht", "icon": "🥓", "desc": "Hard air-dried pork sausage from North Hesse, with protected origin status. Sliced thick and eaten on bread.", "kw": ["ahle wurst", "ahle wurscht"]}, {"id": "kassel-weckewerk", "name": "Weckewerk", "local": "", "icon": "🍳", "desc": "Cooked sausage of bread rolls, pork and spices, sliced and fried crisp. A classic North Hessian farm breakfast, served with pickles.", "kw": ["weckewerk"]}, {"id": "kassel-speckkuchen", "name": "Speckkuchen", "local": "", "icon": "🥧", "desc": "Bacon tart on yeast dough, baked in North Hesse and eaten warm. A simple local baker's staple.", "kw": ["speckkuchen"]}, {"id": "kassel-salzkuchen", "name": "Schwälmer Salzkuchen", "local": "", "icon": "🥐", "desc": "Flat yeast bread topped with cream, egg and bacon, baked in the Schwalm region. A local festive bread, now found in bakeries too.", "kw": ["salzkuchen"]}, {"id": "kassel-diebchen", "name": "Diebchen", "local": "", "icon": "🥔", "desc": "Potato dumplings stuffed with meat or bacon, served with bacon sauce. A simple North Hessian village dish.", "kw": ["diebchen"]}],
  kempten: [{"id": "kempten-kaesspatzen", "name": "Allgäu Kässpatzen", "local": "Allgäuer Kässpatzen", "icon": "🧀", "desc": "Egg noodles layered with mountain cheese and topped with fried onions. The most typical dish of the Allgäu, found in every inn in Kempten.", "kw": ["kässpatzen", "käsespätzle"]}, {"id": "kempten-krautkrapfen", "name": "Kemptener Krautkrapfen", "local": "", "icon": "🥟", "desc": "Egg-dough pockets filled with sauerkraut, bacon and butter, then baked or fried. A traditional Kempten dish.", "kw": ["krautkrapfen"]}, {"id": "kempten-bergkaese", "name": "Allgäu mountain cheese", "local": "Allgäuer Bergkäse", "icon": "🧀", "desc": "Hard, aged cow's-milk cheese from Alpine dairies, nutty and firm. Kempten has a long tradition of cheese ripening.", "kw": ["bergkäse", "allgäuer käse"]}, {"id": "kempten-flaedlesuppe", "name": "Flädlesuppe", "local": "", "icon": "🍜", "desc": "Clear beef broth with thin strips of pancake and chives. A classic first course on Allgäu menus.", "kw": ["flädlesuppe"]}, {"id": "kempten-topfenschmarrn", "name": "Topfenschmarrn", "local": "", "icon": "🥞", "desc": "Torn, fluffy curd-cheese pancake, usually served with fruit compote or ice cream. A regular on Allgäu menus after hiking.", "kw": ["topfenschmarrn", "schmarrn"]}],
  kiel: [{"id": "kiel-fischbroetchen", "name": "Fischbrötchen", "local": "", "icon": "🥪", "desc": "Roll with herring, matjes or smoked fish with onions and remoulade. Eaten straight from the harbour stalls on the fjord.", "kw": ["fischbrötchen", "fish roll"]}, {"id": "kiel-sprotten", "name": "Kieler Sprotten", "local": "", "icon": "🐟", "desc": "Small smoked sprats, a regional delicacy of Kiel eaten whole with bread.", "kw": ["sprotten"]}, {"id": "kiel-rote-gruetze", "name": "Rote Grütze", "local": "", "icon": "🍓", "desc": "Thick red berry compote served with vanilla sauce or cream, a Schleswig-Holstein dessert.", "kw": ["rote grütze"]}, {"id": "kiel-birnen-bohnen", "name": "Birnen, Bohnen und Speck", "local": "", "icon": "🍐", "desc": "Green beans, pears and bacon cooked together in one pot, a sweet-and-savoury northern dish.", "kw": ["birnen", "bohnen"]}, {"id": "kiel-katenschinken", "name": "Holsteiner Katenschinken", "local": "", "icon": "🥩", "desc": "Smoked and air-cured ham from Holstein, sliced thin and eaten on dark bread.", "kw": ["katenschinken"]}],
  kobenhavn: [{"id": "kobenhavn-smorrebrod", "name": "Smørrebrød", "local": "", "icon": "🥪", "desc": "Open rye sandwiches with herring, shrimp, egg or roast beef. Copenhagen's lunch places have kept the form alive for over a century.", "kw": ["smørrebrød", "smorrebrod"]}, {"id": "kobenhavn-wienerbrod", "name": "Wienerbrød", "local": "", "icon": "🥐", "desc": "Laminated butter pastry with custard or remonce. The Danish pastry as eaten in Copenhagen bakeries.", "kw": ["wienerbrød", "danish pastry"]}, {"id": "kobenhavn-stjerneskud", "name": "Stjerneskud", "local": "", "icon": "🐟", "desc": "Fried and steamed plaice on buttered bread, topped with shrimp and caviar. A classic Copenhagen restaurant dish.", "kw": ["stjerneskud"]}, {"id": "kobenhavn-polse", "name": "Danish hot dog", "local": "Dansk pølse", "icon": "🌭", "desc": "Red sausage in a bun with remoulade and crispy onions, sold from pølsevogne across the city.", "kw": ["pølse", "hot dog"]}, {"id": "kobenhavn-flaeskesteg", "name": "Flæskesteg", "local": "", "icon": "🍖", "desc": "Roast pork with crackling, red cabbage and brown potatoes. A Danish staple on old Copenhagen menus.", "kw": ["flæskesteg"]}, {"id": "kobenhavn-rugbrod", "name": "Bornholm smoked herring", "local": "Bornholmer røget sild", "icon": "🐟", "desc": "Herring smoked in alder smokehouses on Bornholm, served with raw egg yolk and radish. Sold at the island's smokehouses.", "kw": ["røget sild", "bornholm", "sol over gudhjem"]}],
  koblenz: [{"id": "koblenz-hunsrueck-schinken", "name": "Hunsrück ham", "local": "Hunsrücker Schinken", "icon": "🥓", "desc": "Dry-cured, smoked ham from the hills just west of Koblenz, sliced thin for bread or hearty plates.", "kw": ["hunsrücker", "schinken"]}, {"id": "koblenz-hunsrueck-spiessbraten", "name": "Hunsrück Spießbraten", "local": "Hunsrücker Spießbraten", "icon": "🍖", "desc": "Pork marinated with onions and herbs, roasted on a spit over a beechwood fire and served with onions and spätzle or bread. The signature roast of the Hunsrück hills west of Koblenz.", "kw": ["spießbraten", "spiessbraten"]}, {"id": "koblenz-ajerkaese", "name": "Westerwald Eierkäse", "local": "Westerwälder Ajerkäse", "icon": "🍮", "desc": "Sweet baked dish of eggs, milk and sugar set into a firm slice, eaten as a dessert or snack. A traditional speciality of the Westerwald, the hills east of Koblenz.", "kw": ["ajerkäse", "eierkäse"]}, {"id": "koblenz-kappes-un-erwes", "name": "Kappes un Erwes", "local": "Kappes un Erwes", "icon": "🥬", "desc": "Sauerkraut topped with pea mash, often with smoked pork. A poor-man's dish of the Hunsrück, served in country inns around Koblenz.", "kw": ["kappes un erwes", "kappes"]}],
  koeln: [{"id": "koeln-himmel-un-aeaed", "name": "Himmel un Ääd", "local": "", "icon": "🥔", "desc": "Mashed potatoes with apple sauce and fried black pudding. Cologne's best-known Rhineland dish.", "kw": ["himmel un ääd", "himmel und ääd"]}, {"id": "koeln-halve-hahn", "name": "Halve Hahn", "local": "", "icon": "🥪", "desc": "Rye roll with aged Gouda, onions and mustard, a typical Cologne brewery-house order.", "kw": ["halve hahn", "halver hahn"]}, {"id": "koeln-koelscher-kaviar", "name": "Kölscher Kaviar", "local": "", "icon": "🌭", "desc": "Slices of black pudding served on a roll with onions, a local joke on caviar.", "kw": ["kölscher kaviar", "blutwurst"]}, {"id": "koeln-haemmchen", "name": "Kölsche Hämmchen", "local": "", "icon": "🍖", "desc": "Slow-cooked pork knuckle with sauerkraut and mashed potato, served in Cologne brewery houses.", "kw": ["hämmchen", "pork knuckle"]}],
  konstanz: [{"id": "konstanz-felchen", "name": "Lake Constance whitefish", "local": "Bodensee-Felchen", "icon": "🐟", "desc": "The lake's signature fish, served pan-fried Müllerin style, blue-poached or smoked, with boiled potatoes.", "kw": ["felchen", "whitefish"]}, {"id": "konstanz-kretzer", "name": "Kretzer fillets", "local": "Kretzerfilets", "icon": "🐟", "desc": "Small perch fillets from the lake, fried in butter and served with potatoes and salad. Found on Konstanz menus year round.", "kw": ["kretzer", "perch", "egli"]}, {"id": "konstanz-hechtkloesse", "name": "Pike dumplings", "local": "Hechtklöße", "icon": "🍲", "desc": "Light dumplings of pike mousse poached and served in a creamy sauce. A traditional lake-side fish dish.", "kw": ["hechtklöße", "pike"]}, {"id": "konstanz-schupfnudeln", "name": "Schupfnudeln", "local": "", "icon": "🥔", "desc": "Finger-shaped potato noodles fried in butter, often with sauerkraut or bacon. A common dish on Konstanz inn menus.", "kw": ["schupfnudeln"]}],
  konya: [{"id": "konya-etli-ekmek", "name": "Konya etli ekmek", "local": "Etli ekmek", "icon": "🥖", "desc": "Thin, long dough topped with seasoned minced meat and baked in a very hot oven. It looks like lahmacun but is a different dish, and Konya's best-known meal.", "kw": ["etli ekmek"]}, {"id": "konya-firin-kebabi", "name": "Fırın kebabı", "local": "", "icon": "🍖", "desc": "Lamb ribs and foreleg slow-cooked for hours in a wood oven in their own fat, served with raw onion. A Konya kebap-house classic.", "kw": ["fırın kebabı", "fırın kebap"]}, {"id": "konya-bamya-corbasi", "name": "Bamya çorbası", "local": "", "icon": "🥣", "desc": "Soup of dried okra strung on thread, with small cubes of veal and lemon juice. A Konya wedding and festive-table soup.", "kw": ["bamya çorbası", "bamya"]}, {"id": "konya-su-boregi", "name": "Konya su böreği", "local": "Su böreği", "icon": "🥧", "desc": "Layers of handmade yufka dough, boiled first and then baked, eaten hot in the morning with black tea. A staple of Konya breakfast tables.", "kw": ["su böreği"]}, {"id": "konya-sacarasi", "name": "Sacarası", "local": "", "icon": "🍰", "desc": "Sweet traditionally baked between two griddles over wood embers, though oven versions exist. A homely Konya dessert found in local sweet shops.", "kw": ["sacarası"]}],
  larochelle: [{"id": "larochelle-mouclade", "name": "Mouclade", "local": "Mouclade charentaise", "icon": "🦪", "desc": "Bouchot mussels in a creamy, gently curried sauce. The mussels come from the Bay of Aiguillon and the dish is the classic order on the Charente coast.", "kw": ["mouclade", "mussel"]}, {"id": "larochelle-chaudree", "name": "Chaudrée", "local": "", "icon": "🍲", "desc": "A Charentaise fish stew with white wine, built on a mix of small sea fish. The local cousin of Brittany's cotriade and often compared to bouillabaisse.", "kw": ["chaudrée", "fish stew"]}, {"id": "larochelle-galette-charentaise", "name": "Galette charentaise", "local": "", "icon": "🍪", "desc": "A soft, buttery regional cake flavoured with candied angelica. Eaten with coffee or as an afternoon snack across Charente-Maritime.", "kw": ["galette charentaise", "angelica"]}, {"id": "larochelle-grillon-charentais", "name": "Grillon charentais", "local": "", "icon": "🐖", "desc": "Slow-cooked, seasoned pork eaten on fresh bread, traditionally as an aperitif or picnic food. Less known to visitors but a local favourite.", "kw": ["grillon"]}, {"id": "larochelle-cagouilles", "name": "Cagouilles", "local": "Cagouilles charentaises", "icon": "🐌", "desc": "Small grey snails of the Charente, pan-fried or stewed slowly in white wine with a touch of cognac. A rustic dish of the region.", "kw": ["cagouille", "snail"]}],
  lausanne: [{"id": "lausanne-papet-vaudois", "name": "Papet vaudois", "local": "", "icon": "🥔", "desc": "Leeks stewed with potatoes until soft, served with a smoked Vaud sausage (saucisson vaudois or saucisse aux choux). The canton's signature winter dish, found in country restaurants and at autumn butcher events.", "kw": ["papet vaudois", "papet", "saucisson vaudois"]}, {"id": "lausanne-taille-greubons", "name": "Taillé aux greubons", "local": "", "icon": "🥐", "desc": "Flaky savoury pastry studded with pork cracklings, a Vaud bakery classic since the late 19th century. Eaten at aperitif time or with a bowl of soup.", "kw": ["taillé aux greubons", "greubons", "taillé"]}, {"id": "lausanne-malakoff", "name": "Malakoff", "local": "", "icon": "🧀", "desc": "A deep-fried cheese fritter with a soft, molten centre, born in the La Côte villages around Vinzel and Luins. Served hot with salad or as a snack in local cafés.", "kw": ["malakoff"]}, {"id": "lausanne-vacherin-mont-dor", "name": "Vacherin Mont-d'Or", "local": "", "icon": "🫕", "desc": "Soft, spruce-banded winter cheese made in the Vallée de Joux and the Jura of Vaud, eaten baked in its box with potatoes. Sold only from autumn to spring.", "kw": ["vacherin", "mont-d'or", "mont d'or"]}, {"id": "lausanne-filets-perche", "name": "Perch fillets", "local": "Filets de perche", "icon": "🐟", "desc": "Small lake perch fillets, pan-fried in butter and served with fries or potatoes and lemon. A staple of the Lake Geneva shore restaurants from Lausanne to Vevey and Morges.", "kw": ["filets de perche", "perch"]}, {"id": "lausanne-salee-sucre", "name": "Salée au sucre", "local": "", "icon": "🥧", "desc": "A round of yeast dough topped with cream and sugar, a Vaud bakery and village tradition, listed in the canton's living-heritage inventory with the raisinée tarts. Best eaten warm.", "kw": ["salée", "raisinée", "tarte au sucre"]}],
  leeuwarden: [{"id": "leeuwarden-fries-suikerbrood", "name": "Fries suikerbrood", "local": "", "icon": "🍞", "desc": "Sweet bread studded with sugar lumps and cinnamon, eaten with butter. A staple of Friesland.", "kw": ["suikerbrood"]}, {"id": "leeuwarden-friese-nagelkaas", "name": "Friese nagelkaas", "local": "", "icon": "🧀", "desc": "Hard cheese spiced with cloves and cumin. The cheese of Friesland.", "kw": ["nagelkaas"]}, {"id": "leeuwarden-fryske-dumkes", "name": "Fryske dúmkes", "local": "", "icon": "🍪", "desc": "Small, crunchy, spiced cookies. A traditional Friesland treat.", "kw": ["dumkes", "dúmkes"]}, {"id": "leeuwarden-spekdikken", "name": "Spekdikken", "local": "", "icon": "🥞", "desc": "Small, thick, fluffy pancakes cooked in an indented pan and served with powdered sugar and currants. A traditional Frisian winter treat.", "kw": ["spekdikken"]}, {"id": "leeuwarden-friese-oranjekoek", "name": "Friese oranjekoek", "local": "", "icon": "🍰", "desc": "Orange-flavoured cake from Friesland. Served with butter or coffee.", "kw": ["oranjekoek"]}],
  leipzig: [{"id": "leipzig-allerlei", "name": "Leipziger Allerlei", "local": "", "icon": "🥕", "desc": "Mixed spring vegetables with morels, crayfish and butter sauce. A Leipzig classic that varies from simple vegetable medleys to the refined original.", "kw": ["leipziger allerlei", "allerlei"]}, {"id": "leipzig-lerche", "name": "Leipziger Lerche", "local": "", "icon": "🥧", "desc": "Shortcrust tartlet with almond filling, topped with a cherry and two crossed pastry strips. It replaced the real songbirds once baked into it.", "kw": ["lerche"]}, {"id": "leipzig-raebchen", "name": "Leipziger Räbchen", "local": "", "icon": "🍩", "desc": "Prunes stuffed with marzipan, coated in batter, fried and rolled in cinnamon sugar. A warm Leipzig sweet, eaten around the Christmas market and in cafés.", "kw": ["räbchen"]}, {"id": "leipzig-eierschecke", "name": "Leipziger Eierschecke", "local": "", "icon": "🍰", "desc": "Three-layer cake of yeast dough, quark and egg custard. Saxon-wide, but baked in Leipzig's traditional cafés and bakeries.", "kw": ["eierschecke"]}],
  lemans: [{"id": "lemans-rillettes-du-mans", "name": "Rillettes du Mans", "local": "", "icon": "🥫", "desc": "Pork shoulder slow-cooked in fat and shredded, a protected local product. Spread on bread, it has been Le Mans' signature charcuterie since the 19th century.", "kw": ["rillettes"]}, {"id": "lemans-sable-sable", "name": "Sablés de Sablé", "local": "", "icon": "🍪", "desc": "Crumbly butter shortbread from Sablé-sur-Sarthe, plain or with sugar. Sold in tins and bakeries across the Sarthe.", "kw": ["sablé", "sable", "sablés"]}, {"id": "lemans-entrammes", "name": "Entrammes cheese", "local": "", "icon": "🧀", "desc": "Soft washed-rind cheese from the Mayenne, made by monks near Entrammes and descended from Port-Salut. Mild and creamy, with an orange rind.", "kw": ["entrammes"]}, {"id": "lemans-boudin-mortagne", "name": "Boudin noir de Mortagne", "local": "", "icon": "🌭", "desc": "Black pudding from Mortagne-au-Perche in the Orne, soft and spiced, fried and eaten with apples. The town hosts a yearly boudin fair.", "kw": ["boudin noir", "boudin"]}, {"id": "lemans-poulet-loue", "name": "Loué chicken", "local": "Poulet de Loué", "icon": "🍗", "desc": "Free-range label chicken from Loué in the Sarthe, raised on grain and eaten roast or in cream sauce. Served in Sarthe restaurants and bought at markets.", "kw": ["poulet de loué", "loué"]}],
  leuven: [{"id": "leuven-leuvense-stoverij", "name": "Leuven stoverij", "local": "Stoverij", "icon": "🍲", "desc": "Beef stewed in dark beer with mustard bread, the Flemish carbonade. In Leuven, home of a brewing tradition, beer sets it apart.", "kw": ["stoverij", "carbonade", "stoofvlees"]}, {"id": "leuven-witloof", "name": "Witloof gratin", "local": "Witloof met hesp en kaas", "icon": "🥬", "desc": "Chicory wrapped in ham and baked in cheese sauce. Flemish Brabant is the heart of Belgian chicory growing.", "kw": ["witloof", "chicory", "endive"]}, {"id": "leuven-hageland-aardbei", "name": "Hageland strawberries", "local": "", "icon": "🍓", "desc": "Local strawberries, fresh or in tarts, grown in the Hageland fruit and farm region east of Leuven.", "kw": ["strawberr", "aardbei"]}, {"id": "leuven-kaaskroket", "name": "Cheese croquette", "local": "Kaaskroket", "icon": "🧀", "desc": "Deep-fried croquette of melted cheese, found on Flemish brasserie menus.", "kw": ["kaaskroket", "cheese croquette"]}],
  lille: [{"id": "lille-welsh", "name": "Welsh", "local": "Le welsh", "icon": "🧀", "desc": "Toast and ham under a beer and cheddar sauce, baked and topped with a fried egg, often with Maroilles. Lille's signature estaminet dish.", "kw": ["welsh"]}, {"id": "lille-tarte-maroilles", "name": "Tarte au Maroilles", "local": "", "icon": "🥧", "desc": "A tart of strong Maroilles cheese and cream, served warm with chips or salad. A classic of Lille's estaminets.", "kw": ["maroilles"]}, {"id": "lille-carbonade", "name": "Carbonade flamande", "local": "", "icon": "🍖", "desc": "Beef slowly stewed with beer, onions and gingerbread. A Flemish estaminet favourite in Lille.", "kw": ["carbonade"]}, {"id": "lille-potjevleesch", "name": "Potjevleesch", "local": "", "icon": "🍗", "desc": "A cold terrine of chicken, pork, veal and rabbit set in aspic, served with chips. A speciality of French Flanders.", "kw": ["potjevleesch"]}, {"id": "lille-gaufre-fourree", "name": "Filled waffle", "local": "Gaufre fourrée", "icon": "🧇", "desc": "A thin waffle filled with vanilla or brown sugar syrup, a Lille sweet since the 19th century. Sold in bakeries and boutiques.", "kw": ["gaufre", "waffle"]}, {"id": "lille-moules-frites", "name": "Moules-frites", "local": "", "icon": "🍟", "desc": "Mussels in white wine served with chips, the signature dish of the nearby Flemish coast. Served at the Braderie de Lille and in many brasseries.", "kw": ["moules-frites", "moules frites"]}],
  limoges: [{"id": "limoges-boudin-aux-chataignes", "name": "Chestnut black pudding", "local": "Boudin noir aux châtaignes", "icon": "🌭", "desc": "Limousin black pudding made with chestnuts, grilled in a pan and served with fried onions and caramelised apples from the region.", "kw": ["boudin", "chestnut"]}, {"id": "limoges-clafoutis-limousin", "name": "Limousin clafoutis", "local": "Clafoutis", "icon": "🍒", "desc": "A batter cake traditionally baked with whole cherries and their pits. Made with other fruit it is called flognarde. The best-known dessert of the Limousin.", "kw": ["clafoutis", "flognarde"]}, {"id": "limoges-galette-de-pommes-de-terre", "name": "Limousin potato pie", "local": "Pâté de pommes de terre", "icon": "🥔", "desc": "A savory pie of potatoes, sometimes with meat, in a brioche-style crust in Haute-Vienne. Sold warm at the central market and by local bakers.", "kw": ["potato pie", "pommes de terre"]}, {"id": "limoges-galetou", "name": "Galetou", "local": "", "icon": "🥞", "desc": "A rustic buckwheat pancake once used as bread, usually rolled around rillettes or cracklings. Found at the central market in Limoges.", "kw": ["galetou"]}, {"id": "limoges-marzipan-saint-leonard", "name": "Saint-Léonard marzipan", "local": "Massepain de Saint-Léonard", "icon": "🍬", "desc": "Almond, egg white and sugar sweet, crisp and golden outside, soft inside. Made in Saint-Léonard-de-Noblat, near Limoges, and said to have come with pilgrims.", "kw": ["marzipan", "massepain"]}],
  luebeck: [{"id": "luebeck-marzipan", "name": "Lübecker Marzipan", "local": "", "icon": "🍫", "desc": "Almond marzipan made in Lübeck since the 19th century, in pralines, loaves and cakes.", "kw": ["marzipan"]}, {"id": "luebeck-schwalbennester", "name": "Lübecker Schwalbennester", "local": "", "icon": "🥩", "desc": "Veal roulades filled with ham and egg, braised in gravy. A traditional dish of Lübeck.", "kw": ["schwalbennester"]}, {"id": "luebeck-plockfinken", "name": "Plockfinken", "local": "", "icon": "🍲", "desc": "Hearty stew of beef, potatoes and vegetables, an old Lübeck kitchen classic.", "kw": ["plockfinken"]}, {"id": "luebeck-raeucherfisch", "name": "Baltic smoked fish", "local": "Ostsee-Räucherfisch", "icon": "🐟", "desc": "Smoked eel, sprats and herring from the Baltic coast near Travemünde, sold at harbour stalls.", "kw": ["räucherfisch", "smoked fish", "aal"]}],
  lugano: [{"id": "lugano-polenta-ticinese", "name": "Polenta ticinese", "local": "", "icon": "🌽", "desc": "Slow-cooked cornmeal, served with braised meat, cheese or mushrooms. The old staple of Ticino, found in the grottos around Lugano.", "kw": ["polenta"]}, {"id": "lugano-luganighe", "name": "Luganighe", "local": "Luganighetta", "icon": "🌭", "desc": "Fresh pork sausage of Lugano and Ticino, grilled or cooked in risotto. It is traditionally served with polenta and opens Lugano's carnival.", "kw": ["luganighe", "luganighetta", "luganega"]}, {"id": "lugano-risotto-ticinese", "name": "Risotto ticinese", "local": "", "icon": "🍚", "desc": "Creamy risotto with local rice and Merlot or sausage, a Ticino staple. Almost every grotto and restaurant in the Lugano area has one.", "kw": ["risotto"]}, {"id": "lugano-brasato-merlot", "name": "Brasato al Merlot", "local": "", "icon": "🥩", "desc": "Beef slowly braised in Merlot, served with polenta. A hearty Ticino main course found in grottos and trattorias.", "kw": ["brasato"]}, {"id": "lugano-torta-di-pane", "name": "Torta di pane", "local": "", "icon": "🍰", "desc": "Dense bread pudding with raisins, pine nuts and sometimes cocoa. A traditional Ticino cake found in bakeries and pasticcerie of the Lugano region.", "kw": ["torta di pane"]}],
  luik: [{"id": "luik-luikse-wafel", "name": "Liège waffle", "local": "Gaufre de Liège", "icon": "🧇", "desc": "Dense, chewy yeast waffle with caramelised pearl sugar, eaten warm from street stalls. It is Liège's best-known food.", "kw": ["liège waffle", "liege waffle", "gaufre"]}, {"id": "luik-boulets", "name": "Boulets liégeois", "local": "Boulets à la liégeoise", "icon": "🍖", "desc": "Large meatballs in a sweet-sour sauce of Liège syrup, onion and apple, served with fries.", "kw": ["boulets", "boulet"]}, {"id": "luik-salade-liegeoise", "name": "Salade liégeoise", "local": "", "icon": "🥗", "desc": "Warm salad of green beans, potatoes, bacon and vinegar, a Liège home dish.", "kw": ["salade liégeoise", "liégeoise"]}, {"id": "luik-herve", "name": "Herve cheese", "local": "Fromage de Herve", "icon": "🧀", "desc": "Strong washed-rind cheese from the plateau east of Liège, made since the Middle Ages. Soft and pungent.", "kw": ["herve"]}, {"id": "luik-sirop-de-liege", "name": "Sirop de Liège", "local": "", "icon": "🍯", "desc": "Thick dark syrup of apples and pears, spread on bread or used in cooking. A Walloon pantry staple.", "kw": ["sirop"]}, {"id": "luik-tarte-riz", "name": "Tarte au riz", "local": "", "icon": "🥧", "desc": "Rice-pudding tart from Verviers and the East Cantons, sold in bakeries.", "kw": ["tarte au riz", "rice tart"]}],
  luxembourg: [{"id": "luxembourg-judd", "name": "Judd mat Gaardebounen", "local": "", "icon": "🥓", "desc": "Smoked pork collar with broad beans in cream sauce, the national dish of Luxembourg.", "kw": ["judd", "gaardebounen"]}, {"id": "luxembourg-gromperekichelcher", "name": "Gromperekichelcher", "local": "", "icon": "🥔", "desc": "Fried potato fritters with onion and parsley, eaten with apple sauce at markets and fairs.", "kw": ["gromperekichelcher", "potato fritter"]}, {"id": "luxembourg-bouneschlupp", "name": "Bouneschlupp", "local": "", "icon": "🍲", "desc": "Green bean soup with potatoes, bacon and cream, a traditional Luxembourg soup.", "kw": ["bouneschlupp", "bean soup"]}, {"id": "luxembourg-traipen", "name": "Träipen", "local": "", "icon": "🌭", "desc": "Blood sausage served with mashed potatoes and apple sauce, a Luxembourg dish.", "kw": ["träipen", "traipen", "black pudding"]}, {"id": "luxembourg-rieslingspaschtei", "name": "Rieslingspaschtéit", "local": "", "icon": "🥧", "desc": "Pastry pie of pork, veal and jelly, a classic Luxembourg delicatessen item.", "kw": ["paschtéit", "pâté"]}, {"id": "luxembourg-kniddelen", "name": "Kniddelen", "local": "", "icon": "🥟", "desc": "Soft flour dumplings with bacon, from the Luxembourg home kitchen.", "kw": ["kniddelen", "dumpling"]}],
  luzern: [{"id": "luzern-chuegelipastete", "name": "Luzerner Chügelipastete", "local": "", "icon": "🥧", "desc": "Puff-pastry case filled with small meatballs, mushrooms and cream sauce. Traditional in Lucerne since the 18th century and found in the city's old restaurants.", "kw": ["chügelipastete", "chuegelipastete"]}, {"id": "luzern-aelplermagronen", "name": "Älplermagronen", "local": "", "icon": "🍝", "desc": "Macaroni baked with potato, cheese, cream and onion, served with apple sauce. The Alpine herders' dish of central Switzerland, which Lucerne restaurants cook as a staple.", "kw": ["älplermagronen", "aelplermagronen"]}, {"id": "luzern-lebkuchen", "name": "Luzerner Lebkuchen", "local": "", "icon": "🍯", "desc": "Spiced pear-juice honey bread, a Lucerne winter sweet. Its pear syrup comes from the orchards of the Lucerne hinterland.", "kw": ["lebkuchen"]}, {"id": "luzern-birewegge", "name": "Birewegge", "local": "", "icon": "🍐", "desc": "Pear bread, a pastry stuffed with dried pears, walnuts, figs and raisins. A traditional central Swiss speciality that is eaten around Lucerne.", "kw": ["birewegge", "pear bread"]}, {"id": "luzern-rueblitorte", "name": "Rüeblitorte", "local": "", "icon": "🥕", "desc": "Carrot and almond cake, a Swiss classic baked in Lucerne's bakeries. It is often glazed with marzipan carrots.", "kw": ["rüeblitorte", "carrot cake"]}],
  lyon: [{"id": "lyon-quenelle", "name": "Quenelles de brochet", "local": "Quenelle lyonnaise", "icon": "🐟", "desc": "Light poached pike dumplings in a creamy Nantua crayfish sauce. A signature of Lyon's bouchons.", "kw": ["quenelle"]}, {"id": "lyon-salade-lyonnaise", "name": "Salade lyonnaise", "local": "", "icon": "🥗", "desc": "Curly endive with bacon, croutons and a poached egg in a hot vinegar dressing. The standard bouchon starter.", "kw": ["salade lyonnaise"]}, {"id": "lyon-tablier", "name": "Tablier de sapeur", "local": "", "icon": "🥩", "desc": "Breaded and fried tripe, served with gribiche sauce. A bouchon favourite named after the firefighter's apron.", "kw": ["tablier de sapeur", "tablier"]}, {"id": "lyon-rosette", "name": "Rosette de Lyon", "local": "", "icon": "🥓", "desc": "A dry-cured pork sausage sliced thin, the city's classic charcuterie. Found in bouchons and the Halles.", "kw": ["rosette"]}, {"id": "lyon-saucisson-brioche", "name": "Saucisson brioché", "local": "", "icon": "🥖", "desc": "Hot Lyon sausage baked inside soft brioche dough, sold in bakeries and charcuteries and eaten on the go.", "kw": ["saucisson brioché", "brioche"]}, {"id": "lyon-tarte-pralines", "name": "Tarte aux pralines", "local": "Tarte à la praline", "icon": "🥧", "desc": "A tart covered in a pink sugared almond filling, the city's most recognisable dessert. Sold in bakeries across Lyon.", "kw": ["pralines", "praline"]}, {"id": "lyon-cervelle-canut", "name": "Cervelle de canut", "local": "", "icon": "🧄", "desc": "Fresh cheese whipped with herbs, shallots, garlic and white wine, spread on bread. A Lyon bouchon starter named after the silk workers.", "kw": ["cervelle de canut", "canut"]}],
  maastricht: [{"id": "maastricht-limburgse-vlaai", "name": "Limburgse vlaai", "local": "", "icon": "🥧", "desc": "Wide, shallow fruit pie with a yeast base. The pride of Limburg's bakeries, with cherry and apricot as favourites.", "kw": ["vlaai"]}, {"id": "maastricht-rijstevlaai", "name": "Rijstevlaai", "local": "", "icon": "🥧", "desc": "Vlaai filled with sweet rice pudding. A Limburg classic.", "kw": ["rijstevlaai"]}, {"id": "maastricht-zoervleisj", "name": "Maastrichts zoervleisj", "local": "Zoervleisj", "icon": "🥩", "desc": "Marinated beef stew in vinegar, onion and gingerbread. Served in Maastricht restaurants with fries or bread.", "kw": ["zoervleisj", "zuurvlees"]}, {"id": "maastricht-limburgse-appelstroop", "name": "Limburg appelstroop", "local": "Appelstroop", "icon": "🍎", "desc": "Thick apple syrup from Limburg orchards, spread on bread. A regional pantry staple.", "kw": ["appelstroop", "stroop"]}],
  magdeburg: [{"id": "magdeburg-boetel", "name": "Bötel mit Lehm und Stroh", "local": "", "icon": "🍖", "desc": "Boiled pork knuckle with pea purée and sauerkraut. The purée is the clay and the sauerkraut the straw. Found at Magdeburg old-town inns.", "kw": ["bötel", "lehm und stroh"]}, {"id": "magdeburg-bollwurst", "name": "Bollwurst", "local": "", "icon": "🌭", "desc": "Spreadable cooked pork sausage seasoned with onions, from the Magdeburger Börde. Eaten on bread.", "kw": ["bollwurst"]}, {"id": "magdeburg-pottsuse", "name": "Pottsuse", "local": "", "icon": "🥫", "desc": "Pork and lard spread with spices, a traditional farmhouse spread from the Börde. Eaten on dark bread.", "kw": ["pottsuse"]}, {"id": "magdeburg-baumkuchen", "name": "Salzwedeler Baumkuchen", "local": "", "icon": "🎂", "desc": "Layered cake baked on a rotating spit, built up ring by ring. Salzwedel in the Altmark is its traditional home.", "kw": ["baumkuchen"]}, {"id": "magdeburg-grutzwurst", "name": "Grützwurst with red cabbage", "local": "", "icon": "🌭", "desc": "Sausage of groats and pork, served with apple red cabbage. Altmark winter dish.", "kw": ["grützwurst"]}],
  mainz: [{"id": "mainz-spundekaes", "name": "Spundekäs", "local": "", "icon": "🧀", "desc": "Soft spread of cream cheese, quark and paprika served with pretzels and raw onion. The classic bite in Mainz wine taverns.", "kw": ["spundekäs"]}, {"id": "mainz-worscht-weck", "name": "Worscht and Weck", "local": "Worscht un Weck", "icon": "🌭", "desc": "Warm sausage (often Fleischwurst or Lyoner) with a crusty bread roll and mustard. The standard Rheinhessen wine-tavern snack.", "kw": ["worscht", "fleischwurst"]}, {"id": "mainz-backesgrumbeere", "name": "Backesgrumbeere", "local": "", "icon": "🥔", "desc": "Potato casserole baked with bacon, onion and sour cream, with origins in Rheinhessen. Found in the wine taverns of Mainz and the villages around it.", "kw": ["backesgrumbeere", "backesgrumbeer"]}, {"id": "mainz-mainzer-kartoffelsuppe", "name": "Mainz potato stew", "local": "Kartoffelsuppe mit Fleischwurst", "icon": "🥣", "desc": "Thick potato stew with bacon and Fleischwurst slices. Home-style winter food served in local Weinstuben.", "kw": ["kartoffelsuppe", "kartoffeleintopf"]}],
  malatya: [{"id": "malatya-kiraz-yapragi", "name": "Cherry-leaf rolls", "local": "Kiraz yaprağı sarması", "icon": "🍃", "desc": "Young cherry leaves wrapped around a filling of bulgur or split peas and meat, then simmered. A signature of the Malatya orchard country and available in local restaurants in season.", "kw": ["kiraz yaprağı", "yaprak sarma"]}, {"id": "malatya-kagit-kebabi", "name": "Kağıt kebabı", "local": "", "icon": "🍖", "desc": "Lamb and vegetables cooked wrapped in paper in a stone oven so the juices stay in. A Malatya way of cooking that is easy to find in the city.", "kw": ["kağıt kebabı", "kagit"]}, {"id": "malatya-kayisi-tatlisi", "name": "Apricot dessert with kaymak", "local": "Kayısı tatlısı", "icon": "🍑", "desc": "Whole Malatya apricots cooked in syrup and served with thick clotted cream and nuts. The province grows a large share of the world's dried apricots.", "kw": ["kayısı tatlısı", "kayısı", "apricot"]}, {"id": "malatya-girik", "name": "Gırık", "local": "Malatya gırık", "icon": "🥣", "desc": "Meatballs of bulgur and minced meat served in a light, sour broth. A Malatya home-style dish from the region's long bulgur tradition.", "kw": ["gırık", "sulu köfte"]}, {"id": "malatya-pestil", "name": "Malatya pestil and kesmece", "local": "Erik pestili, kesmece", "icon": "🍇", "desc": "Sheets of dried plum, mulberry or apricot fruit leather, often cut and eaten with walnuts. A traditional Malatya sweet sold in bazaar shops.", "kw": ["pestil", "kesmece"]}],
  malmo: [{"id": "malmo-falafel", "name": "Falafel roll", "local": "Falafelrulle", "icon": "🧆", "desc": "Falafel in flatbread with sauce and pickles. A Malmö street food closely tied to the city's Middle Eastern community.", "kw": ["falafel"]}, {"id": "malmo-kanelbulle", "name": "Kanelbulle", "local": "", "icon": "🥐", "desc": "Swedish cinnamon bun, baked fresh in Malmö and Lund bakeries and eaten with fika.", "kw": ["kanelbulle", "cinnamon bun"]}, {"id": "malmo-spettekaka", "name": "Spettekaka", "local": "", "icon": "🍰", "desc": "Tall cake made of eggs, sugar and potato flour, baked on a rotating spit. A Skåne speciality sold in Lund and Malmö shops.", "kw": ["spettekaka"]}, {"id": "malmo-sill", "name": "Inlagd sill", "local": "", "icon": "🐟", "desc": "Herring in spiced vinegar, eaten with potatoes and crispbread. A staple of the Skåne coast.", "kw": ["sill", "herring"]}, {"id": "malmo-alagille", "name": "Ålagille", "local": "", "icon": "🐟", "desc": "Smoked eel with scrambled egg and potatoes, a late-summer tradition in Skåne served in coastal restaurants.", "kw": ["ål", "ålagille"]}, {"id": "malmo-kottbullar", "name": "Köttbullar", "local": "", "icon": "🍖", "desc": "Swedish meatballs with lingonberry jam, cream sauce and potatoes, served in traditional restaurants in Malmö.", "kw": ["köttbullar"]}],
  mannheim: [{"id": "mannheim-saumagen", "name": "Saumagen", "local": "", "icon": "🍖", "desc": "Pork, potato and spice stuffing cooked in a pig's stomach, sliced and fried, served with sauerkraut. A Palatinate dish that Mannheim shares as the region's big city.", "kw": ["saumagen"]}, {"id": "mannheim-mannemer-dreck", "name": "Mannemer Dreck", "local": "", "icon": "🍬", "desc": "Chocolate-coated macaroon sweet invented in Mannheim in 1862. A local confection with a deliberately cheeky name.", "kw": ["mannemer dreck"]}, {"id": "mannheim-dampfnudeln", "name": "Dampfnudeln with wine sauce", "local": "Dampfnudeln mit Weinschaum", "icon": "🍞", "desc": "Yeast dumplings steamed and browned in the pan, with a crisp base, served with warm wine custard. A Palatinate Sunday dish.", "kw": ["dampfnudel"]}, {"id": "mannheim-pfaelzer-leberknoedel", "name": "Palatinate Leberknödel", "local": "Pfälzer Leberknödel", "icon": "🍲", "desc": "Liver dumplings with sauerkraut and potatoes. Standard fare in Kurpfalz taverns around the Rhine-Neckar.", "kw": ["leberknödel"]}, {"id": "mannheim-zwiebelkuchen", "name": "Zwiebelkuchen", "local": "", "icon": "🥧", "desc": "Savoury tart of onions, bacon and cream on yeast dough, served in autumn. A Palatinate wine-region tradition.", "kw": ["zwiebelkuchen"]}],
  mardin: [{"id": "mardin-kaburga", "name": "Mardin kaburga dolması", "local": "Kaburga dolması", "icon": "🍖", "desc": "Lamb ribs stuffed with spiced rice, minced meat and nuts, then slow-cooked for hours. A protected-origin dish and the centrepiece of Mardin celebration tables.", "kw": ["kaburga dolması", "kaburga"]}, {"id": "mardin-kibe", "name": "Mardin kibe", "local": "Kibe", "icon": "🥟", "desc": "Bulgur shell stuffed with spiced minced meat and onion, fried or boiled; the city also does a tripe-wrapped version. A core dish of Mardin's Syriac and Arab kitchens.", "kw": ["kibe", "içli köfte"]}, {"id": "mardin-ikbebet", "name": "İkbebet", "local": "", "icon": "🥗", "desc": "Layers of boiled bulgur and ground meat mixed with pomegranate or sumac-style tang and herbs, served cool. A protected Mardin speciality.", "kw": ["ikbebet"]}, {"id": "mardin-sembusek", "name": "Sembusek", "local": "", "icon": "🥟", "desc": "Crescent-shaped pastry filled with minced meat and onion, fried or baked. Part of Mardin's Syriac food tradition and a protected-origin product.", "kw": ["sembusek"]}, {"id": "mardin-badem-sekeri", "name": "Mardin almond candy", "local": "Mardin badem şekeri", "icon": "🍬", "desc": "Small pale sweets made from ground almonds and sugar. Mardin is known for it and shops in the old town sell it by weight.", "kw": ["badem şekeri", "almond"]}],
  marseille: [{"id": "marseille-bouillabaisse", "name": "Bouillabaisse", "local": "", "icon": "🍲", "desc": "The famous Marseille fish stew, a dish with centuries of history rooted in a humble Greek-style fishermen's stew. Served at the port as broth and fish together.", "kw": ["bouillabaisse"]}, {"id": "marseille-navette", "name": "Navettes de Marseille", "local": "", "icon": "🍪", "desc": "Boat-shaped orange-blossom biscuits, the Marseille sweet best suited to taking home. They travel well and are sold in bakeries across the city.", "kw": ["navette", "navettes"]}, {"id": "marseille-panisse", "name": "Panisses", "local": "", "icon": "🍟", "desc": "Fried chickpea-flour fritters, a popular street snack in Marseille and especially associated with L'Estaque. Crisp outside, soft inside, and meat-free.", "kw": ["panisse", "panisses"]}, {"id": "marseille-pieds-paquets", "name": "Pieds paquets", "local": "", "icon": "🥘", "desc": "Lamb tripe parcels stuffed with salted pork, garlic and parsley, simmered in white wine and tomato. A Marseille dish credited to a cook of La Pomme district in 1880.", "kw": ["pieds paquets", "pieds et paquets"]}, {"id": "marseille-calisson", "name": "Calissons d'Aix", "local": "", "icon": "🍬", "desc": "Almond-and-melon-paste sweets with a royal icing top, from Aix-en-Provence. One of the traditional thirteen desserts of a Provençal Christmas.", "kw": ["calisson", "calissons"]}, {"id": "marseille-chichi", "name": "Chichis", "local": "", "icon": "🍩", "desc": "Sweet fried dough fritters, a traditional Marseille treat. Eaten warm, often in the L'Estaque district.", "kw": ["chichi", "chichis"]}],
  mersin: [{"id": "mersin-tantuni", "name": "Tantuni", "local": "", "icon": "🌯", "desc": "Finely chopped beef sautéed on a hot plate with tomato, pepper and oil, wrapped in thin lavash. Mersin's best-known street food.", "kw": ["tantuni"]}, {"id": "mersin-cezerye", "name": "Cezerye", "local": "", "icon": "🥕", "desc": "A chewy sweet made from carrot syrup, coconut and nuts, a speciality of Tarsus and Mersin. Sold in boxes as the souvenir of the coast.", "kw": ["cezerye"]}, {"id": "mersin-batirik", "name": "Batırık", "local": "", "icon": "🥗", "desc": "A thick Tarsus dish of bulgur, chickpeas and herbs, closer to a main course than a soup. Eaten at local lokantas.", "kw": ["batırık", "batirik"]}, {"id": "mersin-kerebic", "name": "Kerebiç", "local": "", "icon": "🍰", "desc": "A rolled sweet with pistachio or walnut and syrup, associated with Silifke and Cilicia. Often eaten at celebrations.", "kw": ["kerebiç", "kerebic"]}, {"id": "mersin-yuksuk-corbasi", "name": "Yüksük çorbası", "local": "", "icon": "🍜", "desc": "A soup of tiny dumplings in a yogurt and chickpea broth, a dish of the Cilician plain. Served at Mersin home-cooking restaurants.", "kw": ["yüksük", "yuksuk"]}],
  metz: [{"id": "metz-quiche-lorraine", "name": "Quiche Lorraine", "local": "", "icon": "🥧", "desc": "Shortcrust tart filled with eggs, crème fraîche and smoked bacon, with no cheese in the traditional version. The Moselle's classic dish, dating back to the 16th century.", "kw": ["quiche lorraine", "quiche"]}, {"id": "metz-mirabelle-tart", "name": "Mirabelle tart", "local": "Tarte aux mirabelles", "icon": "🥧", "desc": "Small golden mirabelle plums baked whole on a short pastry base. Lorraine grows most of the world's mirabelles, and the tart is eaten mainly in late summer.", "kw": ["mirabelle", "tarte aux mirabelles"]}, {"id": "metz-boulay-macarons", "name": "Macarons de Boulay", "local": "", "icon": "🍪", "desc": "Chewy almond macarons of egg white, almond powder and sugar, made to the same recipe in the Moselle town of Boulay since 1854. About 30 minutes from Metz.", "kw": ["macaron", "boulay"]}, {"id": "metz-madeleine-commercy", "name": "Madeleine de Commercy", "local": "", "icon": "🧁", "desc": "Small shell-shaped butter sponge cake from Commercy in the Meuse, said to have been improvised by a servant for Duke Stanislas. Sold as a Lorraine take-home treat.", "kw": ["madeleine", "commercy"]}, {"id": "metz-potee-lorraine", "name": "Potée lorraine", "local": "", "icon": "🥘", "desc": "Winter pot of cabbage, carrots, potatoes, smoked sausages and pork shank simmered together. A hearty Lorraine farmhouse dish found on traditional menus.", "kw": ["potée lorraine", "potée"]}],
  middelburg: [{"id": "middelburg-zeeuwse-bolus", "name": "Zeeuwse bolus", "local": "", "icon": "🍥", "desc": "Sticky, spiral cinnamon-sugar bun from Zeeland. A bakery speciality of Middelburg and Zeeland.", "kw": ["bolus"]}, {"id": "middelburg-zeeuwse-mosselen", "name": "Zeeland mussels", "local": "Zeeuwse mosselen", "icon": "🦪", "desc": "Mussels from the Oosterschelde, steamed with vegetables, in season from July to April.", "kw": ["mosselen", "mussels"]}, {"id": "middelburg-zeeuwse-oesters", "name": "Zeeland oysters", "local": "Zeeuwse oesters", "icon": "🦪", "desc": "Oysters from Yerseke and the Oosterschelde, eaten raw. Zeeland's seafood heritage.", "kw": ["oesters", "oysters"]}, {"id": "middelburg-zeeuwse-babbelaars", "name": "Zeeuwse babbelaars", "local": "", "icon": "🍬", "desc": "Butterscotch toffees from Zeeland. A traditional local candy.", "kw": ["babbelaar"]}, {"id": "middelburg-zeeuwse-kreeft", "name": "Oosterschelde lobster", "local": "Kreeft", "icon": "🦞", "desc": "Lobster from Yerseke's lobster ponds. Found at Zeeland seafood restaurants.", "kw": ["kreeft", "lobster"]}],
  mons: [{"id": "mons-tarte-maton", "name": "Tarte au maton", "local": "", "icon": "🥧", "desc": "Sweet cheese tart made with curds, a Mons and Hainaut bakery speciality.", "kw": ["maton"]}, {"id": "mons-escaveche", "name": "Escavèche", "local": "", "icon": "🐟", "desc": "Fish cooked and served cold in a vinegar and onion marinade, a traditional dish of Hainaut.", "kw": ["escavèche", "escaveche"]}, {"id": "mons-chimay-cheese", "name": "Chimay cheese", "local": "Fromage de Chimay", "icon": "🧀", "desc": "Semi-soft cheese from the monastery at Chimay in south Hainaut, found in local shops and cafes.", "kw": ["chimay"]}, {"id": "mons-boulette-lapin", "name": "Boulettes sauce lapin", "local": "", "icon": "🍖", "desc": "Meatballs in a sweet and sour rabbit-style sauce, common in Mons and Charleroi brasseries.", "kw": ["boulette", "lapin"]}],
  montpellier: [{"id": "montpellier-tielle", "name": "Tielle sétoise", "local": "Tielle sétoise", "icon": "🥧", "desc": "A slightly brioche-like pie filled with octopus, tomato, onion, chilli and white wine, a recipe brought by fishermen from Gaeta. A Sète speciality that Montpellier has adopted.", "kw": ["tielle"]}, {"id": "montpellier-petits-pates", "name": "Petits pâtés de Pézenas", "local": "Petits pâtés de Pézenas", "icon": "🥟", "desc": "Spool-shaped pastries mixing lamb with lemon and brown sugar, sweet and savoury at once. Pézenas has made them since the 18th century and eaten slightly warmed as a starter.", "kw": ["pâtés de pézenas", "petits pâtés"]}, {"id": "montpellier-macaronade", "name": "Macaronade sétoise", "local": "Macaronade sétoise", "icon": "🍝", "desc": "A Sète dish of macaroni with slow-cooked beef brageoles, pork and tomato sauce, hearty and traditional on the Hérault coast.", "kw": ["macaronade"]}, {"id": "montpellier-brasucade", "name": "Brasucade de moules", "local": "Brasucade de moules", "icon": "🦪", "desc": "Mussels from the Thau lagoon cooked in a big pan over a vine-cutting fire, doused with scented olive oil and eaten with the fingers.", "kw": ["brasucade", "mussels"]}, {"id": "montpellier-oreillettes", "name": "Oreillettes", "local": "Oreillettes", "icon": "🍪", "desc": "Thin, crisp fritters made from a doughnut-type dough and dusted with sugar, served at traditional festivals and sold at Montpellier bakeries.", "kw": ["oreillettes"]}],
  muenchen: [{"id": "muenchen-weisswurst", "name": "Weißwurst", "local": "", "icon": "🌭", "desc": "Pale veal and pork sausage simmered in water, eaten with sweet mustard, usually before noon. The best-known Munich dish.", "kw": ["weißwurst", "weisswurst"]}, {"id": "muenchen-brezn", "name": "Bavarian pretzel", "local": "Brezn", "icon": "🥨", "desc": "Large soft pretzel with a dark crust and coarse salt. Sold in bakeries and beer gardens throughout the city.", "kw": ["brezn", "brezel", "pretzel"]}, {"id": "muenchen-schweinshaxe", "name": "Schweinshaxe", "local": "", "icon": "🍖", "desc": "Roasted pork knuckle with crackling, served with dumplings and cabbage. The centrepiece of beer-hall menus.", "kw": ["schweinshaxe", "haxe"]}, {"id": "muenchen-obatzda", "name": "Obatzda", "local": "", "icon": "🧀", "desc": "Cheese spread made from ripe Camembert, butter, paprika and onions, eaten with pretzels in beer gardens.", "kw": ["obatzda", "obazda"]}, {"id": "muenchen-leberkaese", "name": "Leberkäse", "local": "", "icon": "🥪", "desc": "Baked loaf of finely minced meat, served hot in thick slices in a roll with mustard. A butcher-counter classic.", "kw": ["leberkäse", "leberkas"]}, {"id": "muenchen-steckerlfisch", "name": "Steckerlfisch", "local": "", "icon": "🐟", "desc": "Whole mackerel or trout grilled over charcoal on a stick. Beer-garden food that Munich popularised.", "kw": ["steckerlfisch"]}],
  muenster: [{"id": "muenster-moeppkenbrot", "name": "Möppkenbrot", "local": "", "icon": "🥓", "desc": "Buckwheat blood loaf sliced and fried until crisp, served with apple sauce or bread. A Münsterland winter dish.", "kw": ["möppkenbrot", "moeppkenbrot"]}, {"id": "muenster-stielmus", "name": "Stielmus with Mettwurst", "local": "", "icon": "🥬", "desc": "Stewed turnip greens with potatoes and smoked Mettwurst, a seasonal Münsterland farm dish.", "kw": ["stielmus"]}, {"id": "muenster-pannekoken", "name": "Pannekoken", "local": "", "icon": "🥞", "desc": "Thick pancake served with bacon or apple, a Dutch-influenced Münsterland dish.", "kw": ["pannekoken", "pfannkuchen"]}, {"id": "muenster-hochzeitssuppe", "name": "Münsterland wedding soup", "local": "Münsterländer Hochzeitssuppe", "icon": "🍲", "desc": "Clear beef soup with meatballs, vegetables and egg custard, traditionally served at farm weddings in the Münsterland.", "kw": ["hochzeitssuppe"]}],
  mugla: [{"id": "mugla-cokertme", "name": "Çökertme kebabı", "local": "", "icon": "🥩", "desc": "Thin strips of veal on a bed of fried potato matchsticks and yogurt, finished with butter. A signature of the Bodrum area.", "kw": ["çökertme", "cokertme"]}, {"id": "mugla-bodrum-mantisi", "name": "Bodrum mantısı", "local": "", "icon": "🥟", "desc": "Tiny dumplings steamed or baked, served with garlic yogurt and tomato butter. The best-known home dish of Bodrum.", "kw": ["bodrum mantısı", "mantı"]}, {"id": "mugla-sundurme", "name": "Sündürme", "local": "", "icon": "🥙", "desc": "Stretched, thin dough cooked on a griddle and filled with meat or cheese, then rolled. A traditional Muğla village dish.", "kw": ["sündürme", "sundurme"]}, {"id": "mugla-mugla-koftesi", "name": "Muğla köftesi", "local": "", "icon": "🧆", "desc": "Grilled meatballs with a geographical indication, seasoned simply and served with bread and salad. Milas and Muğla town are the home of this style.", "kw": ["muğla köftesi", "milas köftesi"]}, {"id": "mugla-ciris-otu", "name": "Çiriş otu yemeği", "local": "", "icon": "🌿", "desc": "A wild herb of the Fethiye hills cooked with olive oil and onion, or in an egg dish. Typical of the Aegean herb tradition of the Muğla coast.", "kw": ["çiriş otu", "ciris"]}],
  namur: [{"id": "namur-petits-gris", "name": "Petits-gris de Namur", "local": "Escargots de Namur", "icon": "🐌", "desc": "Small grey garden snails cooked in the Namur way with herbs and butter. The snail is the city's emblem.", "kw": ["petit-gris", "petits-gris", "snail", "escargot"]}, {"id": "namur-bietrume", "name": "Biétrumé", "local": "", "icon": "🍫", "desc": "Butter caramel and chocolate sweet created in Namur in 1956.", "kw": ["biétrumé", "bietrume"]}, {"id": "namur-baisers-namur", "name": "Baisers de Namur", "local": "", "icon": "🍬", "desc": "Soft sweet kisses sold at chocolatiers in Namur and La Roche.", "kw": ["baiser", "baisers"]}, {"id": "namur-jambon-ardennes", "name": "Ardennes ham", "local": "Jambon d'Ardenne", "icon": "🥓", "desc": "Dry-cured, lightly smoked ham from the Ardennes, a protected regional product.", "kw": ["ardennes ham", "jambon", "ham"]}, {"id": "namur-gibier", "name": "Ardennes game", "local": "Gibier", "icon": "🥩", "desc": "Venison and wild boar stewed in autumn in Ardennes inns and restaurants.", "kw": ["game", "gibier", "wild boar", "sanglier"]}],
  nancy: [{"id": "nancy-bergamote", "name": "Bergamotes de Nancy", "local": "", "icon": "🍬", "desc": "Amber hard candies flavoured with bergamot oil, individually hand-wrapped. They hold a PGI, and only a handful of makers, several in Nancy, may produce them.", "kw": ["bergamote", "bergamotes"]}, {"id": "nancy-macarons-soeurs", "name": "Macarons de Nancy", "local": "", "icon": "🍪", "desc": "Almond-heavy macarons with a crisp top and soft centre, unlike the filled Parisian kind. The recipe goes back to nuns in Nancy at the time of the French Revolution.", "kw": ["macaron", "macarons de nancy"]}, {"id": "nancy-baba", "name": "Baba au rhum", "local": "", "icon": "🍰", "desc": "Soft yeast cake soaked in rum syrup, born in the court of Duke Stanislas, who first used Hungarian tokaji wine. One of three Lorraine specialities from the Enlightenment era.", "kw": ["baba au rhum", "baba"]}, {"id": "nancy-pate-lorrain", "name": "Pâté lorrain", "local": "", "icon": "🥧", "desc": "Marinated pork and veal, soaked in white wine and herbs, baked in a golden puff-pastry case. Best eaten warm; found in Nancy's bakeries and delis.", "kw": ["pâté lorrain", "pate lorrain"]}, {"id": "nancy-bilberry-tart", "name": "Bilberry tart", "local": "Tarte aux myrtilles", "icon": "🫐", "desc": "Tart of wild bilberries picked in the Vosges mountains, one of the Vosges' regional pastries. The berries also go into jam and sweets.", "kw": ["myrtille", "bilberry"]}],
  nantes: [{"id": "nantes-sandre-beurre-blanc", "name": "Sandre au beurre blanc", "local": "", "icon": "🐟", "desc": "Loire pikeperch with beurre blanc, a sauce of shallots, white wine and butter. The sauce was born in the Nantes area and still goes on every Loire fish.", "kw": ["beurre blanc", "sandre"]}, {"id": "nantes-gateau-nantais", "name": "Gâteau nantais", "local": "", "icon": "🍰", "desc": "Almond cake made with salted butter and rum, brushed with a rum glaze. A travel cake from the port of Nantes, sold in bakeries.", "kw": ["gâteau nantais", "gateau nantais"]}, {"id": "nantes-petit-beurre", "name": "Petit-beurre LU", "local": "", "icon": "🍪", "desc": "The square butter biscuit with 52 teeth, created in Nantes by the LU biscuit makers in 1886. Still the city's best-known sweet souvenir.", "kw": ["petit-beurre", "petit beurre", "lu "]}, {"id": "nantes-berlingot-nantais", "name": "Berlingot nantais", "local": "", "icon": "🍬", "desc": "Pillow-shaped boiled sweet from Nantes, flavoured with mint, lemon or orange and filled with a core of liquid fruit.", "kw": ["berlingot"]}, {"id": "nantes-cure-nantais", "name": "Curé nantais", "local": "", "icon": "🧀", "desc": "Soft washed-rind cow's-milk cheese from the Nantes area with a strong smell and mild, buttery taste. Sold in orange squares at markets and cheese shops.", "kw": ["curé nantais", "cure nantais"]}, {"id": "nantes-mogettes-vendee", "name": "Mogettes de Vendée", "local": "", "icon": "🫘", "desc": "Slow-cooked white beans of the Vendée, eaten with a thick slice of ham or with butter and bread. A farm-table classic of the inland Vendée.", "kw": ["mogettes", "mogette"]}],
  nice: [{"id": "nice-socca", "name": "Socca", "local": "", "icon": "🥞", "desc": "A thin chickpea flour pancake cooked in a wood oven and eaten hot with black pepper. Nice's classic street food.", "kw": ["socca"]}, {"id": "nice-pissaladiere", "name": "Pissaladière", "local": "", "icon": "🧅", "desc": "Bread dough topped with slow-cooked onions, anchovies and black olives, but no cheese or tomato. Found in every Nice bakery.", "kw": ["pissaladière", "pissaladiere"]}, {"id": "nice-pan-bagnat", "name": "Pan bagnat", "local": "", "icon": "🥖", "desc": "A round roll filled with tuna, tomatoes, eggs, olives and olive oil. The Niçois beach lunch.", "kw": ["pan bagnat"]}, {"id": "nice-salade-nicoise", "name": "Salade niçoise", "local": "", "icon": "🥗", "desc": "A salad of tomato, tuna, anchovy, olives, egg and raw vegetables, dressed with olive oil, from Nice.", "kw": ["salade niçoise", "niçoise"]}, {"id": "nice-tourte-blettes", "name": "Tourte de blettes", "local": "", "icon": "🥧", "desc": "A sweet or savoury tart filled with Swiss chard, pine nuts and raisins. A traditional dessert of Nice bakeries and markets.", "kw": ["tourte de blettes", "blettes"]}, {"id": "nice-petits-farcis", "name": "Petits farcis niçois", "local": "Petits farcis", "icon": "🍅", "desc": "Courgettes, tomatoes, peppers and onions stuffed with minced meat and baked. A Niçois home dish found in traditional restaurants.", "kw": ["petits farcis", "farcis"]}],
  nimes: [{"id": "nimes-brandade", "name": "Brandade de Nîmes", "local": "Brandade de morue de Nîmes", "icon": "🐟", "desc": "Salt cod poached and worked with olive oil, milk and garlic into a smooth purée. Recipes in Nîmes date back to 1786, and it is the city's best-known dish.", "kw": ["brandade"]}, {"id": "nimes-gardiane", "name": "Gardiane de taureau", "local": "Gardiane de taureau", "icon": "🥩", "desc": "Camargue bull meat marinated in red wine and slowly stewed with vegetables and condiments, usually served with rice. Eaten in Nîmes and the Camargue, especially in winter.", "kw": ["gardiane", "taureau"]}, {"id": "nimes-petit-pate-nimois", "name": "Petit pâté nîmois", "local": "Petit pâté nîmois", "icon": "🥧", "desc": "A small pastry created in 1800, filled with minced veal and pork, some versions with brandade. A common lunchtime snack at the covered market.", "kw": ["petit pâté nîmois", "pâté nîmois"]}, {"id": "nimes-croquants-villaret", "name": "Croquants Villaret", "local": "Croquants Villaret", "icon": "🍪", "desc": "Crunchy dry almond biscuits made in Nîmes by one family firm since 1775, flavoured with honey, orange blossom and lemon.", "kw": ["croquants", "villaret"]}, {"id": "nimes-pelardon", "name": "Pélardon", "local": "Pélardon", "icon": "🧀", "desc": "A small AOC goat's cheese from the Cévennes, eaten with bread or with honey and dried fruit. The Gard's best-known cheese.", "kw": ["pélardon"]}],
  nuernberg: [{"id": "nuernberg-bratwurst", "name": "Nürnberger Rostbratwurst", "local": "", "icon": "🌭", "desc": "Thumb-sized pork sausage with a protected origin, grilled over beechwood and served in threes, sixes or twelves.", "kw": ["nürnberger bratwurst", "rostbratwurst", "bratwurst"]}, {"id": "nuernberg-lebkuchen", "name": "Nürnberger Lebkuchen", "local": "", "icon": "🍪", "desc": "Soft spiced gingerbread baked on a wafer, made in Nürnberg since the 14th century with a protected origin.", "kw": ["lebkuchen"]}, {"id": "nuernberg-karpfen", "name": "Franconian carp", "local": "Fränkischer Karpfen", "icon": "🐟", "desc": "Carp from the ponds of the Aischgrund, served baked or fried in autumn and winter. A mainstay of Middle Franconian inns.", "kw": ["karpfen", "carp"]}, {"id": "nuernberg-sauerbraten", "name": "Franconian Sauerbraten", "local": "Fränkischer Sauerbraten", "icon": "🍖", "desc": "Beef marinated for days in vinegar and spices, often with a sauce thickened with Lebkuchen. Served with dumplings.", "kw": ["sauerbraten"]}, {"id": "nuernberg-blaue-zipfel", "name": "Blaue Zipfel", "local": "", "icon": "🌭", "desc": "Bratwürste simmered in a spiced vinegar and onion broth. A Nürnberg pub classic.", "kw": ["blaue zipfel", "zipfel"]}],
  odense: [{"id": "odense-tarteletter", "name": "Tarteletter", "local": "", "icon": "🥧", "desc": "Puff pastry shells filled with chicken and asparagus in white sauce. A Danish classic that is easy to find on Funen.", "kw": ["tarteletter"]}, {"id": "odense-marcipan", "name": "Odense marzipan", "local": "Odense marcipan", "icon": "🍬", "desc": "Marzipan figures, bars and sweets made in the city, which has a long tradition of confectionery.", "kw": ["marcipan", "marzipan"]}, {"id": "odense-aeble", "name": "Funen apple cake", "local": "Fynsk æblekage", "icon": "🍏", "desc": "Funen is the orchard island of Denmark, and apple cakes and desserts feature on cafe menus across the island.", "kw": ["æble", "apple"]}, {"id": "odense-risalamande", "name": "Risalamande", "local": "", "icon": "🍚", "desc": "Cold rice pudding with whipped cream, almonds and hot cherry sauce. Danish Christmas dessert that appears on winter menus.", "kw": ["risalamande"]}, {"id": "odense-flaeskestegsandwich", "name": "Fynsk rullepølse", "local": "Rullepølse", "icon": "🥓", "desc": "Spiced pressed pork roll sliced thin over rye bread, a regular on the Danish cold lunch table.", "kw": ["rullepølse"]}],
  oldenburg: [{"id": "oldenburg-gruenkohl", "name": "Grünkohl mit Pinkel", "local": "", "icon": "🥬", "desc": "Winter kale stewed with smoked Pinkel sausage and bacon, with potatoes. The signature dish of Oldenburg and its Kohlfahrt tradition.", "kw": ["grünkohl", "pinkel"]}, {"id": "oldenburg-friesentorte", "name": "Friesentorte", "local": "", "icon": "🍰", "desc": "Layered puff-pastry cake with cream and plum jam, a classic of East Frisia and Oldenburg cafés.", "kw": ["friesentorte"]}, {"id": "oldenburg-krabben", "name": "North Sea shrimp", "local": "Nordseekrabben", "icon": "🦐", "desc": "Small brown shrimp caught off the East Frisian coast and eaten on bread or in a bowl, fresh from the harbour.", "kw": ["krabben", "shrimp"]}, {"id": "oldenburg-rosinenstuten", "name": "Ostfriesischer Rosinenstuten", "local": "", "icon": "🍞", "desc": "Sweet, soft raisin loaf, served with tea in East Frisian homes and bakeries.", "kw": ["rosinenstuten", "stuten"]}, {"id": "oldenburg-entenbraten", "name": "Oldenburger Entenbraten", "local": "", "icon": "🦆", "desc": "Roast duck with red cabbage and dumplings, a famous Oldenburg dinner dish with duck farming ties.", "kw": ["entenbraten", "duck"]}],
  orleans: [{"id": "orleans-pithiviers", "name": "Pithiviers", "local": "", "icon": "🥧", "desc": "An almond cake from the Loiret town of Pithiviers, sold glazed or as a puff pastry version close to a galette des rois. One of the emblems of the Loiret.", "kw": ["pithiviers"]}, {"id": "orleans-andouille-de-jargeau", "name": "Andouille de Jargeau", "local": "", "icon": "🌭", "desc": "A chitterling sausage of pork tripe and minced meat in natural casing, traditionally served with mashed potatoes. Made in Jargeau on the Loire for centuries.", "kw": ["andouille", "jargeau"]}, {"id": "orleans-cendre-d-olivet", "name": "Cendré d'Olivet", "local": "Olivet cendré", "icon": "🧀", "desc": "A cow's milk cheese like a camembert, coated in ash that once kept flies off. A Loiret farm cheese, now made at Châteauneuf-sur-Loire.", "kw": ["olivet", "cendré"]}, {"id": "orleans-pralines-de-montargis", "name": "Montargis pralines", "local": "Praslines de Montargis", "icon": "🌰", "desc": "Caramelised, grilled almonds made from an old local recipe. A confectioner in Montargis has been making them since 1903.", "kw": ["praline", "montargis"]}, {"id": "orleans-cotignac", "name": "Cotignac d'Orléans", "local": "Cotignac", "icon": "🍯", "desc": "A thick, creamy quince jelly made around Orléans since the late Middle Ages. It is sold in a small spruce box whose lid doubles as a spoon.", "kw": ["cotignac", "quince"]}],
  osnabrueck: [{"id": "osnabrueck-pickert", "name": "Pickert", "local": "", "icon": "🥞", "desc": "Thick yeast-and-potato pancake, fried and eaten with butter, jam or sausage. A farmhouse bread from Westphalia that is common around Osnabrück.", "kw": ["pickert"]}, {"id": "osnabrueck-pannekauken", "name": "Emsland buckwheat pancake", "local": "Buchweizen-Pannekauken", "icon": "🥞", "desc": "Thin pancake of buckwheat flour with bacon, fried in a pan. Buckwheat grew on the sandy Emsland soils and the pancake stayed on local menus.", "kw": ["pannekauken", "buckwheat pancake"]}, {"id": "osnabrueck-duemmer-aal", "name": "Smoked Dümmer eel", "local": "Dümmer Räucheraal", "icon": "🐟", "desc": "Eel from Lake Dümmer on the edge of Vechta and Osnabrück land, smoked and eaten on dark bread. Sold from local smokehouses.", "kw": ["räucheraal", "smoked eel"]}, {"id": "osnabrueck-bentheimer-schwein", "name": "Bentheimer Landschwein roast", "local": "", "icon": "🐖", "desc": "Pork from the rare Bentheimer Landschwein breed, raised in the Grafschaft Bentheim and served on regional menus as roast or sausage.", "kw": ["bentheimer"]}],
  paris: [{"id": "paris-onion-soup", "name": "French onion soup", "local": "Soupe à l'oignon", "icon": "🍲", "desc": "Onions simmered in beef stock, topped with bread and gratinéed Gruyère. A Les Halles market dish, served in brasseries today.", "kw": ["onion soup", "soupe à l'oignon"]}, {"id": "paris-jambon-beurre", "name": "Jambon-beurre", "local": "", "icon": "🥖", "desc": "A baguette with butter and ham, Paris's everyday sandwich. Sold in every bakery and café.", "kw": ["jambon-beurre", "jambon beurre"]}, {"id": "paris-croque-monsieur", "name": "Croque-monsieur", "local": "", "icon": "🥪", "desc": "A toasted ham and cheese sandwich with béchamel, topped with a fried egg as a croque-madame. A Paris café classic since 1910.", "kw": ["croque-monsieur", "croque monsieur"]}, {"id": "paris-steak-frites", "name": "Steak-frites", "local": "", "icon": "🥩", "desc": "Pan-seared steak with chips and sometimes a pepper or Béarnaise sauce. The standard dish of a Paris brasserie.", "kw": ["steak frites", "steak-frites"]}, {"id": "paris-macaron", "name": "Parisian macaron", "local": "Macaron parisien", "icon": "🍬", "desc": "Two almond meringue shells around a ganache or jam. The Paris version is made in dozens of patisseries.", "kw": ["macaron"]}, {"id": "paris-eclair", "name": "Éclair", "local": "", "icon": "🍫", "desc": "A choux pastry filled with cream, topped with fondant icing. One of Paris's most-loved patisserie items.", "kw": ["éclair", "eclair"]}, {"id": "paris-croissant", "name": "Croissant", "local": "", "icon": "🥐", "desc": "A flaky, buttery crescent eaten for breakfast. Paris bakeries compete for the best butter version.", "kw": ["croissant"]}],
  passau: [{"id": "passau-erdaepfelkas", "name": "Erdäpfelkas", "local": "", "icon": "🥔", "desc": "Spread of mashed potatoes, sour cream, onion and chives, eaten with bread and smoked meat. Typical in the Bavarian Forest.", "kw": ["erdäpfelkas", "kartoffelkäse"]}, {"id": "passau-reiberdatschi", "name": "Reiberdatschi", "local": "", "icon": "🥞", "desc": "Crisp potato pancake fried in fat, eaten with apple sauce or smoked fish. A Lower Bavarian farm dish.", "kw": ["reiberdatschi", "potato pancake"]}, {"id": "passau-schwammerl", "name": "Schwammerl with dumplings", "local": "Schwammerl mit Semmelknödel", "icon": "🍄", "desc": "Forest mushrooms in cream sauce, served with bread dumplings. Bavarian Forest autumn dish.", "kw": ["schwammerl", "mushroom"]}, {"id": "passau-schweinsbraten", "name": "Schweinsbraten with Knödel", "local": "", "icon": "🍖", "desc": "Roast pork with crackling, dark beer gravy and potato dumplings. A staple of Niederbayern inns.", "kw": ["schweinsbraten", "knödel"]}],
  perigueux: [{"id": "perigueux-pate-perigueux", "name": "Pâté de Périgueux", "local": "", "icon": "🥧", "desc": "Pastry pie filled with meat, foie gras and truffle, whose origins are traced to Périgueux pastry cooks of past centuries. Found in local delicatessens and restaurants.", "kw": ["pâté de périgueux", "pâté périgourdin"]}, {"id": "perigueux-tourin", "name": "Tourin", "local": "Tourin périgourdin", "icon": "🥣", "desc": "Garlic and onion soup cooked in duck fat, often thickened with egg and served with bread. A humble Périgord farm soup, still on menus in Dordogne.", "kw": ["tourin"]}, {"id": "perigueux-confit-canard", "name": "Duck confit", "local": "Confit de canard", "icon": "🦆", "desc": "Duck leg slowly cooked and preserved in its own fat, then crisped. Served in Périgord with sarladaise potatoes or cep mushrooms.", "kw": ["confit de canard", "duck confit"]}, {"id": "perigueux-foie-gras", "name": "Périgord foie gras", "local": "Foie gras du Périgord", "icon": "🍽️", "desc": "Duck or goose liver served as terrine or lightly seared, a mainstay of Dordogne cooking. Eaten with toast and fig jam in local restaurants and markets.", "kw": ["foie gras"]}, {"id": "perigueux-sarladaise", "name": "Sarladaise potatoes", "local": "Pommes de terre sarladaises", "icon": "🥔", "desc": "Sliced potatoes fried in duck fat with garlic and parsley, often with truffle or ceps. The standard side for confit and magret in Périgord.", "kw": ["sarladaise"]}, {"id": "perigueux-gateau-noix", "name": "Walnut cake", "local": "Gâteau aux noix du Périgord", "icon": "🍰", "desc": "Dense cake made with protected Périgord walnuts, found in bakeries along with walnut tarts and nut-based sweets. Dordogne is a leading French walnut region.", "kw": ["noix", "walnut"]}],
  perpignan: [{"id": "perpignan-boles-picolat", "name": "Boles de picolat", "local": "Boles de picolat", "icon": "🍲", "desc": "Catalan meatballs of minced beef and pork with bacon, garlic, parsley and bread soaked in milk, simmered in tomato sauce, often with white beans. A classic of Roussillon home cooking.", "kw": ["boles de picolat", "picolat"]}, {"id": "perpignan-rousquilles", "name": "Rousquilles", "local": "Rosquilles", "icon": "🍩", "desc": "Ring-shaped Catalan biscuits coated in a thin, sweet, lightly aniseed white glaze. A symbol of Perpignan pastry, found in bakeries all over French Catalonia.", "kw": ["rousquilles", "rosquilles"]}, {"id": "perpignan-creme-catalane", "name": "Crème catalane", "local": "Crema catalana", "icon": "🍮", "desc": "A custard flavoured with cinnamon and lemon zest under a hard caramelised sugar crust, like a crème brûlée. The standard Catalan dessert on Perpignan menus.", "kw": ["crème catalane", "crema catalana"]}, {"id": "perpignan-bunyetes", "name": "Bunyetes", "local": "Bunyetes", "icon": "🥞", "desc": "Very thin, crisp, round fritters scented with orange blossom and citrus, made on the Roussillon plain and in the Vallespir and Conflent. Traditionally an Easter treat.", "kw": ["bunyetes", "beignets"]}, {"id": "perpignan-anchois", "name": "Collioure anchovies", "local": "Anchois de Collioure", "icon": "🐟", "desc": "Anchovies fished at night from boats with a lamp, then salted for months. Collioure on the Côte Vermeille is known for them, eaten on bread or with escalivada.", "kw": ["anchois", "anchovies"]}],
  poitiers: [{"id": "poitiers-farci-poitevin", "name": "Farci poitevin", "local": "", "icon": "🥬", "desc": "A slow-cooked pâté of greens and herbs such as sorrel, cabbage, chard and leeks, sometimes with bacon. Called a typical dish of Poitou, eaten cold or hot.", "kw": ["farci poitevin", "farci"]}, {"id": "poitiers-chabichou-du-poitou", "name": "Chabichou du Poitou", "local": "", "icon": "🧀", "desc": "A whole-milk goat cheese with a distinctive truncated shape and a soft, creamy taste. Named the star cheese of the Vienne, with protected status.", "kw": ["chabichou"]}, {"id": "poitiers-tourteau-fromager", "name": "Tourteau fromager", "local": "", "icon": "🍰", "desc": "A barely sweet goat-cheese cake with a dark, burnt crust. A Poitou tradition eaten as dessert, snack or with an aperitif.", "kw": ["tourteau fromager", "tourteau"]}, {"id": "poitiers-broye-du-poitou", "name": "Broyé du Poitou", "local": "", "icon": "🍪", "desc": "A hard, crumbly butter shortbread. Tradition says you break it by pressing the centre with your fist, and it is served at celebrations.", "kw": ["broyé", "broye"]}, {"id": "poitiers-macaron-de-montmorillon", "name": "Montmorillon macaron", "local": "Macaron de Montmorillon", "icon": "🍪", "desc": "Almond macarons from Montmorillon in the Vienne, made with egg whites and sugar. The town has been known for them for over two centuries.", "kw": ["macaron", "montmorillon"]}],
  potsdam: [{"id": "potsdam-havel-zander", "name": "Havel pike-perch", "local": "Havelzander", "icon": "🐟", "desc": "Pan-fried zander from the Havel lakes, with potatoes or in a herb sauce. The freshwater fish of the Potsdam lake district.", "kw": ["zander", "pike-perch", "havel"]}, {"id": "potsdam-teltower-ruebchen", "name": "Teltower turnips", "local": "Teltower Rübchen", "icon": "🥕", "desc": "Small sweet turnips from the Teltow area just outside Potsdam, usually glazed in butter. A protected regional vegetable.", "kw": ["teltower rübchen", "rübchen"]}, {"id": "potsdam-beelitzer-spargel", "name": "Beelitz asparagus", "local": "Beelitzer Spargel", "icon": "🌱", "desc": "White asparagus from the sandy soils of Beelitz, eaten in spring with potatoes, ham and butter.", "kw": ["beelitzer", "spargel", "asparagus"]}, {"id": "potsdam-leinoel-quark", "name": "Potatoes with linseed oil", "local": "Pellkartoffeln mit Leinöl und Quark", "icon": "🥔", "desc": "Boiled jacket potatoes with fresh quark and cold-pressed linseed oil. A simple Brandenburg country classic.", "kw": ["leinöl", "quark"]}, {"id": "potsdam-suelze", "name": "Sülze with fried potatoes", "local": "Sülze mit Bratkartoffeln", "icon": "🍽️", "desc": "Jellied pork brawn with pickles and onions, served with crispy fried potatoes. Hearty traditional Brandenburg pub food.", "kw": ["sülze", "bratkartoffeln"]}],
  regensburg: [{"id": "regensburg-wurst", "name": "Regensburger Wurst", "local": "", "icon": "🌭", "desc": "Coarse smoked pork sausage, short and thick, eaten hot with mustard or in a roll. Regensburg's own recipe.", "kw": ["regensburger wurst", "regensburger"]}, {"id": "regensburg-karpfen", "name": "Upper Palatinate carp", "local": "Oberpfälzer Karpfen", "icon": "🐟", "desc": "Carp from the pond country of the Upper Palatinate, served baked or fried in autumn and winter.", "kw": ["karpfen", "carp"]}, {"id": "regensburg-dampfnudel", "name": "Dampfnudel", "local": "", "icon": "🥟", "desc": "Yeast dumpling steamed in a covered pan so it gets a salty, caramelised crust underneath, served with vanilla sauce. A classic of Upper Palatinate and Lower Bavarian kitchens.", "kw": ["dampfnudel"]}, {"id": "regensburg-bauernseufzer", "name": "Oberpfälzer Bauernseufzer", "local": "", "icon": "🌭", "desc": "Air-dried, smoked salami-style sausage from the Upper Palatinate, eaten as a snack with bread.", "kw": ["bauernseufzer"]}],
  reims: [{"id": "reims-biscuit-rose", "name": "Biscuit rose de Reims", "local": "Biscuit rose", "icon": "🍪", "desc": "A pink, vanilla-flavoured biscuit made in Reims since 1691. Crisp and light, designed for dunking.", "kw": ["biscuit rose", "biscuits roses"]}, {"id": "reims-massepain", "name": "Massepain de Reims", "local": "", "icon": "🍬", "desc": "Soft almond marzipan biscuits made in Reims since the Middle Ages. Often packed in boxes for gifts.", "kw": ["massepain"]}, {"id": "reims-pain-epices", "name": "Reims gingerbread", "local": "Pain d'épices de Reims", "icon": "🍞", "desc": "A dense honey and spice bread, a Reims confectioner's speciality for centuries. Sold in slices or as small cakes.", "kw": ["pain d'épices", "gingerbread"]}, {"id": "reims-jambon", "name": "Jambon de Reims", "local": "", "icon": "🍖", "desc": "Pressed ham set in aspic with parsley, served cold in slices. A Reims charcuterie classic.", "kw": ["jambon de reims"]}, {"id": "reims-moutarde", "name": "Moutarde de Reims", "local": "", "icon": "🥄", "desc": "A coarse-ground wholegrain mustard made in Reims since the Middle Ages. Used with ham and sold in local épiceries.", "kw": ["moutarde de reims", "mustard"]}],
  rennes: [{"id": "rennes-galette-saucisse", "name": "Galette-saucisse", "local": "", "icon": "🌭", "desc": "A grilled pork sausage rolled in a hot buckwheat galette, the street food of Rennes, sold at the Lices market and outside the football stadium.", "kw": ["galette-saucisse", "galette saucisse"]}, {"id": "rennes-galette-complete", "name": "Galette complète", "local": "", "icon": "🥞", "desc": "Savoury buckwheat galette with ham, egg and Emmental, served with cider. Saint-Malo and Rennes are old crêperie towns where buckwheat is a daily food.", "kw": ["galette complète", "galette", "crêpe"]}, {"id": "rennes-craquelins-saint-malo", "name": "Craquelins de Saint-Malo", "local": "", "icon": "🍘", "desc": "Thin, crisp, lightly sweet biscuits made in Saint-Malo since the 19th century, once sold in the walled town's shops. Eaten with butter, jam or cheese.", "kw": ["craquelin", "craquelins"]}, {"id": "rennes-coquille-saint-brieuc", "name": "Saint-Brieuc scallops", "local": "Coquilles Saint-Jacques de la baie de Saint-Brieuc", "icon": "🐚", "desc": "Scallops dredged in the Bay of Saint-Brieuc from October to April under a protected label. Eaten seared, in a galette or with leeks and cream.", "kw": ["coquille saint-jacques", "scallop"]}, {"id": "rennes-moules-bouchot", "name": "Bouchot mussels", "local": "Moules de bouchot de la baie du Mont-Saint-Michel", "icon": "🦪", "desc": "Small, sweet mussels grown on wooden poles in the bay around Cancale and Vivier-sur-Mer, protected by an AOP. Steamed with cream or cider.", "kw": ["moules", "mussels", "bouchot"]}],
  ribe: [{"id": "ribe-aal", "name": "Ribe eel", "local": "Ribe ål", "icon": "🐟", "desc": "Smoked or fried eel from the Wadden Sea marshes around Ribe, found on traditional menus in the old town.", "kw": ["ål", "eel"]}, {"id": "ribe-oyster", "name": "Wadden Sea oyster", "local": "Vadehavsøsters", "icon": "🦪", "desc": "Oysters from the Wadden Sea around Rømø and Fanø, served in coast and Ribe restaurants.", "kw": ["østers", "oyster"]}, {"id": "ribe-sonderjysk", "name": "Sønderjysk kaffebord", "local": "", "icon": "🥧", "desc": "South Jutland coffee table with several small cakes and sweet bread, served at traditional cafes.", "kw": ["kaffebord", "sønderjysk"]}, {"id": "ribe-rejer", "name": "North Sea prawns", "local": "Rejer", "icon": "🦐", "desc": "Cold-water prawns on rye bread, common in South Jutland seaside restaurants.", "kw": ["rejer", "prawn"]}, {"id": "ribe-fisk", "name": "Plaice with remoulade", "local": "Rødspætte med remoulade", "icon": "🐟", "desc": "Breaded plaice fried and served with remoulade and lemon, a coastal fish lunch around Esbjerg and Ribe.", "kw": ["rødspætte", "plaice"]}],
  rize: [{"id": "rize-muhlama", "name": "Muhlama", "local": "Muhlama", "icon": "🧈", "desc": "A warm breakfast dish of kolot cheese, butter and cornmeal, eaten with cornbread. Rize's signature dish and one of its most consumed.", "kw": ["muhlama", "mıhlama"]}, {"id": "rize-laz-boregi", "name": "Laz boregi", "local": "Hopa Laz böreği", "icon": "🍮", "desc": "Layers of thin pastry around a vanilla custard, finished with syrup and in Hopa a touch of black pepper. Hopa, in Artvin, holds the geographical indication.", "kw": ["laz böreği", "laz boregi"]}, {"id": "rize-karalahana-sarmasi", "name": "Black cabbage sarma", "local": "Karalahana sarması", "icon": "🥬", "desc": "Black cabbage leaves wrapped around rice, onion and dill, sometimes with ground meat. A signature Rize dish eaten in colder months.", "kw": ["karalahana sarması", "karalahana"]}, {"id": "rize-pucuko", "name": "Pucuko", "local": "Puçuko", "icon": "🫘", "desc": "Sun-dried green beans cooked with tomato paste and bulgur, with lemon or vinegar if you like. A registered speciality of Artvin.", "kw": ["puçuko"]}, {"id": "rize-silor", "name": "Silor", "local": "Silor", "icon": "🥛", "desc": "Thin egg-and-milk dough, rolled, cut and baked, then softened and served with yogurt and melted butter. A pastry-like dish from Artvin.", "kw": ["silor"]}],
  rodez: [{"id": "rodez-aligot", "name": "Aligot", "local": "", "icon": "🧀", "desc": "Mashed potato whipped with fresh Laguiole tomme, butter and garlic until it stretches in ribbons. The best-known Aveyron dish, served on the Aubrac plateau and in Rodez.", "kw": ["aligot"]}, {"id": "rodez-farcous", "name": "Farçous", "local": "", "icon": "🥞", "desc": "Fried savoury fritters of chard, herbs and sometimes pork, a traditional Aveyron farm dish. Sold in bakeries and markets around Rodez.", "kw": ["farçous", "farcous"]}, {"id": "rodez-tripoux", "name": "Tripoux", "local": "", "icon": "🍲", "desc": "Small parcels of sheep tripe and feet, stuffed and simmered in white wine and tomato. A rustic Aveyron speciality served in local restaurants.", "kw": ["tripoux"]}, {"id": "rodez-fouace", "name": "Fouace", "local": "Fouace de l'Aveyron", "icon": "🥐", "desc": "Orange-blossom brioche shaped as a crown, traditional in Aveyron bakeries. Eaten at celebrations and as an everyday pastry.", "kw": ["fouace"]}, {"id": "rodez-estofinado", "name": "Estofinado", "local": "", "icon": "🐟", "desc": "Dried cod mashed with potato, cream, garlic and walnut oil. A dish of Rodez and the Aveyron valleys, found in traditional restaurants.", "kw": ["estofinado"]}, {"id": "rodez-roquefort", "name": "Roquefort", "local": "", "icon": "🧀", "desc": "Blue ewe's-milk cheese ripened in the natural caves of Roquefort-sur-Soulzon in south Aveyron. A regional cheese found on every local cheese board.", "kw": ["roquefort"]}],
  rosenheim: [{"id": "rosenheim-chiemsee-renke", "name": "Chiemsee Renke", "local": "Chiemseerenke", "icon": "🐟", "desc": "Lake whitefish from the nearby Chiemsee, fried in butter 'Müllerin' style with lemon. The classic fish of the Chiemgau.", "kw": ["renke", "chiemsee"]}, {"id": "rosenheim-biersuppe", "name": "Bavarian beer soup", "local": "Boarische Biersuppe", "icon": "🍲", "desc": "Beer-based soup thickened with cream and egg yolk, served with cheese-topped bread slices. An old Upper Bavarian recipe.", "kw": ["biersuppe"]}, {"id": "rosenheim-kaiserschmarrn", "name": "Kaiserschmarrn", "local": "", "icon": "🥞", "desc": "Fluffy torn pancake with raisins and powdered sugar, served with plum compote. A fixture on alpine-style menus in the Chiemgau.", "kw": ["kaiserschmarrn"]}, {"id": "rosenheim-auszogne", "name": "Auszogne", "local": "", "icon": "🍩", "desc": "Fried yeast pastry with a thin centre and thick rim, dusted with sugar. An Upper Bavarian fair and bakery treat.", "kw": ["auszogne", "schmalznudel"]}, {"id": "rosenheim-butternudeln", "name": "Butternudel", "local": "", "icon": "🍝", "desc": "Handmade Chiemgau noodles tossed in browned butter, a nearly forgotten mountain-inn speciality.", "kw": ["butternudel"]}],
  rostock: [{"id": "rostock-bueckling", "name": "Warnemünde Bückling", "local": "", "icon": "🐟", "desc": "Whole smoked herring, eaten warm at the fish stands on the Alter Strom harbour in Warnemünde.", "kw": ["bückling", "smoked herring"]}, {"id": "rostock-fischsuppe", "name": "Rostocker Fischsuppe", "local": "", "icon": "🍲", "desc": "Clear Baltic fish soup with vegetables and dill, served in harbour restaurants.", "kw": ["fischsuppe", "fish soup"]}, {"id": "rostock-brathering", "name": "Fried herring", "local": "Brathering", "icon": "🐟", "desc": "Pan-fried herring marinated in vinegar, eaten with fried potatoes. A staple on Baltic coast menus around Rostock and Warnemünde.", "kw": ["brathering", "fried herring"]}, {"id": "rostock-rote-gruetze", "name": "Rote Grütze", "local": "", "icon": "🍓", "desc": "Red berry pudding with vanilla sauce or cream. A summer dessert that is part of Mecklenburg tradition.", "kw": ["rote grütze"]}],
  rotterdam: [{"id": "rotterdam-kapsalon", "name": "Kapsalon", "local": "", "icon": "🍟", "desc": "Fries topped with doner meat, melted cheese, salad and sauce. Invented in a Rotterdam barbershop neighbourhood and now served citywide.", "kw": ["kapsalon"]}, {"id": "rotterdam-surinaamse-roti", "name": "Surinamese roti", "local": "Roti", "icon": "🫓", "desc": "Flatbread with curried chicken and potato, a Surinamese-Hindustani dish. Rotterdam has a large Surinamese community.", "kw": ["roti", "surinamese"]}, {"id": "rotterdam-stroopwafel", "name": "Stroopwafel", "local": "", "icon": "🧇", "desc": "Thin waffles sandwiched with caramel syrup, warmed above a cup. Originated in nearby Gouda.", "kw": ["stroopwafel"]}, {"id": "rotterdam-goudse-kaas", "name": "Gouda cheese", "local": "Goudse kaas", "icon": "🧀", "desc": "Wheel cheese from the Gouda area, aged from young to mature. Found at Rotterdam's market hall.", "kw": ["gouda", "kaas"]}],
  rouen: [{"id": "rouen-canard", "name": "Rouen duck", "local": "Canard à la rouennaise", "icon": "🦆", "desc": "Duckling roasted rare and served in a sauce of Bordeaux wine, shallots and the bird's own blood. It is Rouen's signature dish and is traditionally carved and finished at the table.", "kw": ["rouen duck", "canard à la rouennaise"]}, {"id": "rouen-sucre-pomme", "name": "Sucre de pomme", "local": "", "icon": "🍎", "desc": "Orange apple-sugar sticks made from apple juice, apple purée and sugar, a Rouen confectionery speciality. Sold by local confectioners as a sweet to take home.", "kw": ["sucre de pomme", "apple sugar"]}, {"id": "rouen-douillon", "name": "Douillon d'Elbeuf", "local": "", "icon": "🥧", "desc": "A whole apple, hollowed and filled with butter and sugar, wrapped in puff pastry and baked. A Seine valley treat from Elbeuf, eaten from September through winter.", "kw": ["douillon"]}, {"id": "rouen-neufchatel", "name": "Neufchâtel", "local": "", "icon": "🧀", "desc": "Heart-shaped cow's-milk cheese with a white bloomy rind, made in Seine-Maritime around Neufchâtel-en-Bray. One of Normandy's four AOP cheeses.", "kw": ["neufchâtel", "neufchatel"]}, {"id": "rouen-marmite-dieppoise", "name": "Marmite dieppoise", "local": "", "icon": "🍲", "desc": "Creamy fish stew from Dieppe on the Channel coast: monkfish, sole or turbot with mussels and prawns, cooked in cider or white wine and finished with cream.", "kw": ["marmite dieppoise", "dieppoise"]}],
  saarbruecken: [{"id": "saarbruecken-dibbelabbes", "name": "Dibbelabbes", "local": "", "icon": "🥔", "desc": "Grated potato baked in a pot with leeks and smoked meat, served with apple sauce. The Saarland's most typical home dish.", "kw": ["dibbelabbes"]}, {"id": "saarbruecken-gefillde", "name": "Gefillde", "local": "", "icon": "🥟", "desc": "Large potato dumplings filled with minced meat or liver sausage, served with bacon sauce or sauerkraut. Saarland comfort food.", "kw": ["gefillde"]}, {"id": "saarbruecken-schwenkbraten", "name": "Schwenkbraten", "local": "", "icon": "🥩", "desc": "Marinated pork steaks grilled over beech wood on a swinging tripod grill. The Saarland's summer barbecue.", "kw": ["schwenker", "schwenkbraten"]}, {"id": "saarbruecken-lyoner", "name": "Lyoner", "local": "Saarländer Lyoner", "icon": "🌭", "desc": "Ring-shaped pork and beef sausage, eaten fried, boiled or cold. Saarlanders treat it as their own despite the French name.", "kw": ["lyoner"]}, {"id": "saarbruecken-hoorische", "name": "Hoorische", "local": "", "icon": "🥔", "desc": "Long potato dumplings boiled in water and served with bacon sauce or sauerkraut. An old Saarland dish.", "kw": ["hoorische"]}],
  safranbolu: [{"id": "safranbolu-lokum", "name": "Safranbolu saffron lokum", "local": "Safranbolu lokumu", "icon": "🍬", "desc": "Turkish delight made with cornstarch and sugar, coloured gold and lightly scented with saffron. Made here since the Ottoman period and sold in boxes in the old town.", "kw": ["safranbolu lokumu", "lokum"]}, {"id": "safranbolu-zerde", "name": "Zerde", "local": "", "icon": "🍚", "desc": "Sweet rice dessert with saffron, sugar and rice, served cold, often topped with walnuts. Descended from palace cooking and tied to the saffron that gave the town its name.", "kw": ["zerde"]}, {"id": "safranbolu-peruhi", "name": "Peruhi", "local": "", "icon": "🥟", "desc": "Hand-rolled dough squares filled with strained yogurt or keş and mint, folded into triangles, boiled and finished with butter. Sometimes called yoğurtlu mantı.", "kw": ["peruhi", "perohi"]}, {"id": "safranbolu-safranbolu-bukmesi", "name": "Safranbolu bükme", "local": "Safranbolu bükmesi", "icon": "🥧", "desc": "Savoury pastry of rolled dough with minced meat, spinach, onion and pepper, finished with butter and often served with sour cherry syrup.", "kw": ["bükme", "safranbolu bükmesi"]}, {"id": "safranbolu-cullu-borek", "name": "Çullu börek", "local": "", "icon": "🥧", "desc": "Layered pastry of yufka sheets baked on a griddle, with some cut into strips between whole sheets in a copper tray and finished with butter.", "kw": ["çullu börek", "çullu"]}],
  saintetienne: [{"id": "saintetienne-rapee", "name": "Râpée stéphanoise", "local": "Râpée", "icon": "🥔", "desc": "Crisp pan-fried galette of grated potato, egg and garlic, originally from Saint-Étienne. Often eaten with sarasson or a salad.", "kw": ["râpée", "rapée"]}, {"id": "saintetienne-sarasson", "name": "Sarasson", "local": "", "icon": "🧀", "desc": "Fresh curd cheese of the Forez mixed with cream, garlic and herbs, spread on country bread or eaten with potatoes.", "kw": ["sarasson"]}, {"id": "saintetienne-barboton", "name": "Barboton", "local": "", "icon": "🍲", "desc": "Lamb stew simmered for hours with potatoes and carrots in a cast-iron pot so the vegetables absorb the meat juices. A Stéphanois home dish.", "kw": ["barboton"]}, {"id": "saintetienne-bugnes-stephanoises", "name": "Bugnes stéphanoises", "local": "Bugnes", "icon": "🍩", "desc": "Fried yeast dough, softer and thicker than the crisp Lyon bugne. A carnival sweet of Saint-Étienne.", "kw": ["bugnes"]}, {"id": "saintetienne-fourme-de-montbrison", "name": "Fourme de Montbrison", "local": "", "icon": "🧀", "desc": "Mild blue cow's milk cheese with an orange rind, protected by AOP since 2002. Made in the Forez mountains and the emblematic cheese of the Loire.", "kw": ["fourme de montbrison", "fourme"]}],
  samsun: [{"id": "samsun-bafra-pidesi", "name": "Bafra pide", "local": "Bafra pidesi", "icon": "🥟", "desc": "A thin, closed pide stuffed with plenty of onion and minced meat seasoned with black pepper, baked until crisp. It comes from Bafra, on the Samsun coast, and is the area's signature bake.", "kw": ["bafra pide", "bafra"]}, {"id": "samsun-sinop-mantisi", "name": "Sinop manti", "local": "Sinop mantısı", "icon": "🥟", "desc": "Large pieces of thin dough, shaped like ears and filled with meat, served with yogurt and walnut. A registered Sinop product, bigger than Kayseri manti.", "kw": ["sinop mantısı", "sinop manti", "kulak"]}, {"id": "samsun-katik-boregi", "name": "Katik boregi", "local": "Katık böreği", "icon": "🥐", "desc": "Layers of thin yufka pastry filled with local cheese or minced meat. A home-style Samsun pastry found in local bakeries and lokantas.", "kw": ["katık böreği", "katik"]}, {"id": "samsun-kaz-tiridi", "name": "Kaz tiridi", "local": "Kaz tiridi", "icon": "🍗", "desc": "Goose cooked in its own broth and served over yufka and bulgur pilaf. A traditional holiday dish of the Samsun area.", "kw": ["kaz tiridi", "kaz ekmeği"]}, {"id": "samsun-findikli-burma", "name": "Hazelnut burma", "local": "Fındıklı burma tatlısı", "icon": "🌰", "desc": "A rolled pastry dessert from Ordu, the heart of Turkish hazelnut country. It is made with flour, yogurt, eggs and butter and carries a geographical indication.", "kw": ["fındıklı burma", "burma tatlısı"]}],
  sanliurfa: [{"id": "sanliurfa-urfa-kebab", "name": "Urfa kebab", "local": "Urfa kebabı", "icon": "🍢", "desc": "Hand-chopped lamb, mildly seasoned and grilled on a wide skewer, served with onion, tomato and lavash. The meat is traditionally chopped with a zırh knife and eaten without the hot spice of Antep.", "kw": ["urfa kebab", "urfa kebabı"]}, {"id": "sanliurfa-cig-kofte", "name": "Urfa çiğ köfte", "local": "", "icon": "🥬", "desc": "Bulgur kneaded with tomato paste, spices and isot pepper, wrapped in lettuce. In Urfa it is now made without raw meat and sold at stalls across the old town.", "kw": ["çiğ köfte", "cig kofte", "isot"]}, {"id": "sanliurfa-sillik", "name": "Şıllık", "local": "Şıllık tatlısı", "icon": "🍮", "desc": "Thin pastry sheets soaked in grape molasses with a layer of walnuts or pistachios and a milky syrup. A traditional Urfa sweet seldom found outside the province.", "kw": ["şıllık", "sillik"]}, {"id": "sanliurfa-lahmacun", "name": "Urfa lahmacun", "local": "Urfa lahmacunu", "icon": "🫓", "desc": "Very thin flatbread topped with minced meat, tomato and pepper, baked in a stone oven and rolled with parsley and lemon. Urfa claims it as one of its signature foods.", "kw": ["lahmacun"]}, {"id": "sanliurfa-lebeni", "name": "Lebeni soup", "local": "Lebeni çorbası", "icon": "🥣", "desc": "Yoghurt soup with chickpeas and wheat, finished with mint and chili butter. A tangy comfort dish from Urfa home kitchens and local restaurants.", "kw": ["lebeni", "lebeni çorbası"]}],
  sauerland: [{"id": "sauerland-potthucke", "name": "Potthucke", "local": "", "icon": "🥔", "desc": "Grated potato bake with onions and bacon, baked in a pot or tin, sometimes with sausage. A traditional Sauerland and Siegerland dish.", "kw": ["potthucke"]}, {"id": "sauerland-kruestchen", "name": "Sauerländer Krüstchen", "local": "", "icon": "🥩", "desc": "Breaded pork cutlet on bread with a fried egg, a hearty Sauerland pub dish.", "kw": ["krüstchen", "kruestchen"]}, {"id": "sauerland-struwen", "name": "Siegerland Struwen", "local": "Siegerländer Struwen", "icon": "🥔", "desc": "Small potato dumplings tossed in a pan with bacon and onions, a Siegerland farmhouse dish.", "kw": ["struwen"]}, {"id": "sauerland-riewekooche", "name": "Riewekooche", "local": "Siegerländer Riewekooche", "icon": "🥔", "desc": "Dense grated-potato cake baked in the oven, a Siegerland variant of the potato pancake eaten with applesauce or bread.", "kw": ["riewekooche"]}],
  schwerin: [{"id": "schwerin-rippenbraten", "name": "Mecklenburger Rippenbraten", "local": "", "icon": "🍖", "desc": "Roast pork ribs stuffed with apples, prunes and dark bread, served with red cabbage. A Sunday dish of Mecklenburg inns.", "kw": ["rippenbraten"]}, {"id": "schwerin-ente", "name": "Mecklenburg duck", "local": "Mecklenburger Ente", "icon": "🦆", "desc": "Roast duck stuffed with plums, apples and raisins, served with red cabbage and dumplings. A seasonal dish of Wismar and the lake country.", "kw": ["ente", "duck"]}, {"id": "schwerin-kloppschinken", "name": "Kloppschinken", "local": "", "icon": "🍖", "desc": "Mild-cured pork ham that is beaten to tenderise it, then boiled and sliced. A Mecklenburg cold-cut speciality.", "kw": ["kloppschinken"]}, {"id": "schwerin-schmandpudding", "name": "Schmandpudding", "local": "", "icon": "🍮", "desc": "Light pudding made from sour cream, eaten with fruit compote. A familiar Mecklenburg dessert.", "kw": ["schmandpudding", "schmand"]}],
  sivas: [{"id": "sivas-kofte", "name": "Sivas kofte", "local": "Sivas köftesi", "icon": "🍖", "desc": "Simple meatballs grilled over wood fire, served on pide with roasted pepper and tomato. A product with a geographical indication and the city's best-known dish.", "kw": ["sivas köftesi", "sivas köfte"]}, {"id": "sivas-hingel", "name": "Hingel", "local": "Hingel", "icon": "🥟", "desc": "Large pieces of filled dough, boiled and served with garlicky yogurt and butter. Sivas's own version of mantı, usually filled with potato or cheese.", "kw": ["hingel"]}, {"id": "sivas-divrigi-pilavi", "name": "Divrigi pilaf", "local": "Divriği pilavı", "icon": "🍚", "desc": "A rich pilaf with meat, rice, chickpeas and dried fruit, cooked for special occasions. It comes from Divriği, in the east of the province.", "kw": ["divriği pilavı", "alatlı pilav"]}, {"id": "sivas-madimak", "name": "Madimak", "local": "Madımak yemeği", "icon": "🌿", "desc": "A wild herb chopped and cooked with bulgur, onion and garlic, sometimes with pastirma. A spring dish tied to Sivas.", "kw": ["madımak"]}, {"id": "sivas-erzincan-tulum", "name": "Erzincan tulum cheese", "local": "Erzincan tulum peyniri", "icon": "🧀", "desc": "A crumbly cheese from sheep and goat milk of the high pastures, matured in skin bags for about three months. It carries Turkish and EU geographical indications.", "kw": ["tulum peyniri", "erzincan tulum"]}],
  stgallen: [{"id": "stgallen-bratwurst", "name": "St. Galler Bratwurst", "local": "", "icon": "🌭", "desc": "Pale veal and pork sausage with a protected geographical status, eaten without mustard. The city's butchers set its rules as early as 1438.", "kw": ["bratwurst"]}, {"id": "stgallen-buerli", "name": "St. Galler Bürli", "local": "", "icon": "🥖", "desc": "Crusty bread rolls baked in pairs that are pulled apart. The traditional partner of the St. Galler Bratwurst.", "kw": ["bürli", "buerli"]}, {"id": "stgallen-biber", "name": "St. Galler Biber", "local": "", "icon": "🍯", "desc": "Honey gingerbread filled with almond paste, pressed in carved moulds. Sold by the city's bakers as the local sweet.", "kw": ["biber"]}, {"id": "stgallen-fladen", "name": "St. Galler Fladen", "local": "", "icon": "🥧", "desc": "Flat fruit tart, the traditional pastry of the Eastern Swiss countryside around St. Gallen. Bakeries and chocolatiers sell it by the slice.", "kw": ["fladen"]}, {"id": "stgallen-sammetsuppe", "name": "Galler Sammetsuppe", "local": "", "icon": "🍲", "desc": "Smooth and velvety soup, an old St. Gallen dish. A few traditional restaurants in the old town still make it.", "kw": ["sammetsuppe"]}],
  stralsund: [{"id": "stralsund-fischbroetchen", "name": "Stralsunder Fischbrötchen", "local": "", "icon": "🥪", "desc": "Soft roll with pickled herring, onion and remoulade, sold at the harbour. Stralsund's fastest meal and the best-known fish snack on the Baltic coast.", "kw": ["fischbrötchen", "fish roll"]}, {"id": "stralsund-zander", "name": "Bodden pike-perch", "local": "Zander", "icon": "🐟", "desc": "Freshwater predator fish from the lagoons, pan-fried and served with potatoes. Standard fish dish at Rügen and Usedom inns.", "kw": ["zander", "pike-perch"]}, {"id": "stralsund-badejunge", "name": "Rügener Badejunge", "local": "", "icon": "🧀", "desc": "Soft cheese from Rügen, mild and creamy with a rind washed in a short brine. Made by an island dairy and sold in local shops.", "kw": ["badejunge"]}, {"id": "stralsund-sanddorn", "name": "Sea buckthorn cake", "local": "Sanddorntorte", "icon": "🍰", "desc": "Sponge cake with sharp orange sea buckthorn cream. The berry grows on Rügen's dunes and turns up in jam, ice cream and cakes.", "kw": ["sanddorn", "sea buckthorn"]}, {"id": "stralsund-flunder", "name": "Smoked Baltic flounder", "local": "Räucherflunder", "icon": "🐟", "desc": "Flounder smoked warm over beech wood, eaten with bread. Sold fresh from the smokehouses on Rügen and Usedom.", "kw": ["flunder", "flounder"]}],
  strasbourg: [{"id": "strasbourg-choucroute", "name": "Choucroute garnie", "local": "", "icon": "🥘", "desc": "Sauerkraut cooked with smoked pork, sausages and potatoes. Strasbourg's best-known plate, served in its winstubs.", "kw": ["choucroute"]}, {"id": "strasbourg-knack", "name": "Strasbourg knack", "local": "Knack", "icon": "🌭", "desc": "A short, pink pork sausage poached and served with mustard and bread. A Strasbourg street food staple.", "kw": ["knack", "saucisse de strasbourg"]}, {"id": "strasbourg-foie-gras", "name": "Alsatian foie gras", "local": "Foie gras d'Alsace", "icon": "🍽️", "desc": "Goose liver terrine said to have been perfected in Strasbourg in the 18th century. Served with brioche or gingerbread.", "kw": ["foie gras"]}, {"id": "strasbourg-baeckeoffe", "name": "Baeckeoffe", "local": "", "icon": "🍲", "desc": "A slow-baked casserole of marinated meats and potatoes, traditionally cooked at the baker's oven. A winter dish at Strasbourg's winstubs.", "kw": ["baeckeoffe", "baeckeofe"]}, {"id": "strasbourg-bretzel", "name": "Alsatian bretzel", "local": "Bretzel", "icon": "🥨", "desc": "A soft, salted pretzel, sold plain or with butter or cheese in Strasbourg's bakeries and market stalls.", "kw": ["bretzel", "pretzel"]}],
  stuttgart: [{"id": "stuttgart-maultaschen", "name": "Maultaschen", "local": "", "icon": "🥟", "desc": "Large filled pasta squares with minced meat, spinach and onion, served in broth or pan-fried with egg. The best-known Swabian dish.", "kw": ["maultaschen"]}, {"id": "stuttgart-linsen-spaetzle", "name": "Lentils with spaetzle", "local": "Linsen mit Spätzle", "icon": "🍲", "desc": "Stewed lentils with vinegar, soft egg noodles and a pair of Saitenwürstle sausages. Stuttgart's everyday signature plate.", "kw": ["linsen", "spätzle"]}, {"id": "stuttgart-gaisburger-marsch", "name": "Gaisburger Marsch", "local": "", "icon": "🍲", "desc": "Beef stew with potatoes and spätzle, topped with onions. Named after the Gaisburg district of Stuttgart.", "kw": ["gaisburger marsch"]}, {"id": "stuttgart-zwiebelrostbraten", "name": "Zwiebelrostbraten", "local": "", "icon": "🥩", "desc": "Pan-fried roast beef with a rich gravy and crispy onions, served with spätzle. A Swabian tavern classic.", "kw": ["rostbraten", "zwiebelrostbraten"]}, {"id": "stuttgart-filderkraut", "name": "Filderkraut", "local": "", "icon": "🥬", "desc": "Pointed cabbage from the Filder plateau, braised with bacon or served as a side. Stuttgart's own protected local cabbage.", "kw": ["filderkraut", "filder"]}],
  tarbes: [{"id": "tarbes-haricot-tarbais", "name": "Tarbais bean stew", "local": "Haricot tarbais", "icon": "🫘", "desc": "Creamy white beans grown around Tarbes under a protected label, cooked with pork or confit. Introduced in the 18th century, they are the pride of the Hautes-Pyrénées.", "kw": ["haricot tarbais", "tarbais bean"]}, {"id": "tarbes-garbure", "name": "Garbure", "local": "", "icon": "🍲", "desc": "Thick Pyrenean soup of cabbage, beans, potatoes and preserved meat, eaten as a winter meal. A staple of mountain farm kitchens in Bigorre and Béarn.", "kw": ["garbure"]}, {"id": "tarbes-porc-noir", "name": "Black pork of Bigorre", "local": "Porc noir de Bigorre", "icon": "🐖", "desc": "Ham, sausage and chops from an old black pig breed raised in the Pyrenean foothills, with its own protected label. Found at Tarbes market and local restaurants.", "kw": ["porc noir", "black pork"]}, {"id": "tarbes-gateau-broche", "name": "Gâteau à la broche", "local": "", "icon": "🎂", "desc": "Tall ring-shaped cake baked on a spit, layer by layer, giving it a rough, branched crust. A traditional Pyrenean celebration cake of the Hautes-Pyrénées.", "kw": ["gâteau à la broche", "spit cake"]}],
  toulon: [{"id": "toulon-cade", "name": "Cade", "local": "", "icon": "🥞", "desc": "A thin, tart-like chickpea-flour pancake that Toulon cooks adopted as their own. Served as a side or eaten on its own.", "kw": ["cade"]}, {"id": "toulon-tropezienne", "name": "Tarte tropézienne", "local": "", "icon": "🥧", "desc": "Brioche split and filled with cream, a specialty of the Var coast made famous at Saint-Tropez and by Brigitte Bardot. Sold in bakeries across the area.", "kw": ["tropézienne", "tropezienne"]}, {"id": "toulon-figue-sollies", "name": "Figues de Solliès", "local": "", "icon": "🟣", "desc": "Protected-origin figs from orchards around Solliès in the Var. In Toulon they turn up in fig biscuits and other local sweets.", "kw": ["figue", "figues de solliès"]}, {"id": "toulon-brouillade-truffes", "name": "Brouillade de truffes", "local": "", "icon": "🍳", "desc": "Scrambled eggs cooked gently with truffle, simple and typically from the Var. A winter dish in restaurants of the Var hinterland.", "kw": ["brouillade", "truffle"]}, {"id": "toulon-ker-moco", "name": "Ker-moco", "local": "", "icon": "🍰", "desc": "A small buckwheat cake with a heart of Solliès figs, cited as a Toulon specialty.", "kw": ["ker-moco", "ker moco"]}],
  toulouse: [{"id": "toulouse-cassoulet", "name": "Cassoulet", "local": "", "icon": "🍲", "desc": "Slow-baked casserole of white beans, Toulouse sausage and duck confit under a golden crust. The signature dish of the Toulouse area and of Languedoc.", "kw": ["cassoulet"]}, {"id": "toulouse-saucisse", "name": "Toulouse sausage", "local": "Saucisse de Toulouse", "icon": "🌭", "desc": "Coarse pork sausage seasoned only with salt and pepper, grilled and served with lentils or mash. The sausage that goes into every cassoulet.", "kw": ["saucisse de toulouse", "toulouse sausage"]}, {"id": "toulouse-violettes", "name": "Candied violets", "local": "Violettes de Toulouse", "icon": "🌸", "desc": "Violet flowers crystallised in sugar, made in Toulouse since the 19th century. Sold as sweets and used in cakes and chocolates around the city.", "kw": ["violette", "violet"]}, {"id": "toulouse-poulet-toulousaine", "name": "Chicken à la toulousaine", "local": "Poulet à la toulousaine", "icon": "🍗", "desc": "Chicken stuffed with sausage meat and roasted with olives and whole garlic cloves. A traditional Toulouse family Sunday dish.", "kw": ["toulousaine"]}],
  tours: [{"id": "tours-rillettes-de-tours", "name": "Rillettes de Tours", "local": "", "icon": "🥫", "desc": "Pork slowly cooked and shredded into a soft, golden spread, eaten on bread. Protected as a geographical indication and tied to the charcutiers of Touraine.", "kw": ["rillettes"]}, {"id": "tours-rillons", "name": "Rillons de Touraine", "local": "Rillons", "icon": "🥓", "desc": "Chunks of pork belly cooked gently until caramelised, eaten warm or cold, alone or with lentils and potatoes. A classic pairing with rillettes on Touraine charcuterie boards.", "kw": ["rillons"]}, {"id": "tours-sainte-maure", "name": "Sainte-Maure de Touraine", "local": "", "icon": "🧀", "desc": "The region's best-known goat cheese, a log with a straw running through its centre. It holds a protected designation and is sold in markets across the Tours area.", "kw": ["sainte-maure", "goat cheese"]}, {"id": "tours-nougat-de-tours", "name": "Nougat de Tours", "local": "", "icon": "🍰", "desc": "Not a nougat in the Provençal sense but a pastry: shortcrust topped with fruit compote, candied fruit and almonds. A traditional Tours sweet.", "kw": ["nougat de tours", "nougat"]}, {"id": "tours-beuchelle", "name": "Beuchelle tourangelle", "local": "Beuchelle tourangelle", "icon": "🍲", "desc": "A rich Touraine dish of sweetbreads and kidneys in a creamy mushroom sauce. Offal cooking in the old Tours style, found on traditional menus.", "kw": ["beuchelle"]}],
  trabzon: [{"id": "trabzon-akcaabat-koftesi", "name": "Akcaabat kofte", "local": "Akçaabat köftesi", "icon": "🍖", "desc": "Garlic-seasoned grilled meatballs from the Akçaabat district, just west of Trabzon. Served with bread, peppers and other sides.", "kw": ["akçaabat köfte", "akçaabat"]}, {"id": "trabzon-hamsi-tava", "name": "Hamsi tava", "local": "Hamsi tava", "icon": "🐟", "desc": "Fresh anchovies coated in cornmeal and fried crisp. Often called Trabzon's most famous dish and one of the most commonly served local plates.", "kw": ["hamsi tava", "hamsi"]}, {"id": "trabzon-kuymak", "name": "Kuymak", "local": "Kuymak", "icon": "🧀", "desc": "A molten mix of kolot cheese and cornmeal, eaten hot with cornbread. A staple of Black Sea breakfasts and the most served local dish in Trabzon menus.", "kw": ["kuymak"]}, {"id": "trabzon-pide", "name": "Trabzon pide", "local": "Trabzon pidesi", "icon": "🥖", "desc": "Thin dough topped with local cheese, often with a cracked egg and plenty of butter. A staple local bake, found throughout the city.", "kw": ["trabzon pide", "peynirli pide"]}, {"id": "trabzon-karalahana-corbasi", "name": "Black cabbage soup", "local": "Karalahana çorbası", "icon": "🥬", "desc": "Kale soup thickened with cornmeal and borlotti beans and finished with butter. Karalahana is the defining winter vegetable of the Black Sea.", "kw": ["karalahana", "karalahana çorbası"]}],
  trier: [{"id": "trier-weingraewes", "name": "Weingräwes", "local": "", "icon": "🍖", "desc": "Pork ribs braised with sauerkraut and bacon, a Moselle tavern dish.", "kw": ["weingräwes"]}, {"id": "trier-wingertspoal", "name": "Wingertspoal", "local": "Mosel-Wingertspoal", "icon": "🍖", "desc": "Marinated, spiced pork neck grilled over fire. Moselle vineyard-tavern food.", "kw": ["wingertspoal"]}, {"id": "trier-schales", "name": "Schales", "local": "", "icon": "🥔", "desc": "Baked potato dish with bacon and onion, served in slices. An old home recipe of the Moselle and Hunsrück.", "kw": ["schales"]}, {"id": "trier-mosel-aal", "name": "Smoked Moselle eel", "local": "Geräucherter Aal", "icon": "🐟", "desc": "Eel smoked and served cold with bread, a river fish tradition along the Moselle.", "kw": ["aal", "eel"]}, {"id": "trier-tresterfleisch", "name": "Tresterfleisch", "local": "", "icon": "🥩", "desc": "Pork marinated in grape pomace from the Moselle wine harvest, then pan-fried or grilled. A Trier and Moselle vineyard-tavern dish.", "kw": ["tresterfleisch", "trester"]}],
  troyes: [{"id": "troyes-andouillette", "name": "Andouillette de Troyes", "local": "", "icon": "🌭", "desc": "Pork sausage of strips of large intestine and stomach, seasoned and simmered for almost five hours, then grilled. The Aube's must-eat dish, from Troyes' butchery tradition.", "kw": ["andouillette"]}, {"id": "troyes-chaource", "name": "Chaource", "local": "", "icon": "🧀", "desc": "Soft, mild cow's-milk cheese with a flowery rind, moulded by hand with ladles in the Aube village of Chaource. It has held AOC status for over 50 years.", "kw": ["chaource"]}, {"id": "troyes-langres", "name": "Langres", "local": "", "icon": "🧀", "desc": "Cow's-milk cheese from Haute-Marne with a soft, creamy paste and a strong but not aggressive taste. A local cheese for the end of a meal.", "kw": ["langres"]}, {"id": "troyes-soumaintrain", "name": "Soumaintrain", "local": "", "icon": "🧀", "desc": "Raw cow's-milk washed-rind cheese from the Yonne, to be eaten well ripened. A farmhouse neighbour of Chaource and Saint-Florentin.", "kw": ["soumaintrain"]}, {"id": "troyes-choucroute-champagne", "name": "Champagne sauerkraut", "local": "Choucroute au champagne", "icon": "🥬", "desc": "Sauerkraut from the plain around Brienne-le-Château, cooked with champagne and served with pork. The Aube is France's second-largest sauerkraut producer.", "kw": ["choucroute", "sauerkraut"]}],
  ulm: [{"id": "ulm-zuckerbrot", "name": "Ulmer Zuckerbrot", "local": "", "icon": "🍞", "desc": "Sweet, thin yeast bread coated in sugar, a bakery specialty of Ulm since the 17th century.", "kw": ["zuckerbrot"]}, {"id": "ulm-dinnete", "name": "Dinnete", "local": "", "icon": "🥧", "desc": "Swabian Alb flatbread baked in a hot oven with cream, bacon and onions, eaten in country inns.", "kw": ["dinnete", "dennete"]}, {"id": "ulm-kartoffelsalat", "name": "Swabian potato salad", "local": "Schwäbischer Kartoffelsalat", "icon": "🥔", "desc": "Warm, soupy potato salad dressed in broth, vinegar and onion. Served with sausage in Ulm and on the Alb.", "kw": ["kartoffelsalat", "potato salad"]}, {"id": "ulm-kutteln", "name": "Saure Kutteln", "local": "", "icon": "🍲", "desc": "Tripe in a sour sauce with vinegar and onions, a Swabian inn classic of Ulm and the Alb.", "kw": ["kutteln", "tripe"]}, {"id": "ulm-ofenschlupfer", "name": "Ofenschlupfer", "local": "", "icon": "🍞", "desc": "Baked bread pudding with apples and raisins, served with vanilla sauce. A Swabian home dessert.", "kw": ["ofenschlupfer"]}],
  utrecht: [{"id": "utrecht-botersprits", "name": "Utrecht botersprits", "local": "Botersprits", "icon": "🍪", "desc": "Salty butter spritz biscuit made to Pieter Bergman's 1888 recipe, still baked and sold by a bakery near the Dom Tower.", "kw": ["botersprits", "sprits"]}, {"id": "utrecht-domtorentjes", "name": "Domtorentjes", "local": "", "icon": "🍫", "desc": "Chocolate bonbons with a creamy filling and a Dom Tower relief on top, an Utrecht sweet since 1922, sold in a bakery by the Dom.", "kw": ["domtorentje", "domtorentjes"]}, {"id": "utrecht-vockingworst", "name": "Vockingworst", "local": "", "icon": "🌭", "desc": "Liver sausage from Utrecht, served as a bar snack. A local butcher's speciality.", "kw": ["vockingworst", "leverworst"]}, {"id": "utrecht-erwtensoep", "name": "Erwtensoep", "local": "Snert", "icon": "🍲", "desc": "Thick split-pea soup with smoked sausage and pork, so thick a spoon stands up in it. A winter staple.", "kw": ["erwtensoep", "snert"]}],
  valais: [{"id": "valais-raclette", "name": "Raclette du Valais", "local": "", "icon": "🧀", "desc": "Cheese melted from the wheel and scraped over potatoes, pickles and dried meat. Valais cheese carries a protected designation and the dish is from here.", "kw": ["raclette"]}, {"id": "valais-cholera", "name": "Cholera", "local": "", "icon": "🥧", "desc": "Baked vegetable pie with leeks, potatoes, apples and cheese. The Valais dish got its name from an old cholera outbreak and is found in local restaurants.", "kw": ["cholera"]}, {"id": "valais-walliser-trockenfleisch", "name": "Valais dried meat", "local": "Walliser Trockenfleisch", "icon": "🥩", "desc": "Air-dried beef, cured ham and dried bacon with protected status. Valais plates serve it with rye bread and pickles.", "kw": ["trockenfleisch", "viande séchée", "dried meat"]}, {"id": "valais-roggenbrot", "name": "Walliser Roggenbrot", "local": "Pain de seigle valaisan", "icon": "🍞", "desc": "Dense sourdough rye bread with a protected designation, baked in the Valais. It is eaten with cheese and dried meat.", "kw": ["roggenbrot", "rye bread", "pain de seigle"]}, {"id": "valais-gsottus", "name": "Gsottus", "local": "", "icon": "🍲", "desc": "Hearty soup of dried meat, with the broth poured over rye bread and cheese. A traditional Valais mountain dish.", "kw": ["gsottus"]}],
  van: [{"id": "van-van-kahvalti", "name": "Van breakfast", "local": "Van kahvaltısı", "icon": "🍳", "desc": "A large spread of herb cheese, honey with kaymak, olives, eggs and fresh bread. Van's breakfast houses are known across Türkiye.", "kw": ["van kahvaltı", "kahvaltı"]}, {"id": "van-keledos", "name": "Keledoş", "local": "", "icon": "🥣", "desc": "Hearty stew of kurut (dried yoghurt), wheat, chickpeas and beans with meat and wild herbs, finished with butter. A registered Van speciality served in traditional restaurants.", "kw": ["keledoş"]}, {"id": "van-otlu-peynir", "name": "Van herbed cheese", "local": "Van otlu peyniri", "icon": "🧀", "desc": "Sheep's-milk cheese kneaded with wild mountain herbs such as sivri and heliz. A staple on Van breakfast tables.", "kw": ["otlu peynir", "peynir"]}, {"id": "van-kurt-kofte", "name": "Kürt köftesi", "local": "", "icon": "🧆", "desc": "Bulgur and meat dumplings served in a tomato-based soup. A Van home dish found in local lokantas.", "kw": ["kürt köftesi", "köfte"]}, {"id": "van-van-corek", "name": "Van çöreği", "local": "", "icon": "🥐", "desc": "Soft, buttery bread roll from Van's bakeries, eaten fresh with the city's famous breakfast or with tea.", "kw": ["van çöreği", "çörek"]}],
  vannes: [{"id": "vannes-andouille-guemene", "name": "Andouille de Guéméné", "local": "", "icon": "🌭", "desc": "Smoked pork andouille from Guéméné-sur-Scorff in the Morbihan, built from rings of chitterling in layers. Served cold in slices or hot with potatoes and mustard.", "kw": ["andouille de guéméné", "andouille"]}, {"id": "vannes-niniches", "name": "Niniches de Quiberon", "local": "", "icon": "🍬", "desc": "Sucette-shaped salted-butter caramels from Quiberon and sold in paper bags. Found in sweet shops and markets all around Vannes and the Gulf.", "kw": ["niniches"]}, {"id": "vannes-gateau-breton", "name": "Gâteau breton", "local": "", "icon": "🍰", "desc": "Dense, buttery shortbread-style cake made with salted butter, often with prune or apple filling, from Morbihan and Finistère. Baked in bakeries around Vannes and Carnac.", "kw": ["gâteau breton", "gateau breton"]}, {"id": "vannes-sardines-quiberon", "name": "Sardines de Quiberon", "local": "", "icon": "🐟", "desc": "Sardines from Quiberon, the Morbihan's canning town, sold fresh in season or tinned in vintage-labelled boxes. Quiberon's canneries date from the 19th century.", "kw": ["sardines", "sardine"]}, {"id": "vannes-huitres-morbihan", "name": "Gulf of Morbihan oysters", "local": "Huîtres du golfe du Morbihan", "icon": "🦪", "desc": "Oysters farmed in the sheltered Gulf of Morbihan and the Quiberon bay. Eaten raw at oyster stalls and on the quays around Vannes, Auray and Locmariaquer.", "kw": ["huîtres", "oysters"]}],
  versailles: [{"id": "versailles-paris-brest", "name": "Paris-Brest", "local": "", "icon": "🥐", "desc": "A ring of choux pastry filled with praline cream, created in 1910 at Maisons-Laffitte, in the Yvelines near Versailles.", "kw": ["paris-brest", "paris brest"]}, {"id": "versailles-petits-pois", "name": "Petits pois à la française", "local": "", "icon": "🫛", "desc": "Young peas braised with butter, lettuce and onions, a dish that became a fashion at Louis XIV's court in Versailles.", "kw": ["petits pois", "peas"]}, {"id": "versailles-rambolitain", "name": "Rambolitain", "local": "", "icon": "🍰", "desc": "Soft almond-macaron cake filled with light praline cream, topped with toasted almonds and hazelnuts. Created in Rambouillet in 1946 and now a recognised local speciality of the town.", "kw": ["rambolitain"]}, {"id": "versailles-houdan", "name": "Houdan poultry", "local": "Volaille de Houdan", "icon": "🍗", "desc": "Roast chicken or capon of the five-toed Houdan breed, an IGP-protected poultry from Houdan in the western Yvelines. Traditionally roasted for festive meals.", "kw": ["houdan"]}, {"id": "versailles-potage-st-germain", "name": "Potage Saint-Germain", "local": "", "icon": "🥣", "desc": "Smooth green soup of split or fresh peas, named after Saint-Germain-en-Laye in the Yvelines. A French classic that the Yvelines department counts among its own specialities.", "kw": ["potage saint-germain", "saint-germain"]}, {"id": "versailles-pate-chartres", "name": "Pâté de Chartres", "local": "", "icon": "🥧", "desc": "A rich game pâté baked in pastry, often with partridge, foie gras and pistachios. A Chartres speciality since the 18th century, sold by the city's charcutiers and pâtissiers.", "kw": ["pâté de chartres"]}, {"id": "versailles-mentchikoff", "name": "Mentchikoff", "local": "", "icon": "🍬", "desc": "A chocolate praline wrapped in a light vanilla meringue shell, created by a Chartres confectioner in 1893 for the Franco-Russian alliance. Sold in the city's pâtisseries.", "kw": ["mentchikoff"]}],
  wuerzburg: [{"id": "wuerzburg-meefischli", "name": "Meefischli", "local": "", "icon": "🐟", "desc": "Small river fish rolled in flour and fried crisp, eaten whole with lemon and bread. A Würzburg Main-valley specialty.", "kw": ["meefischli"]}, {"id": "wuerzburg-presssack", "name": "Fränkischer Presssack", "local": "", "icon": "🍖", "desc": "Pressed cold-cut of pork head in aspic, dressed with vinegar, oil and onions. Eaten on bread in Lower Franconian taverns.", "kw": ["presssack"]}, {"id": "wuerzburg-rhoenlamm", "name": "Rhön lamb", "local": "Rhönschaf Lamm", "icon": "🍖", "desc": "Meat of the Rhön sheep, grazed on mountain meadows, roasted or braised in Rhön inns.", "kw": ["rhönschaf", "rhön lamb", "lamm"]}, {"id": "wuerzburg-bratwurst", "name": "Franconian Bratwurst", "local": "Fränkische Bratwurst", "icon": "🌭", "desc": "Grilled pork sausage seasoned with marjoram and served in a roll, a staple of Würzburg and Lower Franconian markets.", "kw": ["bratwurst"]}],
  zuerich: [{"id": "zuerich-geschnetzeltes", "name": "Zürcher Geschnetzeltes", "local": "", "icon": "🍽️", "desc": "Thin-sliced veal in a cream, mushroom and white wine sauce, served with rösti. The city's best-known dish and a staple of its old restaurants.", "kw": ["geschnetzeltes"]}, {"id": "zuerich-bircher", "name": "Bircher muesli", "local": "Birchermüesli", "icon": "🥣", "desc": "Oats soaked with apple, yoghurt and nuts. Zürich doctor Bircher-Brenner created it around 1900, and the city's cafés still serve it.", "kw": ["bircher", "birchermüesli"]}, {"id": "zuerich-tirggel", "name": "Tirggel", "local": "", "icon": "🍪", "desc": "Very thin, hard honey biscuit pressed with old pictorial moulds. A Zürich Christmas speciality, found in bakeries from autumn.", "kw": ["tirggel"]}, {"id": "zuerich-luxemburgerli", "name": "Luxemburgerli", "local": "", "icon": "🍬", "desc": "Tiny, airy macaron-like almond meringues, made by a Zürich confectioner since the 1950s. Sold by the box in the city's shops.", "kw": ["luxemburgerli"]}, {"id": "zuerich-eintopf", "name": "Zürcher Eintopf", "local": "", "icon": "🍲", "desc": "Pork and cabbage stew, a traditional Zürich winter dish. It is served in old guild restaurants in the old town.", "kw": ["eintopf", "zürcher eintopf"]}],
  zwolle: [{"id": "zwolle-zwolse-balletjes", "name": "Zwolse balletjes", "local": "", "icon": "🍬", "desc": "Small pillow-shaped sweet candies sold in Zwolle since 1845. In flavours like mandarin and mocha.", "kw": ["balletjes"]}, {"id": "zwolle-zwollenaartjes", "name": "Zwollenaartjes", "local": "", "icon": "🥐", "desc": "Hazelnut meringue pastries with mocha cream. A Zwolle patisserie speciality.", "kw": ["zwollenaartje"]}, {"id": "zwolle-deventer-koek", "name": "Deventer koek", "local": "", "icon": "🍞", "desc": "Dense spiced cake from nearby Deventer, sliced and buttered. A classic from Overijssel.", "kw": ["deventer koek"]}, {"id": "zwolle-boerenkool-stamppot", "name": "Boerenkool stamppot", "local": "", "icon": "🥬", "desc": "Mashed potato with kale and smoked sausage. Served in winter in Zwolle restaurants.", "kw": ["boerenkool", "stamppot"]}]
};
